function trDays(s,i){return s.split(', ').map(d=>{const k=d.trim().toLowerCase();return DAYMAP[k]?DAYW[i][DAYMAP[k][0]]:d}).join(', ')}
function tr1(k,i){const d=TRD[k];if(d)return d[i];
  for(const [re,arr,mode] of PAT){const m=k.match(re);if(m){return arr[i].replace(/\$(\d)/g,(_,n)=>{const g=m[+n]||'';if(mode==='days'&&n==='1')return trDays(g,i);if(mode==='seg')return g.split(/(\s·\s*|, )/).map((x,j)=>j%2?x:(TRD[x]?TRD[x][i]:x)).join('');if(TRD[g])return TRD[g][i];if(mode==='grp'){const L={'réservé':['booked','reservado','prenotato','gebucht','reservado','محجوز'],'bloqué':['blocked','bloqueado','bloccato','gesperrt','bloqueado','محجوب'],'libre':['free','libre','libero','frei','livre','متاح'],'jour non travaillé':['day off','no laborable','non lavorativo','arbeitsfrei','folga','يوم عطلة']};if(L[g])return L[g][i]}return g})}}
  return null}
function tr(s){const i=LIDX[S.lang];if(i==null)return s;const k=s.trim();if(!k)return s;
  let r=tr1(k,i);if(r!=null)return s.replace(k,r);
  const parts=k.split(/(\s·\s*|, |\s→\s)/);if(parts.length>1){let ch=false;const out=parts.map((p,j)=>{if(j%2)return p;const t=tr1(p,i);if(t!=null){ch=true;return t}return p});if(ch)return s.replace(k,out.join(''))}
  return s}
function translateDom(){if(!S||S.lang==='fr')return;const root=document.body;if(!root||!document.createTreeWalker)return;
  const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>!n.parentNode||/^(SCRIPT|STYLE|TEXTAREA)$/.test(n.parentNode.nodeName)||(n.parentNode.closest&&n.parentNode.closest('.ugc'))?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});
  const nodes=[];let n;while(n=w.nextNode())nodes.push(n);
  nodes.forEach(x=>{const v=tr(x.nodeValue);if(v!==x.nodeValue)x.nodeValue=v});
  root.querySelectorAll('[placeholder],[aria-label],[title]').forEach(e=>['placeholder','aria-label','title'].forEach(a=>{const v=e.getAttribute(a);if(v){const t=tr(v);if(t!==v)e.setAttribute(a,t)}}))}

