function comp(id){return S.companions.find(c=>c.id===id)}
function endOf(b){return b.start+(b.hours*60+b.extMins)*M}
function dur(b){const m=b.hours*60+b.extMins;return Math.floor(m/60)+' h'+(m%60?' '+(m%60):'')}
function price(rate,hours,annex,uid){const st=S.settings,cf=feePct(uid),prest=r2(rate*hours),service=r2(prest*cf/100),tva=r2(service*st.vat/100),comm=r2(prest*(st.compFee??0)/100),ann=r2(annex||0);return{prest,service,tva,comm,cf,annexAmt:ann,total:r2(prest+service+tva+ann),payout:r2(prest-comm+ann)}}
function rating(cid){S.reviews.forEach(r=>{if(r.status==='aveugle'&&now()-r.t>14*DAY)r.status=r.fin});const r=S.reviews.filter(x=>x.to===cid&&x.status==='publie');return r.length?{avg:(r.reduce((a,x)=>a+x.stars,0)/r.length).toFixed(1),n:r.length}:{avg:'—',n:0}}
function notify(to,text){S.notifs.unshift({to,text,t:S?now():Date.now(),read:false})}
function log(actor,action,ref){S.logs.unshift({t:now(),actor,action,ref})}
function setStatus(b,s,actor,note){b.status=s;b.history.push({s,t:now(),actor,note});log(actor,ST[s][0]+(note?' — '+note:''),b.ref)}
function genCode(b){const v=String(crypto.getRandomValues(new Uint32Array(1))[0]%900000+100000);b.code={value:v,distress:distressFor(v),expires:b.start+2*H,attempts:0,used:false,locked:false}}
