    if(u.verified!=='ok')return{err:'Vérification d\'identité requise avant toute réservation.'};
    if(!c||c.verified!=='ok'||c.suspended)return{err:'Ce profil n\'est pas disponible à la réservation.'};
    if(!f.start||isNaN(start))return{err:'Indiquez la date et l\'heure.'};
    if(start<now()+24*H)return{err:'Réservation refusée : le rendez-vous doit être au moins 24 heures après maintenant (règle contrôlée côté serveur).'};
    if(hours<S.settings.minH||hours>S.settings.maxH)return{err:`Durée autorisée : de ${S.settings.minH} h à ${S.settings.maxH} h.`};
    const d=new Date(start),wd=(d.getDay()+6)%7,h=d.getHours()+d.getMinutes()/60;
    if(!c.days.includes(wd))return{err:`${c.name} n'est pas disponible le ${DAYS[wd].toLowerCase()}.`};
    if(h<c.from||h+hours>c.to)return{err:`${c.name} est disponible de ${c.from} h à ${c.to} h.`};
    if(!S.cats.find(x=>x.id===f.cat&&x.on)||!c.cats.includes(f.cat))return{err:'Activité non proposée.'};
    if(!f.place||f.place.trim().length<4)return{err:'Indiquez le lieu du rendez-vous.'};
    if(c.paused)return{err:`${c.name} ne reçoit pas de nouvelles demandes pour le moment.`};
    if((c.blocked||[]).includes(dayKey(start)))return{err:`${c.name} n'est pas disponible ce jour-là.`};
    const end=start+hours*H;
    if(S.bookings.some(b=>b.companionId===cid&&ACTIVE.includes(b.status)&&start<endOf(b)+(c.buffer||0)*M&&end+(c.buffer||0)*M>b.start))return{err:`${c.name} a déjà une réservation sur ce créneau (délai de déplacement compris).`};
