function bioEnter(){const r=S.lock.role;S.lock=null;S.role=r;S.tab='home';S.sheet=null;scrollTo(0,0)}
/* ================= V2.0 — Modifier, avis à l'aveugle, lieux publics, parrainage, calendrier, recherche admin ================= */
function seedV20(){
  const tels={u1:'06 12 34 56 78',u2:'06 23 45 67 89',u3:'07 34 56 78 90',u4:'06 45 67 89 01',u5:'07 56 78 90 12',u6:'06 67 89 01 23'};
  Object.entries(tels).forEach(([k,t])=>{if(S.users[k])S.users[k].tel=t});
  S.companions.forEach((c,i)=>{c.tel=c.tel||('07 '+String(11+i*7).padStart(2,'0')+' '+String(20+i*3).padStart(2,'0')+' '+String(40+i).padStart(2,'0')+' '+String(60+i*2).padStart(2,'0'))});
  S.settings.refAmount=10;S.users.u1.refCode='SOPHIE-SBS10';S.users.u1.refs=[{name:'Léa',t:now()-20*DAY,done:true}];
  S.gifts.push({code:'PARR-SOPHIE',amount:10,balance:10,from:'Parrainage Side by Side',to:'Sophie',msg:'Merci d\'avoir fait découvrir Side by Side à Léa.',t:now()-12*DAY,ref:true});
  S.admSearch=null;}

/* ----- Lieux publics suggérés ----- */
const PLACES={
  Paris:{musees:['Parvis du musée du Louvre (pyramide)','Entrée du musée d\'Orsay, quai Anatole-France','Centre Pompidou, piazza'],restaurants:['Café de Flore, boulevard Saint-Germain','Brasserie Bofinger, place de la Bastille','Le Train Bleu, gare de Lyon'],shopping:['Galeries Lafayette, entrée principale boulevard Haussmann','Place des Vosges, sous les arcades','Le Bon Marché, rue de Sèvres'],tourisme:['Parvis de Notre-Dame','Place du Tertre, Montmartre','Place du Trocadéro'],promenades:['Jardin du Luxembourg, fontaine Médicis','Jardin des Tuileries, côté Concorde','Canal Saint-Martin, écluse des Récollets'],_:['Hall de la gare Saint-Lazare','Place de la Concorde, obélisque','Parvis de l\'Hôtel de Ville']},
  Lyon:{musees:['Musée des Beaux-Arts, place des Terreaux','Musée des Confluences, entrée principale'],restaurants:['Les Halles Paul Bocuse','Place Bellecour, statue de Louis XIV'],shopping:['Rue de la République, place des Jacobins','Centre commercial Confluence, entrée principale'],tourisme:['Place Saint-Jean, cathédrale','Basilique de Fourvière, esplanade'],promenades:['Parc de la Tête d\'Or, entrée des Enfants du Rhône','Quais de Saône, passerelle Saint-Georges'],_:['Place Bellecour, statue de Louis XIV','Gare Part-Dieu, hall principal']},
  Nice:{musees:['Musée Matisse, Cimiez','MAMAC, place Yves-Klein'],restaurants:['Cours Saleya','Place Garibaldi'],shopping:['Avenue Jean-Médecin, place Masséna','Place Masséna, fontaine du Soleil'],tourisme:['Colline du Château, entrée','Promenade des Anglais, Hôtel Negresco'],promenades:['Promenade du Paillon','Port Lympia, quai Lunel'],_:['Place Masséna, fontaine du Soleil','Gare Nice-Ville, hall principal']},
  Bordeaux:{musees:['Cité du Vin, entrée principale','Musée d\'Aquitaine, cours Pasteur'],restaurants:['Place du Parlement','Marché des Capucins'],shopping:['Rue Sainte-Catherine, place de la Comédie','Galeries Lafayette, rue Sainte-Catherine'],tourisme:['Place de la Bourse, miroir d\'eau','Grand-Théâtre, place de la Comédie'],promenades:['Jardin public, entrée cours de Verdun','Quais des Chartrons, hangar 14'],_:['Place de la Comédie, Grand-Théâtre','Gare Saint-Jean, hall 1']}};
function placeChips(city,cat){const P=PLACES[city]||{},l=[...(P[cat]||[]),...(P._||[])].slice(0,4);if(!l.length)return'';
  return `<div class="stack" style="gap:6px"><span class="xs muted">Lieux publics suggérés :</span><div class="pchips">${l.map(x=>`<button type="button" class="pchip" data-a="place-pick" data-v="${esc(x)}">${esc(x)}</button>`).join('')}</div></div>`}

/* ----- Modifier une réservation ----- */
const canModify=b=>!LIVE&&['en_attente','acceptee','confirmee'].includes(b.status)&&b.start-now()>=24*H&&!(b.change&&b.change.status==='pending');
function modifySheet(s,head,b){const c=comp(b.companionId),hrs=s.hours||b.hours,days=freeDays(c,hrs),dk=days.includes(dayKey(b.start))?dayKey(b.start):days[0],ts=dk?slots(c,dk,hrs):[];
  return head(`Modifier ${b.ref}`,`${esc(c.name)} · ${esc(catName(b.cat))}`)+`<form class="stack" data-form="modify" data-id="${b.id}" data-cid="${c.id}">
  <div class="card sm">Actuellement : <b>${fdt(b.start)}</b> · ${b.hours} h · <span class="ugc">${esc(b.place)}</span></div>
  <span class="fl">Nouvelle date et heure</span>${days.length?`<div class="row" style="flex-wrap:nowrap"><select id="b-day" aria-label="Jour" style="flex:1.7;min-width:0">${days.map(k=>`<option value="${k}" ${k===dk?'selected':''}>${fday(k)}</option>`).join('')}</select><select id="b-start" name="start" aria-label="Heure" style="flex:1;min-width:0">${ts.map(t=>`<option value="${dtLocal(t)}" ${t===b.start?'selected':''}>${fhour(t)}</option>`).join('')}</select></div>`:'<p class="note t-warn sm">Aucun autre créneau libre.</p>'}
  <label class="fl" for="b-h">Durée</label><select id="b-h" name="hours">${Array.from({length:S.settings.maxH-S.settings.minH+1},(_,i)=>i+S.settings.minH).map(n=>`<option value="${n}" ${n===+hrs?'selected':''}>${n} h</option>`).join('')}</select>
  <label class="fl" for="b-place">Lieu de rendez-vous</label><textarea id="b-place" name="place" rows="3" class="placebox">${esc(b.place)}</textarea>${placeChips(c.city,b.cat)}
  <p class="xs muted">${b.status==='en_attente'?'La demande n\'est pas encore acceptée : la modification s\'applique tout de suite.':`${esc(c.name)} doit accepter la modification. Si le prix change, la différence est débitée ou remboursée automatiquement.`}</p>
  <p class="note t-bad sm" id="md-err" hidden></p><button class="btn pri full">${b.status==='en_attente'?'Enregistrer la modification':'Envoyer la demande de modification'}</button></form>`}
function applyChange(b,ch){const c=comp(b.companionId),ex=(b.services||[]).length?((c.prestige&&c.prestige.extras)||[]).filter(x=>b.services.includes(x[0])).reduce((a,x)=>a+x[1],0):0;
  const p=price(c.rate+ex,ch.hours,b.annex||0,b.clientId),diff=r2(p.total-b.total);
  Object.assign(b,{start:ch.start,hours:ch.hours,place:ch.place},p);
  if(b.mission)b.mission={v:(b.mission.v||1)+1,signed:b.mission.signed};
  if(b.paid&&diff){S.ledger.push({t:now(),type:diff>0?'Encaissement (modification)':'Remboursement',ref:b.ref,amount:diff>0?diff:diff})}
  return diff}
function v20Submit(k,f,d){
  if(k==='modify'){const b=S.bookings.find(x=>x.id===f.dataset.id),st=d.start?new Date(d.start).getTime():NaN,place=(d.place||'').trim(),err=m=>{const p=document.getElementById('md-err');p.textContent=tr(m);p.hidden=false;return 'stop'};
    if(!st)return err('Choisissez un créneau.');if(place.length<4)return err('Indiquez le lieu du rendez-vous.');
    if(st===b.start&&+d.hours===b.hours&&place===b.place)return err('Aucun changement.');
    const ch={start:st,hours:+d.hours,place,t:now()};
    if(b.status==='en_attente'){applyChange(b,ch);log('Sophie','Réservation modifiée',b.ref);notify('companion',`${b.ref} modifiée par ${partyName(b,'client')} : ${fdt(st)}.`);S.sheet=null;toast('Réservation modifiée.');return true}
    b.change={...ch,status:'pending'};log('Sophie','Demande de modification',b.ref);notify('companion',`${partyName(b,'client')} demande à modifier ${b.ref} : ${fdt(st)}, ${ch.hours} h.`);S.sheet=null;toast(`Demande envoyée à ${comp(b.companionId).name}.`);return true}
  if(k==='adm-phone'){const q=(d.tel||'').replace(/\D/g,'').replace(/^33/,'0');if(q.length<4){toast('Saisissez au moins 4 chiffres.',true);return 'stop'}
    const hit=[...Object.values(S.users).map(u=>({kind:'client',id:u.id,name:u.name,tel:u.tel})),...S.companions.map(c=>({kind:'companion',id:c.id,name:c.name,tel:c.tel}))].filter(x=>x.tel&&x.tel.replace(/\D/g,'').includes(q));
    S.admSearch={q:d.tel,hits:hit};return true}
  return false}
function chgHtml(b,role){const ch=b.change;if(!ch||ch.status!=='pending')return'';const c=comp(b.companionId);
  return `<div class="note t-warn sm">Modification demandée : <b>${fdt(ch.start)}</b> · ${ch.hours} h · <span class="ugc">${esc(ch.place)}</span>${role==='client'?` — en attente de ${esc(c.name)}`:''}</div>`}

/* ----- Calendrier ----- */
function calLink(b){const z=t=>new Date(t).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),c=comp(b.companionId),u=S.users[b.clientId];
  const who=S.role==='client'?c.name:u.name,q=new URLSearchParams({action:'TEMPLATE',text:`Side by Side · ${who} · ${catName(b.cat)}`,dates:`${z(b.start)}/${z(endOf(b))}`,location:b.place,details:`Réservation ${b.ref}`});
  return `<a class="btn ghost" href="https://calendar.google.com/calendar/render?${q}" target="_blank" rel="noopener">${tr('Ajouter au calendrier')}</a>`}

/* ----- Parrainage ----- */
function refCard(){const u=S.users.u1,a=S.settings.refAmount||10;if(S.biz)return'';
  return `<section class="section"><div class="card stack"><span class="lbl" style="color:var(--gold)">Parrainage</span>
  <p class="sm">Offrez ${eur(a)} à vos proches sur leur première réservation. Vous recevez ${eur(a)} dès qu'elle est terminée.</p>
  <div class="row" style="flex-wrap:nowrap"><span class="num refcode grow sel">${u.refCode}</span><button class="btn" data-a="ref-copy">Copier</button></div>
  <div class="row sm"><span class="grow">${(u.refs||[]).length} filleul(s) · ${eur((u.refs||[]).filter(x=>x.done).length*a)} gagnés</span></div>
  ${(u.refs||[]).map(r=>`<div class="row xs muted"><span class="grow">${esc(r.name)}</span><span>${r.done?'Première réservation terminée':'Inscrit(e)'}</span></div>`).join('')}
  <p class="xs muted">Vos gains apparaissent dans vos cartes cadeaux et s'utilisent au moment du paiement.</p></div></section>`}

/* ----- Recherche admin par téléphone ----- */
function aPhoneSearch(){const R=S.admSearch;
  const res=R?(R.hits.length?R.hits.map(h=>{const bs=S.bookings.filter(b=>h.kind==='client'?b.clientId===h.id:b.companionId===h.id).sort((a,b)=>b.start-a.start),last=bs[0];
    return `<div class="card stack"><div class="row"><b class="grow">${esc(h.name)}</b><span class="pill">${h.kind==='client'?'Client':'Accompagnateur'}</span></div><span class="num xs">${esc(h.tel)}</span>
    ${last?`<div class="row sm"><span class="grow">Dernière mission : <span class="num">${last.ref}</span> · ${fdt(last.start)}</span>${pill(last.status)}</div><button class="btn pri" data-a="detail" data-id="${last.id}">Ouvrir la dernière mission</button>`:'<p class="sm muted">Aucune mission.</p>'}</div>`}).join(''):'<div class="empty">Aucun compte avec ce numéro.</div>'):'';
  return `<section class="section"><h3>Recherche par téléphone</h3><form class="row" data-form="adm-phone" style="flex-wrap:nowrap"><input name="tel" type="tel" placeholder="06 12 34 56 78" aria-label="Numéro de téléphone" value="${R?esc(R.q):''}" style="flex:1;min-width:0"><button class="btn pri">Rechercher</button></form>${res}</section>`}

EXTRA_SHEETS.modify=(s,h,b)=>modifySheet(s,h,b);
function v20Click(a,el,id,v,b){switch(a){
  case'modify':open('modify',{id});return true;
  case'adm-forgot':case'adm-resend':admSendCode();if(a==='adm-resend')toast('Nouveau code envoyé.');return true;
  case'adm-reset-cancel':S.admReset=null;return true;
  case'legaldoc':open('legaldoc',{doc:v});return true;
  case'chg-yes':{const ch=b.change;if(!ch)return true;const st=ch.start,busy=S.bookings.some(x=>x.id!==b.id&&x.companionId===b.companionId&&ACTIVE.includes(x.status)&&st<x.start+(x.hours*60+x.extMins)*M&&st+ch.hours*H>x.start);
    if(busy){toast('Ce créneau n\'est plus libre.',true);return true}
    const diff=applyChange(b,ch);b.change=null;log(comp(b.companionId).name,'Modification acceptée',b.ref);
    notify('client',`${comp(b.companionId).name} a accepté la modification de ${b.ref}.`+(b.paid&&diff?(diff>0?` ${eur(diff)} débités sur votre carte.`:` ${eur(-diff)} remboursés.`):''));toast('Modification acceptée.');return true}
  case'chg-no':b.change=null;log(comp(b.companionId).name,'Modification refusée',b.ref);notify('client',`${comp(b.companionId).name} a refusé la modification de ${b.ref}. La réservation reste inchangée.`);toast('Modification refusée. La réservation reste inchangée.');return true;
  case'place-pick':{const t=el.closest('form')&&el.closest('form').querySelector('#b-place');if(t){t.value=v;t.focus()}return false}
  case'ref-copy':{const code=S.users.u1.refCode;try{navigator.clipboard.writeText(code).then(()=>toast('Code copié.'),()=>toast(code))}catch(e){toast(code)}return false}
  case'gift-quick':{const g=S.gifts.find(x=>x.code===v);if(b&&g){b.giftCode=g.code;b.giftUsed=r2(Math.min(g.balance,b.total));toast('Carte cadeau appliquée.')}return true}
  default:return false}}

/* ================= V2.1 — Pages juridiques ================= */
const LEGAL_CO={name:'Zyntell',form:'SAS à associé unique (SASU), en cours d\'immatriculation',addr:'14 rue de Binche, 76150 Maromme',tel:'07 82 80 01 01',mail:'contact@zyntell.fr',brand:'Side by Side',date:'3 novembre 2026'};
const LEGAL_LIST=[['mentions','Mentions légales'],['cgu','Conditions générales d\'utilisation'],['cgv','Conditions générales de vente'],['confidentialite','Politique de confidentialité'],['cookies','Cookies et traceurs'],['charte','Charte de confiance et de sécurité'],['contrat','Contrat accompagnateur']];
function legalDoc(id){const C=LEGAL_CO,st=S.settings,R=st.cancel,h=(t,b)=>`<h3>${t}</h3>${b}`,p=t=>`<p>${t}</p>`,ul=a=>`<ul>${a.map(x=>`<li>${x}</li>`).join('')}</ul>`;
  const ident=`${C.name}, ${C.form}, dont le siège est situé ${C.addr}. Téléphone : ${C.tel}. E-mail : ${C.mail}`;
  switch(id){
  case'mentions':return h('Éditeur',p(`L'application ${C.brand} est éditée par ${ident}.`)+p('SIREN et numéro de TVA intracommunautaire : communiqués dès l\'immatriculation.')+p(`Directeur de la publication : le président de ${C.name}.`))
    +h('Hébergement',p('Les données de l\'application sont hébergées par Supabase, Inc., sur des serveurs situés dans l\'Union européenne. Les paiements sont traités par Stripe Payments Europe, Ltd.'))
    +h('Contact',p(`Pour toute question : ${C.mail} ou ${C.tel}. Ligne sécurité, 7 jours sur 7 : ${C.tel}.`))
    +h('Propriété intellectuelle',p(`La marque ${C.brand}, le logo, les textes et l'interface sont la propriété de ${C.name}. Toute reproduction sans autorisation écrite est interdite.`))
    +h('Signalement de contenus illicites',p(`Tout contenu illicite peut être signalé depuis l'application (bouton « Signaler ») ou à ${C.mail}. ${C.name} traite chaque signalement dans les meilleurs délais, conformément au règlement européen sur les services numériques.`));
  case'cgu':return h('1. Objet',p(`Les présentes conditions régissent l'utilisation de l'application ${C.brand}, éditée par ${C.name}. ${C.brand} propose des prestations d'accompagnement social, culturel, touristique et professionnel : visites, musées, sorties, dîners d'affaires, événements, accompagnement de personnes âgées.`))
    +h('2. Ce que n\'est pas Side by Side',p(`${C.brand} n'est ni un site de rencontres ni un service d'escorte. Tout service intime ou sexuel, toute sollicitation de cette nature et toute activité illégale sont strictement interdits. Toute infraction entraîne la suspension immédiate et définitive du compte, sans remboursement, et peut être signalée aux autorités.`))
    +h('3. Comptes',ul(['L\'inscription est réservée aux personnes majeures (18 ans et plus).','L\'identité de chaque membre est vérifiée par un prestataire spécialisé (pièce d\'identité et selfie vidéo) avant toute réservation.','Les accompagnateurs passent en plus un entretien vidéo avec l\'équipe Side by Side, font valider leurs photos et déposent une attestation d\'assurance responsabilité civile à jour couvrant leur activité rémunérée.','Chaque membre garantit l\'exactitude de ses informations et la confidentialité de son mot de passe.','Un seul compte par personne.']))
    +h('4. Rôle de Zyntell',p(`${C.name} est le prestataire des services vendus sur ${C.brand}. Pour les réaliser, ${C.name} fait appel à des accompagnateurs indépendants, qui interviennent en tant que sous-traitants et restent libres d'accepter ou de refuser chaque mission.`))
    +h('5. Photos et profils',p('Les photos doivent être réelles, récentes et représenter uniquement le membre, sans retouche ni création par intelligence artificielle. Une photo suspecte est masquée en attendant une vérification humaine. Une fois validées, les photos sont verrouillées.'))
    +h('6. Sécurité',ul(['Premier rendez-vous recommandé dans un lieu public.','Code de rencontre à usage unique, validation du début et de la fin de mission par les deux parties.','Bouton SOS, code de détresse et point sécurité pendant la mission.','En cas de danger, appelez d\'abord le 112.']))
    +h('7. Non-contournement',p(`Pendant 12 mois après une première rencontre via ${C.brand}, clients, entreprises et accompagnateurs s'engagent à ne pas organiser de prestation directement entre eux, en dehors de l'application. En cas de manquement, ${C.name} peut facturer des frais de mise en relation et suspendre les comptes concernés.`))
    +h('8. Avis',p('Seules les prestations réellement terminées peuvent être évaluées. Les avis sont publiés « à l\'aveugle » : chacun ne voit l\'avis de l\'autre qu\'après avoir donné le sien, ou au bout de 14 jours. Les commentaires sont modérés ; un avis injurieux, discriminatoire ou sans rapport avec la prestation est retiré.'))
    +h('9. Suspension',p('En cas de manquement aux présentes conditions, un compte peut être suspendu. Toute suspension définitive est décidée par un membre de l\'équipe, jamais par un système automatique seul, et peut être contestée auprès de '+C.mail+'.'))
    +h('10. Responsabilité',p(`${C.name} met tout en œuvre pour assurer la sécurité et la qualité des prestations. Chaque membre reste responsable de son comportement et de ses propres biens.`))
    +h('11. Modification et droit applicable',p('Les membres sont informés de toute modification des conditions au moins 15 jours avant son entrée en vigueur. Les présentes conditions sont soumises au droit français.'));
  case'cgv':return h('1. Prix',p(`Chaque accompagnateur affiche un tarif horaire. Au moment de la réservation, des frais de service sont ajoutés. Le récapitulatif indique le prix de la prestation, les frais de service et le total avant tout paiement. Les membres Privilège bénéficient de frais de service réduits. Les prix sont exprimés en euros, toutes taxes comprises.`))
    +h('2. Réservation et paiement',ul(['Réservation au moins 24 heures à l\'avance, sous réserve d\'acceptation par l\'accompagnateur.','Aucun débit avant l\'acceptation et la signature de la fiche de mission.','Le paiement est traité par Stripe. Le montant est conservé jusqu\'à la fin de la prestation, validée par les deux parties.','Cartes cadeaux et crédits de parrainage utilisables au paiement, valables 1 an.']))
    +h('3. Déroulement',p('La mission commence quand le client et l\'accompagnateur ont tous deux validé « Je commence la mission », et se termine quand les deux ont validé « Je termine la mission ». L\'heure et le lieu sont enregistrés. Une prolongation peut être demandée pendant la mission et doit être acceptée et payée.'))
    +h('4. Modification',p('Le client peut demander à modifier l\'heure, la durée ou le lieu au plus tard 24 heures avant le rendez-vous. Si la demande est déjà acceptée, l\'accompagnateur doit valider la modification. La différence de prix est débitée ou remboursée automatiquement.'))
    +h('5. Annulation',ul([`Plus de 48 heures avant : ${R.early} % remboursé.`,`Entre 24 et 48 heures avant : ${R.mid} % remboursé.`,`Moins de 24 heures avant : ${R.late} % remboursé.`,'Membres Privilège : remboursement intégral jusqu\'à 24 heures avant.',`Annulation par l'accompagnateur : ${R.companion} % remboursé.`,`Annulation pour raison de sécurité : ${R.safety} % remboursé.`]))
    +h('6. Absence',p(`Si le client est absent sans prévenir, l'accompagnateur reçoit une indemnité de ${st.noShowPct||50} % de la prestation après vérification. Le client peut contester sous 48 heures.`))
    +h('7. Droit de rétractation',p('Les prestations de loisirs fournies à une date déterminée ne sont pas soumises au droit de rétractation (article L221-28 du Code de la consommation) ; les conditions d\'annulation ci-dessus s\'appliquent. L\'abonnement Privilège peut être résilié à tout moment et bénéficie d\'un délai de rétractation de 14 jours.'))
    +h('8. Abonnement Privilège',p(`${eur(st.privPrice)} par mois, sans engagement, prélevé chaque mois à la même date et résiliable à tout moment depuis le compte.`))
    +h('9. Comptes entreprise',p('L\'enregistrement d\'une carte bancaire (empreinte bancaire) est obligatoire. Chaque réservation est débitée sur cette carte dans la limite du plafond mensuel choisi, et une facture récapitulative est émise chaque mois.'))
    +h('10. Pourboire',p('Le pourboire est facultatif et reversé en totalité à l\'accompagnateur.'))
    +h('11. Factures',p(`${C.name} émet une facture pour chaque prestation terminée, disponible dans l'application.`))
    +h('12. Réclamations et médiation',p(`Toute réclamation peut être adressée à ${C.mail}. Les litiges sur une prestation sont traités dans un délai de ${st.disputeDays} jours. En l'absence d'accord, le client peut recourir gratuitement à un médiateur de la consommation, dont les coordonnées sont communiquées sur simple demande, ou à la plateforme européenne de règlement des litiges.`))
    +h('13. Droit applicable',p('Les présentes conditions sont soumises au droit français.'));
  case'confidentialite':return h('Responsable du traitement',p(ident+'.'))
    +h('Données collectées',ul(['Identité : nom, prénom, date de naissance, photo, vérification d\'identité.','Coordonnées : e-mail, téléphone, ville.','Réservations, messages, avis, signalements.','Paiement : traité par Stripe ; Side by Side ne conserve jamais votre numéro de carte.','Position : uniquement pendant une alerte SOS, et seulement si vous l\'avez autorisé.']))
    +h('Pourquoi',ul(['Fournir le service et exécuter les réservations (contrat).','Vérifier l\'identité et l\'âge, assurer la sécurité (intérêt légitime et obligation légale).','Facturation et comptabilité (obligation légale).','Partage de position en cas de SOS (consentement).','Informations sur les nouveautés (consentement, désactivable à tout moment).']))
    +h('Vérification d\'identité et des photos',p('La vérification d\'identité est réalisée par un prestataire spécialisé, qui compare votre pièce d\'identité et un selfie vidéo. Side by Side ne conserve pas l\'image de votre pièce d\'identité. Une analyse automatique peut signaler une photo suspecte ; la décision finale est toujours prise par une personne de l\'équipe.'))
    +h('Durées de conservation',ul(['Compte : pendant toute son utilisation, puis 3 ans après la dernière activité.','Factures et pièces comptables : 10 ans.','Messages et historique des réservations : 5 ans (preuve en cas de litige).','Position SOS : 60 minutes de partage, conservée ensuite uniquement si un incident est ouvert.']))
    +h('Destinataires',p('Vos données sont accessibles à l\'équipe Side by Side et, pour une réservation, à l\'autre partie (prénom, photo, informations utiles). Prestataires : Supabase (hébergement), Stripe (paiement), prestataire de vérification d\'identité, envoi de SMS et d\'e-mails. Si des données sont transférées hors de l\'Union européenne, elles sont protégées par les clauses contractuelles types de la Commission européenne.'))
    +h('Vos droits',p(`Vous pouvez accéder à vos données, les rectifier, les effacer, les récupérer, limiter ou refuser leur utilisation, et retirer votre consentement à tout moment, en écrivant à ${C.mail}. Réponse sous un mois. Vous pouvez aussi saisir la CNIL (cnil.fr).`))
    +h('Mineurs',p('Le service est réservé aux personnes majeures. Aucun compte ne peut être créé par une personne de moins de 18 ans.'));
  case'cookies':return h('Traceurs utilisés',ul(['Strictement nécessaires : connexion, sécurité, langue choisie. Ils ne demandent pas de consentement.','Mesure d\'audience : uniquement si vous l\'acceptez, pour améliorer l\'application.']))
    +h('Votre choix',p('Vous pouvez accepter ou refuser les traceurs non nécessaires à tout moment depuis les paramètres de votre compte. Les refuser ne limite pas l\'utilisation de l\'application.'))
    +h('Durée',p('Votre choix est conservé 6 mois.'));
  case'charte':return h('Notre engagement',p(`${C.brand} réunit des personnes pour des moments culturels, sociaux et professionnels, dans le respect et la sécurité.`))
    +h('Interdit',ul(['Tout service intime ou sexuel, et toute sollicitation de cette nature.','Toute activité illégale.','Le harcèlement, les insultes, les discriminations.','La consommation excessive d\'alcool et toute substance illicite pendant une mission.','Les fausses photos et les faux profils.','Organiser une prestation en dehors de l\'application.']))
    +h('Recommandé',ul(['Premier rendez-vous dans un lieu public.','Contact de confiance renseigné dans votre compte.','Valider ensemble le début et la fin de chaque mission.','Signaler tout comportement inapproprié.']))
    +h('En cas de problème',p(`Bouton SOS dans chaque réservation, ligne sécurité au ${C.tel}, et 112 en cas d'urgence.`));
  case'contrat':return h('Parties',p(`Entre ${ident}, ci-après « Zyntell », et l'accompagnateur inscrit sur ${C.brand}, exerçant en tant que travailleur indépendant (micro-entrepreneur ou équivalent), ci-après « l'Accompagnateur ».`))
    +h('1. Objet',p(`Zyntell confie à l'Accompagnateur, en sous-traitance, la réalisation de prestations d'accompagnement vendues sur ${C.brand}.`))
    +h('2. Indépendance',ul(['L\'Accompagnateur est libre d\'accepter ou de refuser chaque mission, sans justification.','Il fixe lui-même son tarif horaire, ses disponibilités et les activités qu\'il propose.','Il organise librement sa prestation, dans le respect de la charte.','Il peut travailler pour d\'autres clients ou plateformes. Aucun lien de subordination n\'existe entre les parties.']))
    +h('3. Rémunération',p(`Pour chaque mission, l'Accompagnateur perçoit le prix de la prestation diminué d'une commission de ${st.compFee} % au profit de Zyntell. Le montant net est affiché dans l'application avant l'acceptation. Il est versé sur son compte bancaire après la validation de fin de mission par les deux parties. Les pourboires lui sont reversés en totalité. Zyntell lui remet une facture récapitulative pour chaque mission.`))
    +h('4. Obligations de l\'Accompagnateur',ul(['Déclarer ses revenus et payer ses cotisations sociales et impôts.','Disposer d\'une assurance responsabilité civile couvrant son activité rémunérée et déposer dans l\'application une attestation à jour (obligatoire : sans attestation valide, aucune réservation ne peut être reçue).','Publier uniquement des photos réelles de lui-même.','Respecter la charte de confiance et de sécurité.','Valider le début et la fin de chaque mission dans l\'application.']))
    +h('5. Non-contournement',p('Pendant 12 mois après une mission, l\'Accompagnateur s\'interdit de proposer ses services directement à un client rencontré via '+C.brand+'. En cas de manquement, Zyntell peut facturer des frais de mise en relation et mettre fin au contrat.'))
    +h('6. Confidentialité',p('L\'Accompagnateur garde confidentielles les informations sur les clients, notamment leurs coordonnées et leurs habitudes.'))
    +h('7. Durée et fin du contrat',p('Le contrat est conclu pour une durée indéterminée. Chaque partie peut y mettre fin à tout moment, sous réserve d\'honorer les missions déjà acceptées. Zyntell peut le résilier immédiatement en cas de manquement grave à la charte.'));
  default:return''}}
function legalListHtml(){return `<div class="stack" style="gap:6px;margin-top:10px">${LEGAL_LIST.filter(([k])=>k!=='contrat'||S.role!=='client').map(([k,t])=>`<button class="btn ghost legalbtn" data-a="legaldoc" data-v="${k}"><span class="grow">${t}</span><span aria-hidden="true">→</span></button>`).join('')}<p class="xs muted">${LEGAL_CO.name} · ${LEGAL_CO.addr} · ${LEGAL_CO.tel} · ${LEGAL_CO.mail}</p></div>`}
function legalSheet(s,head){const t=(LEGAL_LIST.find(x=>x[0]===s.doc)||[])[1]||'';
  return head(t,`Version du ${LEGAL_CO.date}`)+`${S.lang!=='fr'?'<div class="note t-gold sm">Ce document est disponible en français. La version française fait foi.</div>':''}<article class="legaldoc ugc" lang="fr">${legalDoc(s.doc)}</article><button class="btn pri full" data-a="close">Fermer</button>`}
EXTRA_SHEETS.legaldoc=(s,h)=>legalSheet(s,h);



function pwRuleErr(nw,nw2){nw=String(nw||'');
  if(nw.length<12||!/[A-Z]/.test(nw)||!/[a-z]/.test(nw)||!/\d/.test(nw)||!/[^A-Za-z0-9]/.test(nw)||/\s/.test(nw))return '12 caractères minimum, avec une majuscule, une minuscule, un chiffre et un caractère spécial, sans espace.';
  if(nw!==String(nw2||''))return 'Les deux mots de passe ne correspondent pas.';
  if(/(.)\1{3}/.test(nw)||/sidebyside|zyntell|password|motdepasse|azerty|qwerty|123456/i.test(nw))return 'Mot de passe trop facile à deviner. Choisissez-en un autre.';
  return ''}
/* Mot de passe administrateur oublié : code envoyé par SMS au numéro de l'administrateur */
const ADM_PHONE_MASK='07 •• •• 01 01';
function admSendCode(){S.admReset={step:'sms',code:String(crypto.getRandomValues(new Uint32Array(1))[0]%900000+100000),tries:0};setTimeout(()=>{smsBanner(S.admReset.code);const i=document.getElementById('ar-code');i&&i.focus()},60)}
function admResetHtml(){const R=S.admReset;
  return `<section class="section" style="max-width:420px;margin:0 auto"><h2>Mot de passe oublié</h2>${R.step==='sms'
  ?`<p class="muted">Un code de vérification a été envoyé par SMS au numéro de l'administrateur (${ADM_PHONE_MASK}).</p><form class="card stack" data-form="adm-reset-sms"><div class="field"><label for="ar-code">Code reçu par SMS</label><input id="ar-code" name="code" inputmode="numeric" maxlength="6" autocomplete="one-time-code"></div><p class="note t-bad sm" id="ar-err" hidden></p><button class="btn pri full">Vérifier</button><button type="button" class="btn ghost" data-a="adm-resend">Renvoyer le code</button></form>`
  :`<p class="muted">Choisissez votre nouveau mot de passe administrateur.</p><form class="card stack" data-form="adm-reset-new"><div class="field"><label for="ar-new">Nouveau mot de passe</label><input id="ar-new" name="nw" type="password" autocomplete="new-password"></div><div class="field"><label for="ar-new2">Confirmez le nouveau mot de passe</label><input id="ar-new2" name="nw2" type="password" autocomplete="new-password"></div><p class="xs muted">12 caractères minimum, avec au moins une majuscule, une minuscule, un chiffre et un caractère spécial (! ? @ # $ % & * …).</p><p class="note t-bad sm" id="ar-err" hidden></p><button class="btn pri full">Enregistrer et me connecter</button></form>`}
  <button class="btn ghost full" data-a="adm-reset-cancel">Annuler</button></section>`}
function admResetSubmit(k,d){const e=m=>{const p=document.getElementById('ar-err');p.textContent=tr(m);p.hidden=false;return 'stop'},R=S.admReset;if(!R)return true;
  if(k==='adm-reset-sms'){if(String(d.code||'').replace(/\D/g,'')!==R.code){R.tries++;if(R.tries>=5){S.admReset=null;toast('Trop d\'essais. Recommencez.',true);return true}return e('Code incorrect.')}R.step='new';return true}
  const pe=pwRuleErr(d.nw,d.nw2);if(pe)return e(pe);
  sha256(String(d.nw)).then(h=>{try{localStorage.setItem(ADM_KEY,h)}catch(x){e('Impossible d\'enregistrer le code sur cet appareil.');return}
    S.admReset=null;S.adminOk=true;S.mfaTries=0;log('Administrateur Side by Side','Mot de passe administrateur réinitialisé par SMS','—');toast('Mot de passe modifié. Vous êtes connecté.');render()});
  return 'stop'}
/* Code d'accès administrateur personnel (enregistré chiffré sur l'appareil) */
const ADM_KEY='sbs_admin_code_hash';
async function sha256(t){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode('sbs|'+t));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function adminHash(){try{return localStorage.getItem(ADM_KEY)}catch(e){return null}}
async function adminCheck(code){code=String(code||'');const h=adminHash();if(!h)return false;try{return (await sha256(code))===h}catch(e){return false}}
function aAdminCode(){return `<form class="card stack" data-form="admcode"><h3>Accès administrateur</h3><p class="xs muted">Votre mot de passe personnel est actif sur cet appareil.</p>
  <div class="field"><label for="ac-old">Code ou mot de passe actuel</label><input id="ac-old" name="old" type="password" autocomplete="current-password"></div>
  <div class="field"><label for="ac-new">Nouveau mot de passe</label><input id="ac-new" name="nw" type="password" autocomplete="new-password"></div><div class="field"><label for="ac-new2">Confirmez le nouveau mot de passe</label><input id="ac-new2" name="nw2" type="password" autocomplete="new-password"></div>
  <p class="xs muted">12 caractères minimum, avec au moins une majuscule, une minuscule, un chiffre et un caractère spécial (! ? @ # $ % & * …).</p>
  <p class="note t-bad sm" id="ac-err" hidden></p><button class="btn pri">Changer le mot de passe</button></form>`}
function admCodeSubmit(d){const e=m=>{const p=document.getElementById('ac-err');p.textContent=tr(m);p.hidden=false},nw=String(d.nw||'');
  adminCheck(d.old).then(async ok=>{
    if(!ok)return e('Code actuel incorrect.');
    {const pe=pwRuleErr(nw,d.nw2);if(pe)return e(pe)}
    try{localStorage.setItem(ADM_KEY,await sha256(nw))}catch(x){return e('Impossible d\'enregistrer le code sur cet appareil.')}
    log('Administrateur Side by Side','Code d\'accès administrateur modifié','—');toast('Mot de passe modifié. Utilisez-le à votre prochaine connexion.');render()});
  return 'stop'}
/* ================= V2.2 — Réserver pour un proche, compte rendu, mode grand confort ================= */
const REL=['Parent','Grand-parent','Conjoint(e)','Frère ou sœur','Ami(e)','Autre'];
const NEEDS=[['mobilite','Se déplace lentement'],['canne','Canne ou déambulateur'],['fauteuil','Fauteuil roulant'],['audition','Entend mal'],['vue','Voit mal'],['memoire','Troubles de la mémoire']];
function forWhoHtml(){return `<div class="card stack forwho"><span class="fl">Pour qui est cette sortie ?</span>
  <div class="seg2"><label><input type="radio" name="who" value="moi" checked><span>Pour moi</span></label><label><input type="radio" name="who" value="proche"><span>Pour un proche</span></label></div>
  <div class="prochebox stack">
    <p class="xs muted">Vous réservez et payez ; votre proche vit la sortie. Vous êtes prévenu(e) au début et à la fin, et recevez un compte rendu de l'accompagnateur.</p>
    <div class="two"><div class="field"><label for="pr-name">Prénom du proche</label><input id="pr-name" name="pr_name" maxlength="40" autocomplete="off"></div>
    <div class="field"><label for="pr-rel">Lien</label><select id="pr-rel" name="pr_rel">${REL.map(r=>`<option>${r}</option>`).join('')}</select></div></div>
    <div class="field"><label for="pr-tel">Téléphone du proche</label><input id="pr-tel" name="pr_tel" type="tel" placeholder="06 12 34 56 78"><span class="xs muted">Le code de rencontre lui est envoyé par SMS.</span></div>
    <span class="fl">Besoins particuliers</span><div class="days">${NEEDS.map(([k,l])=>`<label><input type="checkbox" name="pr_needs" value="${k}">${l}</label>`).join('')}</div>
    <div class="field"><label for="pr-info">Informations utiles pour l'accompagnateur (facultatif)</label><textarea id="pr-info" name="pr_info" maxlength="400" placeholder="Habitudes, centres d'intérêt, personne à prévenir…"></textarea></div>
    <label class="row sm"><input type="checkbox" name="pr_ok"> Mon proche est informé et d'accord pour cette sortie</label>
  </div></div>`}
function forWhoCheck(f){if(f.who!=='proche')return null;const name=(f.pr_name||'').trim(),tel=(f.pr_tel||'').replace(/[\s.-]/g,'');
  if(name.length<2)return{err:'Indiquez le prénom de votre proche.'};
  if(!/^(?:\+33|0)[1-9]\d{8}$/.test(tel))return{err:'Indiquez un numéro de téléphone valide pour votre proche.'};
  if(!f.pr_ok)return{err:'Confirmez que votre proche est d\'accord pour cette sortie.'};
  return{fw:{name,rel:REL.includes(f.pr_rel)?f.pr_rel:'Autre',tel:(f.pr_tel||'').trim(),needs:(f.needs||[]).filter(k=>NEEDS.some(n=>n[0]===k)),info:(f.pr_info||'').trim().slice(0,400)}}}
const needLabel=k=>(NEEDS.find(n=>n[0]===k)||[,''])[1];
function forWhoBlock(b,role){const w=b.forWho;if(!w||role==='admin')return'';
  return `<div class="note t-gold sm stack" style="gap:4px"><div><b>${role==='client'?'Sortie pour':'Pour'} ${esc(w.name)}</b> <span class="xs">(${esc(w.rel)})</span>${role==='companion'?` · <span class="num">${esc(w.tel)}</span>`:''}</div>
  ${w.needs.length?`<div class="row" style="gap:6px">${w.needs.map(k=>`<span class="pill">${needLabel(k)}</span>`).join('')}</div>`:''}
  ${role==='companion'&&w.info?`<div class="xs ugc">${esc(w.info)}</div>`:''}
  ${role==='client'&&['confirmee','controle'].includes(b.status)?`<div class="xs">Le code de rencontre est aussi envoyé par SMS à ${esc(w.name)}.</div>`:''}</div>`}
function reportBlock(b,role){const r=b.report;if(!r||role==='admin')return'';
  return `<div class="card stack report"><span class="lbl" style="color:var(--gold)">Compte rendu de ${esc(comp(b.companionId).name)}</span><span class="pill t-ok" style="align-self:flex-start">${esc(r.mood)}</span><p class="sm ugc">${esc(r.text)}</p><span class="xs muted">${fdt(r.t)}</span></div>`}
function reportSheet(s,head,b){const w=b.forWho;
  return head('Compte rendu',`${b.ref} · ${w?`pour la famille de ${esc(w.name)}`:''}`)+`<form class="stack" data-form="report" data-id="${b.id}">
  <span class="fl">Comment s'est passée la sortie ?</span><div class="seg2">${['Très bonne sortie','Bonne sortie','Sortie difficile'].map((m,i)=>`<label><input type="radio" name="mood" value="${m}" ${i===0?'checked':''}><span>${m}</span></label>`).join('')}</div>
  <div class="field"><label for="rp-t">Votre message à la famille</label><textarea id="rp-t" name="text" rows="5" maxlength="800" placeholder="Ce que vous avez fait, comment votre accompagné(e) s'est senti(e), un moment marquant…"></textarea></div>
  <p class="note t-bad sm" id="rp-err" hidden></p><button class="btn pri full">Envoyer le compte rendu</button></form>`}
EXTRA_SHEETS.report=(s,h,b)=>reportSheet(s,h,b);

