/* ================= V2.3 — Récapitulatif annuel des revenus (obligation DAC7, art. 242 bis CGI) ================= */
const DONE_ST=['terminee','versement','cloturee'];
function yearIncome(cid,year){const l=S.bookings.filter(b=>b.companionId===cid&&b.paid&&DONE_ST.includes(b.status)&&new Date(b.start).getFullYear()===year);
  const q=[0,1,2,3].map(i=>{const x=l.filter(b=>Math.floor(new Date(b.start).getMonth()/3)===i);return{n:x.length,gross:r2(x.reduce((a,b)=>a+b.prest+(b.extensions||[]).reduce((s,e)=>s+(e.prest||0),0),0)),comm:r2(x.reduce((a,b)=>a+(b.comm||0),0))}});
  const gross=r2(q.reduce((a,x)=>a+x.gross,0)),comm=r2(q.reduce((a,x)=>a+x.comm,0)),annex=r2(l.reduce((a,b)=>a+(b.annex||0),0)),tips=r2(l.reduce((a,b)=>a+(b.tip||0),0));
  return{n:l.length,q,gross,comm,net:r2(gross-comm),annex,tips}}
const taxOk=c=>!!(c.tax&&c.tax.id&&c.tax.addr&&c.tax.dob);
function pYearCard(){const c=comp('c1'),y=S.taxYear||new Date(now()).getFullYear(),I=yearIncome('c1',y),years=[...new Set(S.bookings.filter(b=>b.companionId==='c1').map(b=>new Date(b.start).getFullYear()))].sort((a,b)=>b-a);
  return `<section class="section"><div class="card stack"><div class="row"><span class="lbl grow">Récapitulatif annuel des revenus</span><select id="tax-year" aria-label="Année">${(years.length?years:[y]).map(v=>`<option ${v===y?'selected':''}>${v}</option>`).join('')}</select></div>
  <div class="kpis"><div class="card kpi"><span class="lbl">Missions</span><span class="num">${I.n}</span></div><div class="card kpi"><span class="lbl">Montant brut</span><span class="num">${eur(I.gross)}</span></div><div class="card kpi"><span class="lbl">Net versé</span><span class="num">${eur(I.net)}</span></div></div>
  <div class="tbl"><table class="t"><tr><th>Trimestre</th><th>Missions</th><th>Brut</th><th>Commission</th></tr>${I.q.map((x,i)=>`<tr><td>T${i+1}</td><td class="num">${x.n}</td><td class="num">${eur(x.gross)}</td><td class="num">${eur(x.comm)}</td></tr>`).join('')}<tr class="tot"><td><b>Total</b></td><td class="num"><b>${I.n}</b></td><td class="num"><b>${eur(I.gross)}</b></td><td class="num"><b>${eur(I.comm)}</b></td></tr></table></div>
  <div class="row sm"><span class="grow">Frais annexes remboursés</span><span class="num">${eur(I.annex)}</span></div><div class="row sm"><span class="grow">Pourboires reçus</span><span class="num">${eur(I.tips)}</span></div>
  <p class="xs muted">Ces montants sont transmis chaque année à l'administration fiscale avant le 31 janvier, comme la loi l'impose aux plateformes (article 242 bis du Code général des impôts). Vous devez les déclarer vous-même sur votre déclaration de revenus et auprès de l'URSSAF.</p>
  <button class="btn" data-a="tax-mail">Recevoir le récapitulatif par e-mail</button></div></section>
  <section class="section"><form class="card stack" data-form="taxinfo"><div class="row"><span class="lbl grow">Informations fiscales</span>${taxOk(c)?'<span class="pill t-ok">Complètes</span>':'<span class="pill t-warn">À compléter</span>'}</div>
  <p class="xs muted">Obligatoires pour recevoir vos versements et pour la déclaration annuelle à l'administration fiscale.</p>
  <div class="field"><label for="tx-id">N° SIRET ou numéro fiscal</label><input id="tx-id" name="id" value="${esc(c.tax&&c.tax.id||'')}" inputmode="numeric" autocomplete="off"></div>
  <div class="field"><label for="tx-dob">Date de naissance</label><input id="tx-dob" name="dob" type="date" value="${esc(c.tax&&c.tax.dob||'')}"></div>
  <div class="field"><label for="tx-addr">Adresse postale</label><textarea id="tx-addr" name="addr" rows="2" autocomplete="street-address">${esc(c.tax&&c.tax.addr||'')}</textarea></div>
  <p class="note t-bad sm" id="tx-err" hidden></p><button class="btn pri">Enregistrer</button></form></section>`}
function dac7Export(){const y=new Date(now()).getFullYear()-(new Date(now()).getMonth()<1?1:0);
  const rows=[['annee','nom','date_naissance','adresse','siret_ou_nif','pays','missions','brut_T1','brut_T2','brut_T3','brut_T4','brut_total','commissions','net_verse','statut']];
  S.companions.forEach(c=>{const I=yearIncome(c.id,y);if(!I.n)return;const t=c.tax||{};rows.push([y,c.name,t.dob||'',(t.addr||'').replace(/[\n;]/g,' '),t.id||'',(S.cities.find(x=>x.city===c.city)||{}).country||'',I.n,...I.q.map(x=>x.gross.toFixed(2)),I.gross.toFixed(2),I.comm.toFixed(2),I.net.toFixed(2),taxOk(c)?'complet':'à compléter'])});
  const miss=rows.slice(1).filter(r=>r[14]!=='complet').length;
  open('text',{title:`Déclaration annuelle des revenus ${y}`,sub:`${rows.length-1} accompagnateur(s) · ${miss} dossier(s) à compléter · à transmettre avant le 31 janvier ${y+1}`,text:rows.map(r=>r.join(';')).join('\n')})}
function seedV23(){const c=comp('c1');c.tax={id:'912 345 678 00012',dob:'1993-04-12',addr:'8 rue de Bretagne, 75003 Paris'};S.taxYear=null}
function v23Click(a){if(a==='tax-mail'){toast('Récapitulatif envoyé à votre adresse e-mail.');return false}if(a==='dac7'){dac7Export();return true}return false}
function v23Submit(k,f,d){if(k!=='taxinfo')return false;const c=comp('c1'),id=(d.id||'').replace(/\s/g,''),e=m=>{const p=document.getElementById('tx-err');p.textContent=tr(m);p.hidden=false;return 'stop'};
  if(!/^\d{9}$|^\d{13}$|^\d{14}$/.test(id))return e('Indiquez un SIRET (14 chiffres), un SIREN (9 chiffres) ou un numéro fiscal (13 chiffres).');
  if(!d.dob)return e('Indiquez votre date de naissance.');
  if((d.addr||'').trim().length<10)return e('Indiquez votre adresse postale complète.');
  c.tax={id:d.id.trim(),dob:d.dob,addr:d.addr.trim()};log(c.name,'Informations fiscales mises à jour','—');toast('Informations fiscales enregistrées.');return true}

/* ================= V2.4 — Mode connecté (application native branchée sur Supabase) =================
   Actif seulement si window.SBS_CONFIG et la bibliothèque Supabase sont présents (application native).
   Sur la démo en ligne, rien ne change. */
const LIVE=!!(window.SBS_CONFIG&&window.supabase&&window.supabase.createClient);
let SB=null,ME=null,LIVE_SUB=null;
const ALIAS={},REAL={};   // identifiant serveur ⇄ identifiant de l'interface ('u1' = moi client, 'c1' = moi accompagnateur)
const aliasOf=id=>ALIAS[id]||id,realOf=id=>REAL[id]||id;
const HUES=[162,210,32,280,190,4,120,30,330,220,100,40];
const hueOf=id=>{let h=0;for(const ch of String(id))h=(h*31+ch.charCodeAt(0))>>>0;return HUES[h%HUES.length]};
function liveFace(id){const pal=[['#F1C9A5','#6B4226'],['#E0AC82','#2B1D14'],['#8D5A3B','#1A1210'],['#C68863','#3B2A1E']],k=hueOf(id)%4;return{skin:pal[k][0],hair:pal[k][1],style:['long','short','bun','short'][k],outfit:'#1F3B4D',shirt:'#F7F5F0'}}
function adaptCompanion(r){const id=aliasOf(r.id);return{id,_id:r.id,name:r.first_name,city:r.city||'',area:r.area||'',langs:r.languages||[],rate:+r.hourly_rate,tier:r.tier||'Standard',cats:r.categories||[],hue:hueOf(r.id),days:(r.work_days||[]).map(Number),from:r.hour_from??9,to:r.hour_to??20,verified:'ok',suspended:false,bio:r.bio||'',incl:r.included||[],excl:r.excluded||[],p:liveFace(r.id),gallery:{photos:[],locked:true,status:null},photo:{status:'ok',t:now()},video:{status:'ok'},_rating:r.rating,_reviews:r.reviews}}
const ST_MAP={en_attente:'en_attente',acceptee:'acceptee',refusee:'refusee',expiree:'expiree',paiement_confirme:'confirmee',confirmee:'confirmee',controle:'controle',verifie:'verifie',en_cours:'en_cours',fin_declaree:'double_attente',double_attente:'double_attente',terminee:'terminee',versement:'versement',cloturee:'cloturee',annulee:'annulee',absence:'absence',contestee:'contestee'};
function adaptBooking(row){const x=row.booking,start=new Date(x.starts_at).getTime(),cid=aliasOf(x.client_id),pid=aliasOf(x.companion_id);
  if(!S.users[cid])S.users[cid]={id:cid,name:row.client_first_name,city:'',verified:'ok',suspended:false,trusted:'',interests:[],notif:[]};
  return{id:x.id,ref:x.ref,clientId:cid,companionId:pid,cat:x.category,start,hours:x.hours,extMins:x.extra_minutes||0,place:x.place,annex:+x.amount_annex||0,
    prest:+x.amount_service,service:+x.amount_client_fee,tva:+x.amount_vat,total:+x.amount_total,comm:+x.amount_commission,payout:+x.amount_payout,cf:null,annexAmt:+x.amount_annex||0,
    lang:x.language||'Français',note:x.note||'',status:ST_MAP[x.status]||x.status,paid:['confirmee','controle','verifie','en_cours','double_attente','terminee','versement','cloturee','contestee'].includes(x.status),
    mission:{v:1,signed:{client:x.mission_signed_client?Date.parse(x.mission_signed_client):null,companion:x.mission_signed_companion?Date.parse(x.mission_signed_companion):null}},
    history:[{s:'demande_creee',t:Date.parse(x.created_at),actor:row.client_first_name}],presence:{client:false,companion:false},ends:{client:x.end_client?Date.parse(x.end_client):null,companion:x.end_companion?Date.parse(x.end_companion):null},
    ext:null,extensions:[],reviewed:{client:!!x.review_client_done,companion:!!x.review_companion_done},refund:0,code:null,flags:{},services:[],tip:+x.tip||0,giftUsed:+x.gift_used||0,
    forWho:x.beneficiary_name?{name:x.beneficiary_name,rel:x.beneficiary_relation||'Autre',tel:x.beneficiary_phone||'',needs:x.beneficiary_needs||[],info:x.beneficiary_info||''}:null}}

async function liveLoad(){const {data:{user}}=await SB.auth.getUser();if(!user){ME=null;S.role=null;render();return}
  const {data:p,error}=await SB.from('profiles').select('*').eq('id',user.id).single();if(error||!p){toast('Profil introuvable. Réessayez plus tard.',true);return}
  ME=p;for(const k in ALIAS)delete ALIAS[k];for(const k in REAL)delete REAL[k];
  const alias=p.role==='companion'?'c1':'u1';ALIAS[p.id]=alias;REAL[alias]=p.id;
  S.users={u1:{id:'u1',name:p.role==='companion'?'—':p.first_name,city:p.city||'',verified:p.identity_verified?'ok':'pending',suspended:p.suspended,trusted:p.trusted_contact||'',interests:[],notif:[],bio:p.biometric_unlock,priv:p.privilege_since?{since:Date.parse(p.privilege_since)}:null,refCode:p.referral_code,refs:[]}};
  const [dir,bk]=await Promise.all([SB.rpc('companions_directory'),SB.rpc('my_bookings')]);
  if(dir.error||bk.error){toast('Connexion au serveur impossible. Vérifiez votre réseau.',true);return}
  S.companions=(dir.data||[]).map(adaptCompanion);
  if(p.role==='companion'&&!S.companions.some(c=>c.id==='c1'))S.companions.push(adaptCompanion({id:p.id,first_name:p.first_name,city:p.city,hourly_rate:35,languages:[],categories:[],work_days:[0,1,2,3,4,5,6]}));
  S.bookings=(bk.data||[]).map(r=>liveAdapt2(r.booking,adaptBooking(r)));
  const ids=S.bookings.map(b=>b.id);S.msgs={};
  if(ids.length){const {data:ms}=await SB.from('messages').select('*').in('booking_id',ids).order('created_at');(ms||[]).forEach(m=>{(S.msgs[m.booking_id]=S.msgs[m.booking_id]||[]).push({from:m.sender_id===p.id?(p.role==='companion'?'companion':'client'):(p.role==='companion'?'client':'companion'),text:m.body||'',t:Date.parse(m.created_at)})})}
  if(!S.role){S.role=p.role==='admin'?'admin':p.role==='companion'?'companion':'client';S.tab=S.role==='admin'?'dashboard':'home'}
  await liveExtra(p);
  liveSubscribe();render()}
function liveSubscribe(){if(LIVE_SUB||!SB.channel)return;let t=null;const again=()=>{clearTimeout(t);t=setTimeout(()=>liveLoad(),600)};
  LIVE_SUB=SB.channel('sbs-'+ME.id).on('postgres_changes',{event:'*',schema:'public',table:'bookings'},again).on('postgres_changes',{event:'INSERT',schema:'public',table:'messages'},again).subscribe()}
async function liveCall(fn,body){const {data,error}=await SB.functions.invoke(fn,{body});if(error){let m='Le serveur ne répond pas. Réessayez.';try{const j=await error.context.json();if(j&&j.error)m=j.error}catch(e){}throw new Error(m)}if(data&&data.error)throw new Error(data.error);return data}
function liveDo(p,ok){p.then(()=>{if(ok)toast(ok);return liveLoad()}).catch(e=>{toast(e.message,true);liveLoad()})}

/* Écran de connexion */
function liveLogin(){const L=S.liveAuth||{};return `<main class="login"><div class="wrap login-in">
<div class="login-top row" style="gap:8px;flex-wrap:nowrap"><button class="btn ghost aplus" data-a="comfort">${S.comfort?'A−':'A+'} <span class="xs">Grands caractères</span></button><select class="lang" id="lang" aria-label="Langue">${[['fr','Français'],['en','English'],['es','Español'],['it','Italiano'],['de','Deutsch'],['pt','Português'],['ar','العربية']].map(([l,n])=>`<option value="${l}" ${l===S.lang?'selected':''}>${n}</option>`).join('')}</select></div>
<div class="login-logo"><div class="mono big" aria-hidden="true"><svg class="mark" viewBox="0 0 40 40" aria-hidden="true"><circle cx="14.5" cy="11" r="4.2"/><circle cx="25.5" cy="11" r="4.2"/><rect x="10.3" y="18" width="8.4" height="17" rx="4.2"/><rect x="21.3" y="18" width="8.4" height="17" rx="4.2"/></svg></div><h1>Side by Side</h1><span class="byline">moments</span></div>
${L.mode==='reset'?`<form class="stack" data-form="live-reset" style="width:100%"><p class="sm muted">Saisissez votre e-mail : vous recevrez un lien pour choisir un nouveau mot de passe.</p><div class="field"><label for="lv-mail">E-mail</label><input id="lv-mail" name="email" type="email" autocomplete="email" value="${esc(L.email||'')}"></div><button class="btn pri full big">Recevoir le lien</button><button type="button" class="btn ghost" data-a="live-mode" data-v="login">Retour</button></form>`
:`<form class="stack" data-form="live-login" style="width:100%"><div class="field"><label for="lv-mail">E-mail</label><input id="lv-mail" name="email" type="email" autocomplete="email" value="${esc(L.email||'')}"></div><div class="field"><label for="lv-pw">Mot de passe</label><input id="lv-pw" name="pw" type="password" autocomplete="current-password"></div><p class="note t-bad sm" id="lv-err" hidden></p><button class="btn pri full big" ${L.busy?'disabled':''}>${L.busy?'Connexion…':'Se connecter'}</button>
<div class="login-links"><button type="button" class="btn ghost" data-a="live-mode" data-v="reset">Mot de passe oublié ?</button><button type="button" class="btn ghost" data-a="signup">Créer un compte</button></div></form>`}
</div></main>`}
function liveEmailPage(){const v=S.su.v;return `<main class="page">${pageHead('Activer mon compte','su-edit')}<div class="bigicon"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/></svg></div>
<h2 style="text-align:center">Vérifiez votre e-mail</h2><p class="sm muted" style="text-align:center">Un lien d'activation a été envoyé à <b class="sel">${esc(v.email)}</b>. Ouvrez-le, puis revenez vous connecter.</p>
<button class="btn pri full big2" data-a="live-mode" data-v="login">J'ai activé mon compte, me connecter</button></main>`}

function liveBoot(){if(!LIVE)return;
  SB=window.supabase.createClient(SBS_CONFIG.url,SBS_CONFIG.key,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:false,flowType:'pkce',storage:window.sessionStorage,storageKey:'sbs-gestion'}});
  // la démo est vidée : seules les données du serveur s'affichent
  Object.assign(S,{companions:[],bookings:[],msgs:{},notifs:[],reviews:[],disputes:[],ledger:[],flags:[],experiences:[],gifts:[],support:[],logs:[],role:null,biz:null});
  S.users={u1:{id:'u1',name:'',city:'',verified:'pending',trusted:'',interests:[],notif:[]}};
  const _welcome=welcome;welcome=()=>liveLogin();
  const _email=emailPage;emailPage=()=>liveEmailPage();
  // fonctions pas encore branchées : masquées dans l'application (lot suivant)
  ['privCard','giftsCard','refCard','bizCard','expHome','pExpCard','aPhoneSearch'].forEach(n=>{window[n]=()=>''});
  const create=api.create.bind(api);
  api.create=(cid,f)=>{const n=S.bookings.length,r=create(cid,f);if(r.err)return r;const b=S.bookings.splice(n,1)[0];
    liveDo(liveCall('create-booking',{companion_id:realOf(cid),category:b.cat,starts_at:new Date(b.start).toISOString(),hours:b.hours,place:b.place,language:b.lang,note:b.note,annex:b.annex,experience_id:null,
      beneficiary:b.forWho?{name:b.forWho.name,relation:b.forWho.rel,phone:b.forWho.tel,needs:b.forWho.needs,info:b.forWho.info,consent:true}:null}),'Votre réservation sera confirmée dès que l\'accompagnateur aura accepté votre demande.');
    return{ok:1,msg:'Envoi de la demande…'}};
  api.accept=b=>{if(b.status!=='en_attente')return{err:'Demande déjà traitée.'};liveDo(liveCall('booking-action',{booking_id:b.id,action:'accept'}),'Demande acceptée.');b.status='acceptee';return{ok:1,msg:'Envoi…'}};
  api.refuse=b=>{if(b.status!=='en_attente')return{err:'Demande déjà traitée.'};liveDo(liveCall('booking-action',{booking_id:b.id,action:'refuse'}),'Demande refusée.');b.status='refusee';return{ok:1,msg:'Envoi…'}};
  const _sign=signMission;signMission=(b,me)=>{_sign(b,me);if(me==='client')liveDo(liveCall('booking-action',{booking_id:b.id,action:'sign'}))};
  api.pay=()=>({err:'Le paiement en ligne sera disponible très bientôt.'});
  const send=api.send.bind(api);api.send=(b,who,text)=>{const r=send(b,who,text);if(r&&r.err)return r;const mine=(S.msgs[b.id]||[]).filter(m=>m.from===who).pop();SB.from('messages').insert({booking_id:b.id,sender_id:ME.id,body:(mine?mine.text:text).trim()}).then(({error})=>{if(error)toast('Message non envoyé. Réessayez.',true)});return r};
  api.cancel=(b,who)=>{if(!['en_attente','acceptee','confirmee'].includes(b.status))return{err:'Annulation impossible à ce stade.'};liveDo(liveCall('refund-booking',{booking_id:b.id}),'Réservation annulée.');b.status='annulee';return{ok:1,msg:'Annulation…'}};
  SB.auth.getSession().then(({data})=>{if(data&&data.session)liveLoad();else render()});
  SB.auth.onAuthStateChange((ev)=>{if(ev==='SIGNED_OUT'){ME=null;S.role=null;S.adminOk=false;S.liveMfa=null;LIVE_ADM.data=null;render()}});
  liveBoot2();
  EXTRA_SHEETS['live-reason']=EXTRA_SHEETS['live-delete']=EXTRA_SHEETS.livepay=(s,h)=>liveSheets(s,h);}

function liveClick(a,el){if(!LIVE)return false;
  if(liveClick2(a,el))return true;
  if(a==='live-mode'){S.liveAuth={...(S.liveAuth||{}),mode:el.dataset.v};if(el.dataset.v==='login'){S.page=null}return true}
  if(a==='logout'){SB.auth.signOut();if(LIVE_SUB){SB.removeChannel(LIVE_SUB);LIVE_SUB=null}return false}
  return false}
function liveSubmit(k,f,d){if(!LIVE)return false;
  {const r2_=liveSubmit2(k,f,d);if(r2_)return r2_}
  if(k==='live-login'){const e=m=>{const p=document.getElementById('lv-err');p.textContent=tr(m);p.hidden=false;return 'stop'};
    if(!/^\S+@\S+\.\S{2,}$/.test(d.email||''))return e('Adresse e-mail invalide.');if(!d.pw)return e('Saisissez votre mot de passe.');
    S.liveAuth={mode:'login',email:d.email,busy:true};render();
    SB.auth.signInWithPassword({email:d.email.trim(),password:d.pw}).then(({error})=>{S.liveAuth.busy=false;if(error){render();const m=/confirm/i.test(error.message)?'Activez d\'abord votre compte avec le lien reçu par e-mail.':'E-mail ou mot de passe incorrect.';const p=document.getElementById('lv-err');if(p){p.textContent=tr(m);p.hidden=false}return}liveLoad()});
    return 'stop'}
  if(k==='live-reset'){if(!/^\S+@\S+\.\S{2,}$/.test(d.email||'')){toast('Adresse e-mail invalide.',true);return 'stop'}
    SB.auth.resetPasswordForEmail(d.email.trim()).then(()=>{toast('Si un compte existe, un lien vient d\'être envoyé.');S.liveAuth={mode:'login',email:d.email};render()});return 'stop'}
  return false}
// Inscription : après les contrôles de la page, le compte est créé sur le serveur
function liveSignup(v){const role=v.type==='companion'?'companion':v.type==='biz'?'business':'client';
  return SB.auth.signUp({email:v.email.trim(),password:v.pw,options:{data:{first_name:v.first.trim(),last_name:v.last.trim(),birth_date:v.dob,phone:(v.tel||'').replace(/[\s.-]/g,''),city:v.city,role,non_circumvention:!!v.nc}}})}


/* Cohérence des données de démonstration : jours et horaires de disponibilité, chronologie de l'historique */
function seedFix(){const N=now(),ANCH={demande_creee:0,en_attente:0,acceptee:1,paiement_confirme:2,confirmee:2};
  S.bookings.forEach(b=>{const c=comp(b.companionId);if(!c)return;
    const dur=b.hours+(b.extMins||0)/60;let d=new Date(b.start),guard=0;
    const past=b.start<N;
    while(!c.days.includes((d.getDay()+6)%7)&&guard++<7)d=new Date(d.getTime()+(past?-DAY:DAY));
    let hh=d.getHours()+d.getMinutes()/60;const lo=c.from,hi=c.to-dur;
    if(hh<lo||hh>hi){hh=Math.max(lo,Math.min(hi,hh));d.setHours(Math.floor(hh),Math.round((hh%1)*60),0,0)}
    const shift=d.getTime()-b.start;
    if(shift){const clash=S.bookings.some(x=>x!==b&&x.companionId===b.companionId&&ACTIVE.includes(x.status)&&ACTIVE.includes(b.status)&&d.getTime()<endOf(x)&&x.start<d.getTime()+dur*H);
      if(!clash){b.start=d.getTime();['starts','ends'].forEach(k=>{if(b[k])for(const w of ['client','companion'])if(b[k][w])b[k][w]+=shift});if(b.startedAt)b.startedAt+=shift;if(b.code&&b.code.expires)b.code.expires+=shift}}
    const end=b.start+dur*H,h=b.history||[];if(!h.length)return;
    const created=Math.min(h[0].t,b.start-26*H,N-H);
    const at=s=>s in ANCH?Math.min(created+ANCH[s]*2*H,b.start-24*H):s==='controle'?b.start-H:s==='verifie'?b.start-5*60000:s==='en_cours'?b.start:(s==='fin_declaree'||s==='double_attente')?end:s==='terminee'?end+10*60000:s==='versement'?end+15*60000:s==='cloturee'?end+3*DAY:null;
    let last=-Infinity;h.forEach(e=>{const t=at(e.s);if(t!=null)e.t=t;if(e.t<last)e.t=last+60000;if(e.t>N)e.t=Math.max(last+60000,N-60000);last=e.t});
    if(b.mission&&b.mission.signed){const sg=b.mission.signed,acc=(h.find(e=>e.s==='acceptee')||h[0]).t,pay=(h.find(e=>e.s==='paiement_confirme')||{}).t;
      if(sg.companion)sg.companion=Math.min(Math.max(sg.companion,acc),pay?pay-20*60000:sg.companion);if(sg.client)sg.client=Math.min(Math.max(sg.client,(sg.companion||acc)+5*60000),pay?pay-10*60000:Infinity)}
    if(b.ends){if(b.ends.client&&b.ends.client<b.start)b.ends.client=Math.min(end,N);if(b.ends.companion&&b.ends.companion<b.start)b.ends.companion=Math.min(end+2*60000,N)}
  })}

/* Barre de navigation du bas : masquée pendant le défilement vers le bas, visible dès qu'on remonte ou qu'on s'arrête,
   en haut et en bas de la page, et à chaque changement d'écran */
(function(){let lastY=window.scrollY,acc=0,idle=null;const root=document.documentElement,show=()=>{root.classList.remove('navhide');acc=0};
  window.addEventListener('scroll',()=>{const y=window.scrollY,d=y-lastY,max=root.scrollHeight-window.innerHeight;lastY=y;
    clearTimeout(idle);idle=setTimeout(show,700);   // réapparaît d'elle-même quand le défilement s'arrête
    if(y<40||y>=max-4||S.sheet){show();return}
    acc=(acc>0)===(d>0)?acc+d:d;
    if(acc>24)root.classList.add('navhide');else if(acc<-12)root.classList.remove('navhide')},{passive:true});
  document.addEventListener('focusin',e=>{if(e.target.closest&&e.target.closest('.tabs'))show()});
  const _r=render;render=(...x)=>{const t=S.tab,r=S.role,res=_r(...x);if(t!==render._t||r!==render._r){show();render._t=t;render._r=r}return res}})();
/* ================= V2.6 — Corrections de l'audit fonctionnel (espaces client et accompagnateur) ================= */
const CLOSED_ST=['cloturee','annulee','refusee','expiree'];
// Prestations incluses : uniquement celles qui correspondent à l'activité réservée
const CAT_KW={shopping:/shopping|style|créateur|boutique/i,restaurants:/restaurant|cuisine|dîner|mets|vin|dégustation/i,promenades:/balade|promenade|itinéraire|marché|quartier|traboule|vieux/i,tourisme:/visite|quartier|itinéraire|billets|marché|vieux|traboule/i,musees:/exposition|galerie|musée|billets|parcours de visite/i,spectacles:/billets|spectacle|cinéma/i,pro:/protocole|participants|notes|invités|organisateur|interprétariat lors|coordination/i,galas:/dîners et réceptions|protocole|invités|placement|réception/i,seniors:/rythme|itinéraire adapté|balade/i};
function inclFor(c,cat){const all=c.incl||[];if(cat==='prestige')return all;const kw=CAT_KW[cat];return all.filter(x=>(kw&&kw.test(x))||!Object.entries(CAT_KW).some(([k,r])=>k!==cat&&r.test(x)))}
// Validations datées de chaque partie
function stepT(b,s){const e=(b.history||[]).find(x=>x.s===s);return e?e.t:null}
function valHtml(b,role){if(!['verifie','en_cours','fin_declaree','double_attente','terminee','versement','cloturee','a_verifier','contestee','incident'].includes(b.status))return'';
  const st=b.starts||{},en=b.ends||{},cl=b.forWho?`${S.users[b.clientId].name} (pour ${b.forWho.name})`:S.users[b.clientId].name,cn=comp(b.companionId).name,t0=stepT(b,'en_cours')||b.startedAt;
  const sc=st.client||(t0&&!b.starts?t0:null),sp=st.companion||(t0&&!b.starts?t0:null),f=t=>t?`<span class="t-ok">✓ ${fdt(t)}</span>`:'<span class="muted">en attente</span>';
  return `<div class="card stack sm"><span class="lbl">Validations</span><div class="mrow"><span>Début · ${esc(cl)}</span><span>${f(sc)}</span></div><div class="mrow"><span>Début · ${esc(cn)}</span><span>${f(sp)}</span></div><div class="mrow"><span>Fin · ${esc(cl)}</span><span>${f(en.client)}</span></div><div class="mrow"><span>Fin · ${esc(cn)}</span><span>${f(en.companion)}</span></div></div>`}
// Versement : « effectué » uniquement avec la confirmation de Stripe
function payoutDone(b){return LIVE?!!b.payoutDone:b.status==='cloturee'}
function payoutHtml(b,role){if(role!=='companion'||!['terminee','versement','cloturee'].includes(b.status))return'';
  const t=stepT(b,'cloturee');return payoutDone(b)?`<div class="note t-ok sm">Versement effectué${t?` le ${fdt(t)}`:''} : ${eur(b.payout)} sur votre compte de versement Stripe${LIVE?'':' (démonstration)'}.</div>`:`<div class="note t-warn sm">Versement en cours : ${eur(b.payout)}. Il sera indiqué « effectué » dès la confirmation de Stripe.</div>`}
function deadlineHtml(b,role){if(b.status!=='acceptee')return'';const dl=b.payDeadline||Math.min((b.mission&&b.mission.signed&&b.mission.signed.companion||now())+24*H,b.start-2*H);
  return `<div class="note t-info sm">${role==='client'?'Réglez':'Le client doit régler'} la réservation avant le ${fdt(dl)}. Le créneau est bloqué jusque-là, puis libéré automatiquement.</div>`}
// Détail de la rémunération pour l'accompagnateur
function netLine(b){const ann=b.annexAmt??b.annex??0;return `<div class="xs muted">Prestation ${eur(b.prest)} · commission plateforme −${eur(b.comm||0)} · net ${eur(r2(b.prest-(b.comm||0)))}${ann?` · frais annexes remboursés ${eur(ann)}`:''}</div>`}

/* ---------- PDF (fiche de mission, factures) : généré dans le téléphone, sans service externe ---------- */
function pdfBytes(title,text){const W1252={'€':128,'‚':130,'„':132,'…':133,'‘':145,'’':146,'“':147,'”':148,'•':149,'–':150,'—':151,'œ':156,'Œ':140,'Ÿ':159,' ':32,' ':32,'✓':42,'★':42,'↔':45,'−':45};
  const enc=s=>{let o='';for(const ch of s){let c=W1252[ch]??ch.charCodeAt(0);if(c>255)c=63;const x=String.fromCharCode(c);o+=(x==='('||x===')'||x==='\\')?'\\'+x:x}return o};
  const lines=[];String(text).split('\n').map(l=>l.replace(/\s+/g,' ').trim()).filter((l,i,a)=>l||a[i-1]).forEach(l=>{if(!l){lines.push('');return}while(l.length>92){let k=l.lastIndexOf(' ',92);if(k<40)k=92;lines.push(l.slice(0,k));l=l.slice(k).trim()}lines.push(l)});
  const pages=[];for(let i=0;i<lines.length;i+=50)pages.push(lines.slice(i,i+50));if(!pages.length)pages.push([]);
  const objs=[],add=s=>{objs.push(s);return objs.length};
  add('<< /Type /Catalog /Pages 2 0 R >>');add('PAGES');add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');
  const kids=[];pages.forEach((pg,pi)=>{let y=800,c=`BT /F2 15 Tf 50 ${y} Td (${enc(title)}) Tj ET\n`;y-=14;c+=`BT /F1 8 Tf 50 ${y} Td (${enc('Side by Side (groupe Zyntell) · document généré le '+new Date().toLocaleString('fr-FR')+' · page '+(pi+1)+'/'+pages.length)}) Tj ET\n`;y-=22;
    pg.forEach(l=>{c+=`BT /F1 10 Tf 50 ${y} Td (${enc(l)}) Tj ET\n`;y-=14.5});const cs=add(`<< /Length ${c.length} >>\nstream\n${c}endstream`);kids.push(add(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ${cs} 0 R >>`))});
  objs[1]=`<< /Type /Pages /Kids [${kids.map(k=>k+' 0 R').join(' ')}] /Count ${kids.length} >>`;
  let out='%PDF-1.4\n',offs=[];objs.forEach((o,i)=>{offs.push(out.length);out+=`${i+1} 0 obj\n${o}\nendobj\n`});
  const x=out.length;out+=`xref\n0 ${objs.length+1}\n0000000000 65535 f \n${offs.map(o=>String(o).padStart(10,'0')+' 00000 n \n').join('')}trailer\n<< /Size ${objs.length+1} /Root 1 0 R >>\nstartxref\n${x}\n%%EOF`;
  const u=new Uint8Array(out.length);for(let i=0;i<out.length;i++)u[i]=out.charCodeAt(i)&255;return u}
function pdfSave(name,bytes){const C=window.Capacitor,P=C&&C.Plugins;
  if(C&&C.isNativePlatform&&C.isNativePlatform()&&P&&P.Filesystem&&P.Share){let bin='';bytes.forEach(x=>bin+=String.fromCharCode(x));
    P.Filesystem.writeFile({path:name,data:btoa(bin),directory:'CACHE'}).then(r=>P.Share.share({title:name,url:r.uri})).catch(()=>toast('Enregistrement du PDF impossible.',true));return}
  const blob=new Blob([bytes],{type:'application/pdf'}),direct=()=>{const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(url);a.remove()},5000)};
  if(window.claude&&window.claude.use){window.claude.use('downloads').then(d=>d?d.save({filename:name,data:blob}).catch(()=>toast('Téléchargement annulé.')):direct()).catch(direct);return}   // page publiée sur claude.ai
  direct()}
function sheetPdf(name){const el=document.querySelector('.sheet.full')||document.querySelector('.sheet');if(!el)return;
  const hide=[...el.querySelectorAll('button,input,select,textarea,.pdfbar,label.row')];hide.forEach(x=>{x.dataset.pd=x.style.display;x.style.display='none'});
  const text=el.innerText;hide.forEach(x=>{x.style.display=x.dataset.pd||'';delete x.dataset.pd});
  const lines=text.split('\n'),title=(lines.find(l=>l.trim())||name).trim();pdfSave(name.replace(/[^\w.-]+/g,'-')+'.pdf',pdfBytes(title,lines.slice(lines.indexOf(lines.find(l=>l.trim()))+1).join('\n')));toast('Fiche PDF générée.')}
const pdfBar=(name,label='Télécharger en PDF')=>`<div class="pdfbar"><button class="btn full" data-a="pdf" data-v="${esc(name)}">${label}</button></div>`;

/* ---------- Versions de la fiche de mission : une modification après signature exige deux nouvelles signatures ---------- */
function versionsHtml(b){const vs=(b.mission&&b.mission.versions)||[];if(!vs.length)return'';
  return `<details class="card"><summary class="sm">Versions précédentes (${vs.length})</summary>${vs.map(v=>`<div class="xs muted">v${v.v} · ${fdt(v.start)} · ${v.hours} h · ${esc(v.place)} · signée par l'accompagnateur ${v.signed.companion?fdt(v.signed.companion):'—'} et le client ${v.signed.client?fdt(v.signed.client):'—'} · remplacée le ${fdt(v.t)}</div>`).join('')}</details>`}

/* ---------- Agenda : périodes bloquées et délai de déplacement ---------- */
function agendaExtra(){const c=comp('c1'),bl=(c.blocked||[]).slice().sort().filter(k=>k>=dayKey(now()));
  return `<form class="card stack" data-form="block-range"><span class="lbl">Bloquer une période (vacances, absence)</span><div class="row"><div class="field grow"><label for="br-from">Du</label><input id="br-from" name="from" type="date" min="${dayKey(now())}"></div><div class="field grow"><label for="br-to">Au</label><input id="br-to" name="to" type="date" min="${dayKey(now())}"></div></div><button class="btn">Bloquer ces jours</button>${bl.length?`<p class="xs muted">Jours bloqués : ${bl.map(fday).join(', ')}</p>`:''}</form>
  <div class="card stack"><span class="lbl">Délai de déplacement entre deux prestations</span><div class="row"><select id="buf" aria-label="Délai de déplacement">${[0,15,30,45,60,90,120].map(m=>`<option value="${m}" ${(c.buffer||0)===m?'selected':''}>${m?m+' min':'Aucun'}</option>`).join('')}</select><span class="xs muted grow">Aucune réservation ne peut commencer avant la fin de ce délai.</span></div></div>`}

/* ---------- Profil de l'accompagnateur : identité, dossier administratif, versements ---------- */
const VST={a_completer:['À compléter','t-warn'],en_cours:['En cours de vérification','t-info'],valide:['Validé','t-ok'],refuse:['Refusé','t-bad']};
const vpill=k=>`<span class="pill ${VST[k][1]}">${VST[k][0]}</span>`;
function idState(){const u=S.users.u1;if(LIVE){const L=S.liveId;return u.verified==='ok'?'valide':L&&L.status==='pending'?'en_cours':L&&L.status==='refused'?'refuse':'a_completer'}
  const c=S.role==='companion'?comp('c1'):null,v=c?(c.idState||(c.verified==='ok'?'valide':'en_cours')):(u.idState||(u.verified==='ok'?'valide':'en_cours'));return v}
function idCard26(){const st=idState();if(LIVE&&st!=='valide')return liveIdCard().replace('<h3>Vérification d\'identité</h3>',`<div class="row"><h3 class="grow">Vérification d'identité</h3>${vpill(st)}</div>`);
  return `<section class="section"><div class="card stack"><div class="row"><span class="lbl grow">Vérification d'identité</span>${vpill(st)}</div><p class="xs muted">Pièce d'identité et selfie transmis de façon chiffrée, examinés par l'équipe puis supprimés à la clôture du compte. Seul le résultat de la vérification est conservé.</p>${st==='refuse'||st==='a_completer'?'<button class="btn pri" data-a="id-demo">Transmettre un justificatif</button>':''}</div></section>`}
function adminCard26(){const c=comp('c1'),a=c.adm||{status:'a_completer'},st=a.status||'a_completer',ls=a.legal||'';
  return `<section class="section"><form class="card stack" data-form="adm-info"><div class="row"><span class="lbl grow">Informations administratives</span>${vpill(st)}</div>
  <div class="field"><label for="ai-st">Statut</label><select id="ai-st" name="legal"><option value="">Choisir…</option><option value="particulier" ${ls==='particulier'?'selected':''}>Particulier (activité occasionnelle)</option><option value="micro" ${ls==='micro'?'selected':''}>Micro-entrepreneur</option><option value="societe" ${ls==='societe'?'selected':''}>Société</option></select></div>
  <div class="field"><label for="ai-siret">Numéro SIRET (micro-entrepreneur ou société)</label><input id="ai-siret" name="siret" inputmode="numeric" maxlength="17" value="${esc(a.siret||'')}" placeholder="14 chiffres"></div>
  <div class="field"><label for="ai-doc">Justificatif (avis de situation INSEE ou extrait Kbis, PDF ou photo)</label><input id="ai-doc" name="doc" type="file" accept="image/jpeg,image/png,application/pdf"></div>
  <p class="xs muted">Les informations demandées dépendent de votre statut. Elles servent à la déclaration annuelle des revenus aux impôts (obligation des plateformes).</p><p class="note t-bad sm" id="ai-err" hidden></p><button class="btn pri">Transmettre pour vérification</button></form></section>`}
function payCard26(){const c=comp('c1'),ok=LIVE?!!c._payouts:c.payoutsOk!==false;
  return `<section class="section"><div class="card stack"><div class="row"><span class="lbl grow">Coordonnées bancaires et versements</span>${ok?'<span class="pill t-ok">Compte de versement actif</span>':'<span class="pill t-warn">À configurer</span>'}</div><p class="xs muted">Vos coordonnées bancaires sont saisies et conservées uniquement chez Stripe (prestataire de paiement agréé), jamais dans Side by Side. Stripe vérifie votre éligibilité aux versements.</p><button class="btn ${ok?'':'pri'}" data-a="stripe-onboard">${ok?'Modifier mes coordonnées bancaires (Stripe)':'Configurer mes versements avec Stripe'}</button>${ok?'':'<p class="xs t-warn">Tant que le compte de versement et les vérifications ne sont pas terminés, vous pouvez préparer votre profil mais pas accepter de mission rémunérée.</p>'}</div></section>`}
/* ---------- Confidentialité et suppression de compte (deux espaces) ---------- */
function privacyCard26(){const u=S.users.u1;return `<section class="section"><div class="card stack"><span class="lbl">Confidentialité et suppression de compte</span>
  <button class="btn ghost" data-a="legaldoc" data-v="confidentialite">Politique de confidentialité</button>
  <label class="row sm"><input type="checkbox" data-a="pv-loc" ${u.consentLoc?'checked':''}> Partage temporaire de ma position en cas de SOS</label>
  <label class="row sm"><input type="checkbox" data-a="receipts" ${S.prefs.receipts?'checked':''}> Accusés de lecture dans la messagerie</label>
  <label class="row sm"><input type="checkbox" data-a="pv-mkt" ${u.mkt?'checked':''}> Recevoir les nouveautés Side by Side par e-mail</label>
  <p class="xs muted">Factures et écritures comptables conservées 10 ans (obligation légale), rattachées à un compte anonymisé. Suppression impossible tant qu'une réservation, un remboursement ou un versement est en cours ; un abonnement Privilège est résilié automatiquement.</p>
  <button class="btn" data-a="${LIVE?'live-export':'pv-export'}">Exporter mes données personnelles</button><button class="btn bad" data-a="${LIVE?'live-delete':'pv-delete'}">Supprimer définitivement mon compte</button></div></section>`}

function v26Init(){if(window.__v26)return;window.__v26=1;
  ['mission','invoice','cinvoice'].forEach(k=>{const f=EXTRA_SHEETS[k];if(!f)return;EXTRA_SHEETS[k]=(s,h,b)=>{const bb=b||S.bookings.find(x=>x.id===s.id);return f(s,h,b)+(k==='mission'&&bb?versionsHtml(bb):'')+pdfBar(`${k==='mission'?'Fiche-de-mission':'Facture'}-${bb?bb.ref:'Side-by-Side'}${k==='mission'&&bb?'-v'+bb.mission.v:''}`)}});
  const _fw=forWhoBlock;forWhoBlock=(b,role)=>{if(role==='companion'&&CLOSED_ST.includes(b.status)&&b.forWho){const fw=b.forWho;b.forWho={...fw,tel:'',needs:[],info:''};const h=_fw(b,role);b.forWho=fw;return h+'<p class="xs muted">Coordonnées et informations de santé du proche masquées après la clôture de la mission.</p>'}return _fw(b,role)};
  const _ac=applyChange;applyChange=(b,ch)=>{const m=b.mission,signed=m&&(m.signed.client||m.signed.companion);if(signed){(m.versions=m.versions||[]).push({v:m.v,start:b.start,hours:b.hours,place:b.place,signed:{...m.signed},t:now()})}
    const d=_ac(b,ch);if(signed){const nm=b.mission||m;nm.v=(m.v||1)+1;nm.versions=m.versions;nm.signed={companion:now(),client:null};b.mission=nm;log(comp(b.companionId).name,`Fiche de mission v${nm.v} signée (modification acceptée)`,b.ref);notify('client',`Nouvelle version de la fiche de mission ${b.ref} : signez-la pour confirmer la modification.`)}return d};
  const _cA=cAccount;cAccount=(...x)=>idCard26()+_cA(...x)+privacyCard26();
  const _pP=pProfile;pProfile=(...x)=>_pP(...x)+idCard26()+adminCard26()+payCard26()+privacyCard26();
  const _vc=api.verifyCode.bind(api);api.verifyCode=(b,code)=>b.mission&&b.mission.v>1&&!(b.mission.signed.client&&b.mission.signed.companion)?{err:'La nouvelle version de la fiche de mission doit d\'abord être signée par les deux parties.'}:_vc(b,code)}
function v26Click(a,el,id,v,b){switch(a){
  case'pdf':sheetPdf(v||'Side-by-Side');return false;
  case'buffer':{const c=comp('c1'),m=+el.value;c.buffer=m;if(LIVE)SB.from('companions').update({travel_buffer_min:m}).eq('id',ME.id).then(({error})=>tr_(error?'Enregistrement impossible.':'Délai de déplacement enregistré.',!!error));else toast('Délai de déplacement enregistré.');return true}
  case'id-demo':{if(S.role==='companion')comp('c1').idState='en_cours';else S.users.u1.idState='en_cours';toast('Démonstration : justificatif transmis, vérification en cours.');return true}
  case'stripe-onboard':{if(LIVE){liveCall('stripe-onboard',{}).then(r=>{if(r.url)location.href=r.url}).catch(e=>tr_(e.message,true))}else{comp('c1').payoutsOk=true;toast('Démonstration : dans l\'application, vous êtes redirigé vers le parcours sécurisé de Stripe.')}return true}
  case'pv-loc':S.users.u1.consentLoc=el.checked;toast('Préférence enregistrée.');return true;
  case'pv-mkt':S.users.u1.mkt=el.checked;toast('Préférence enregistrée.');return true;
  case'pv-export':open('live-export',{json:JSON.stringify({profil:S.users.u1,reservations:S.bookings.filter(x=>x.clientId==='u1'||x.companionId==='c1').map(x=>({ref:x.ref,date:new Date(x.start).toISOString(),statut:x.status,total:x.total}))},null,2)});return true;
  case'pv-delete':open('pv-delete');return true;
  default:return false}}
function v26Submit(k,f,d){
  if(k==='block-range'){const c=comp('c1');if(!d.from||!d.to||d.to<d.from){toast('Choisissez une date de début et de fin.',true);return 'stop'}
    const days=[];for(let t=Date.parse(d.from+'T12:00:00');dayKey(t)<=d.to&&days.length<92;t+=DAY)days.push(dayKey(t));
    const busy=days.filter(k=>S.bookings.some(b=>b.companionId==='c1'&&ACTIVE.includes(b.status)&&dayKey(b.start)===k));const free=days.filter(k=>!busy.includes(k));
    c.blocked=[...new Set([...(c.blocked||[]),...free])];
    if(LIVE&&free.length)SB.from('companion_blocked_days').insert(free.map(k=>({companion_id:ME.id,day:k}))).then(({error})=>{if(error)tr_('Enregistrement impossible.',true)});
    toast(`${free.length} jour(s) bloqué(s)${busy.length?` · ${busy.length} jour(s) déjà réservé(s) non bloqué(s)`:''}.`);return true}
  if(k==='adm-info'){const e=m=>{const p=document.getElementById('ai-err');p.textContent=tr(m);p.hidden=false;return 'stop'},siret=String(d.siret||'').replace(/\s/g,'');
    if(!d.legal)return e('Choisissez votre statut.');if(d.legal!=='particulier'&&!/^\d{14}$/.test(siret))return e('Le numéro SIRET comporte 14 chiffres.');
    const file=f.querySelector('[name=doc]').files[0];if(d.legal!=='particulier'&&!file&&!(comp('c1').adm&&comp('c1').adm.doc))return e('Ajoutez le justificatif.');
    if(file&&(file.size>5*1024*1024||!/^(image\/(jpeg|png)|application\/pdf)$/.test(file.type)))return e('Justificatif : JPG, PNG ou PDF, 5 Mo maximum.');
    const c=comp('c1');c.adm={legal:d.legal,siret,status:'en_cours',doc:!!file||(c.adm&&c.adm.doc)};
    if(LIVE){(async()=>{let path=null;if(file){path=`${ME.id}/administratif-${Date.now()}.${file.type==='application/pdf'?'pdf':file.type==='image/png'?'png':'jpg'}`;const up=await SB.storage.from('documents').upload(path,file,{contentType:file.type});if(up.error)return tr_('Envoi impossible.',true)}
      const {error}=await SB.from('companions').update({legal_status:d.legal,tax_id:siret||null,...(path?{admin_doc_path:path}:{})}).eq('id',ME.id);tr_(error?'Enregistrement impossible.':'Dossier transmis pour vérification.',!!error)})()}else toast('Dossier transmis pour vérification.');return true}
  if(k==='pv-delete'){if(String(d.confirm||'').trim()!=='SUPPRIMER'){toast('Écrivez SUPPRIMER pour confirmer.',true);return 'stop'}
    const act=S.bookings.some(x=>(x.clientId==='u1'||x.companionId==='c1')&&(ACTIVE.includes(x.status)||['terminee','versement'].includes(x.status)));
    if(act){toast('Terminez ou annulez d\'abord vos réservations en cours (démonstration).',true);return 'stop'}S.sheet=null;toast('Démonstration : compte supprimé.');S.role=null;return true}
  return false}
function v26Sheets(s,h){if(s.type==='pv-delete')return `${h('Supprimer mon compte','Action définitive')}<p class="sm">Vos informations personnelles, pièces d'identité et photos sont supprimées ; les factures sont conservées 10 ans, anonymisées. Impossible si une réservation, un remboursement ou un versement est en cours.</p><form class="stack" data-form="pv-delete"><div class="field"><label for="pd-c">Écrivez SUPPRIMER pour confirmer</label><input id="pd-c" name="confirm" autocomplete="off"></div><button class="btn bad full">Supprimer définitivement</button></form>`;return null}

/* ================= V2.7 — Fiscalité annuelle DAC7 (CGI art. 1649 ter A) : documents fiscaux et déclarations ================= */
const DAC7_PORTAL='https://www.impots.gouv.fr/transfert-dinformations-en-application-des-dispositifs-dpi-dac7-plateformes-deconomie-collaborative';
const MOIS=['Janv.','Févr.','Mars','Avr.','Mai','Juin','Juil.','Août','Sept.','Oct.','Nov.','Déc.'];
const eurInt=x=>Math.round(+x+1e-9);
function saveFile(name,blob){const C=window.Capacitor,P=C&&C.Plugins;
  if(C&&C.isNativePlatform&&C.isNativePlatform()&&P&&P.Filesystem&&P.Share){blob.arrayBuffer().then(buf=>{let bin='';new Uint8Array(buf).forEach(x=>bin+=String.fromCharCode(x));return P.Filesystem.writeFile({path:name,data:btoa(bin),directory:'CACHE'})}).then(r=>P.Share.share({title:name,url:r.uri})).catch(()=>toast('Enregistrement impossible.',true));return}
  const direct=()=>{const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(u);a.remove()},5000)};
  if(window.claude&&window.claude.use){window.claude.use('downloads').then(d=>d?d.save({filename:name,data:blob}).catch(()=>toast('Téléchargement annulé.')):direct()).catch(direct);return}direct()}
/* Données de l'année : missions dont le versement est effectué, rattachées au mois du versement */
function taxMonths(cid,year){const out=MOIS.map((m,i)=>({month:i+1,missions:0,gross:0,fees:0,tips:0,annex:0}));
  S.bookings.filter(b=>b.companionId===cid&&b.status==='cloturee'&&payoutDone(b)).forEach(b=>{const t=stepT(b,'cloturee')||endOf(b),d=new Date(t);if(d.getFullYear()!==year)return;const o=out[d.getMonth()];
    o.missions++;o.gross+=b.prest+(b.extensions||[]).reduce((s,e)=>s+(e.prest||0),0);o.fees+=b.comm||0;o.tips+=b.tip||0;o.annex+=b.annex||0});return out}
const quarters=m=>[0,1,2,3].map(q=>m.slice(q*3,q*3+3).reduce((a,x)=>({missions:a.missions+x.missions,gross:a.gross+x.gross,fees:a.fees+x.fees,tips:a.tips+x.tips,annex:a.annex+x.annex}),{missions:0,gross:0,fees:0,tips:0,annex:0}));
const netOf=x=>eurInt(x.gross-x.fees+x.tips);
/* ---------- Espace accompagnateur : « Mes documents fiscaux » ---------- */
function fiscalDocs(){const c=comp('c1');if(!c)return'';const y=S.fiscalYear||new Date(now()).getFullYear(),L=S.liveTax&&S.liveTax.year===y?S.liveTax:null;
  const months=L?MOIS.map((_,i)=>{const r=(L.months||[]).find(x=>x.month===i+1);return r?{month:i+1,missions:r.missions,gross:+r.gross,fees:+r.fees,tips:+r.tips,annex:+r.annex}:{month:i+1,missions:0,gross:0,fees:0,tips:0,annex:0}}):taxMonths('c1',y);
  const Q=quarters(months),T=Q.reduce((a,x)=>({missions:a.missions+x.missions,gross:a.gross+x.gross,fees:a.fees+x.fees,tips:a.tips+x.tips,annex:a.annex+x.annex}),{missions:0,gross:0,fees:0,tips:0,annex:0});
  const certs=(LIVE?(S.liveCerts||[]):(c.certs||[])).slice().sort((a,b)=>b.year-a.year||b.version-a.version),t=c.tax||{},missing=[!t.nif&&'numéro fiscal',!t.birthCity&&'ville de naissance',!t.addr&&'adresse postale',!t.dob&&'date de naissance'].filter(Boolean);
  const years=[...new Set([new Date(now()).getFullYear(),new Date(now()).getFullYear()-1,...certs.map(x=>x.year)])].sort((a,b)=>b-a);
  return `<section class="section"><div class="card stack"><div class="row"><span class="lbl grow">Mes documents fiscaux</span><select id="fy" aria-label="Année fiscale">${years.map(v=>`<option ${v===y?'selected':''}>${v}</option>`).join('')}</select></div>
  <div class="kpis"><div class="card kpi"><span class="lbl">Prestations</span><span class="num">${T.missions}</span></div><div class="card kpi"><span class="lbl">Revenus nets ${y}</span><span class="num">${eur(netOf(T))}</span></div><div class="card kpi"><span class="lbl">Commissions et frais prélevés</span><span class="num">${eur(eurInt(T.fees))}</span></div></div>
  <div class="tbl"><table class="t"><tr><th>Trimestre</th><th>Prestations</th><th>Brut</th><th>Commissions</th><th>Net</th></tr>${Q.map((x,i)=>`<tr><td>T${i+1}</td><td class="num">${x.missions}</td><td class="num">${eur(x.gross)}</td><td class="num">${eur(x.fees)}</td><td class="num">${eur(netOf(x))}</td></tr>`).join('')}<tr class="tot"><td><b>${y}</b></td><td class="num"><b>${T.missions}</b></td><td class="num"><b>${eur(T.gross)}</b></td><td class="num"><b>${eur(T.fees)}</b></td><td class="num"><b>${eur(netOf(T))}</b></td></tr></table></div>
  <details><summary class="sm">Détail mensuel</summary><div class="tbl"><table class="t"><tr><th>Mois</th><th>Prestations</th><th>Net</th></tr>${months.filter(m=>m.missions).map(m=>`<tr><td>${MOIS[m.month-1]}</td><td class="num">${m.missions}</td><td class="num">${eur(netOf(m))}</td></tr>`).join('')||'<tr><td colspan="3" class="muted">Aucun versement cette année.</td></tr>'}</table></div></details>
  <p class="xs muted">Montants des missions dont le versement est effectué, rattachés à la date du versement. Revenus nets = prestations − commissions + pourboires. Frais annexes remboursés (${eur(T.annex)}) non compris. Aucune taxe n'est prélevée par Side by Side.</p>
  ${missing.length?`<div class="note t-warn sm">Informations fiscales à compléter : ${missing.join(', ')}. Elles sont obligatoires pour la déclaration annuelle.</div>`:''}
  <span class="lbl">Attestations annuelles</span>${certs.length?certs.map(x=>`<div class="row sm"><span class="grow">Attestation ${x.year}${x.version>1?` (version ${x.version})`:''} · ${x.published_at||x.published?`disponible le ${fshort(x.published_at?Date.parse(x.published_at):x.published)}`:'en préparation'}</span><button class="btn ghost" data-a="cert-pdf" data-v="${x.year}|${x.version}">PDF</button></div>`).join(''):'<p class="xs muted">Votre attestation annuelle est disponible avant le 31 janvier de l\'année suivante. Vous êtes prévenu(e) par notification.</p>'}
  </div></section>
  <section class="section"><form class="card stack" data-form="taxinfo2"><span class="lbl">Informations pour la déclaration annuelle</span>
  <div class="field"><label for="t2-nif">Numéro fiscal (13 chiffres, sur votre avis d'impôt)</label><input id="t2-nif" name="nif" inputmode="numeric" maxlength="17" value="${esc(t.nif||'')}" autocomplete="off"></div>
  <div class="row"><div class="field grow"><label for="t2-country">Pays de résidence fiscale</label><select id="t2-country" name="country">${[['FR','France'],['BE','Belgique'],['LU','Luxembourg'],['DE','Allemagne'],['ES','Espagne'],['IT','Italie'],['PT','Portugal'],['NL','Pays-Bas'],['CH','Suisse'],['MA','Maroc'],['GB','Royaume-Uni']].map(([k,n])=>`<option value="${k}" ${(t.country||'FR')===k?'selected':''}>${n}</option>`).join('')}</select></div></div>
  <div class="row"><div class="field grow"><label for="t2-bc">Ville de naissance</label><input id="t2-bc" name="bcity" value="${esc(t.birthCity||'')}" maxlength="100"></div><div class="field"><label for="t2-bco">Pays de naissance</label><input id="t2-bco" name="bcountry" value="${esc(t.birthCountry||'FR')}" maxlength="2" style="width:4.5em;text-transform:uppercase"></div></div>
  <p class="xs muted">Données transmises chaque année à l'administration fiscale (DGFiP), comme la loi l'impose aux plateformes. Accès limité aux administrateurs habilités, conservation pendant la durée légale.</p><p class="note t-bad sm" id="t2-err" hidden></p><button class="btn pri">Enregistrer</button></form></section>`}
function certPdf(year,version){const c=comp('c1'),certs=LIVE?(S.liveCerts||[]):(c.certs||[]),x=certs.find(k=>k.year===+year&&k.version===+version);if(!x)return;
  const d=x.data||(()=>{const Q=quarters(taxMonths('c1',+year));return{quarters:Q.map(q=>({missions:q.missions,consideration:netOf(q),fees:eurInt(q.fees),taxes:0})),missions:Q.reduce((a,q)=>a+q.missions,0),consideration:Q.reduce((a,q)=>a+netOf(q),0),fees:Q.reduce((a,q)=>a+eurInt(q.fees),0)}})();
  const t=c.tax||{};const lines=[`Attestation annuelle ${year}${version>1?` · version ${version}`:''}`,'',`Plateforme : Side by Side, éditée par ${LEGAL_CO.name} (${LEGAL_CO.form}), ${LEGAL_CO.addr}`,`Accompagnateur : ${S.users.u1&&S.users.u1.name&&S.users.u1.name!=='—'?S.users.u1.name:c.name}`,`Numéro fiscal : ${t.nif||'non communiqué'} · résidence fiscale : ${t.country||'FR'}`,`Adresse : ${t.addr||'non communiquée'}`,'',
    'Activité : prestations de services personnels (accompagnement)','',...d.quarters.map((q,i)=>`Trimestre ${i+1} : ${q.missions} prestation(s) · revenus nets ${q.consideration} € · commissions et frais ${q.fees} € · taxes ${q.taxes} €`),'',
    `Total ${year} : ${d.missions} prestation(s) · revenus nets ${d.consideration} € · commissions et frais ${d.fees} €`,'','Montants en euros, arrondis à l\'euro le plus proche. Ces informations sont également transmises à la DGFiP',`(article 1649 ter A du Code général des impôts, directive DAC7). Vous devez déclarer vous-même ces revenus.`,LIVE?'':'','',LIVE?'':'DÉMONSTRATION : document fictif, sans valeur fiscale.'];
  saveFile(`Attestation-fiscale-${year}${version>1?'-v'+version:''}.pdf`,new Blob([pdfBytes(`Attestation fiscale ${year}`,lines.join('\n'))],{type:'application/pdf'}));toast('Attestation PDF générée.')}

/* ---------- Espace administrateur : « Fiscalité et déclarations DAC7 » ---------- */
// Démonstration : calculs locaux, fichier de test (codes OECD11, mention TEST) qui ne doit jamais être transmis
function demoSellers(y){return S.companions.map(c=>{const Q=quarters(taxMonths(c.id,y)),t=c.tax||{};return{c,Q,t,missions:Q.reduce((a,q)=>a+q.missions,0)}}).filter(x=>x.missions>0)}
function demoIssues(L){const out=[{who:'Zyntell (opérateur)',field:'SIREN',blocking:true,message:'SIREN de la société non renseigné (SASU en cours d\'immatriculation)'}];
  L.forEach(x=>{const t=x.t;if(!t.dob)out.push({who:x.c.name,field:'naissance',blocking:true,message:'Date de naissance manquante'});if(!t.birthCity)out.push({who:x.c.name,field:'lieu de naissance',blocking:true,message:'Ville de naissance manquante'});if(!t.addr)out.push({who:x.c.name,field:'adresse',blocking:true,message:'Adresse postale manquante'});if(!t.nif)out.push({who:x.c.name,field:'NIF',blocking:false,message:'Numéro fiscal manquant (déclaré « inconnu »)'})});return out}
function demoXml(y,L){const e=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'),ref=`OP_${y}_TEST000000_${Date.now().toString(36).toUpperCase()}`,q4=(tag,f,m=true)=>[0,1,2,3].map(q=>`<dpi:${tag}${q+1}${m?' currCode="EUR"':''}>${f(q)}</dpi:${tag}${q+1}>`).join('');
  return `<?xml version="1.0" encoding="UTF-8"?>\n<!-- DÉMONSTRATION : fichier de test (codes OECD11), données fictives, NE PAS TRANSMETTRE -->\n<dpi:DPI_OECD xmlns:dpi="urn:oecd:ties:dpi:v1" xmlns:stf="urn:oecd:ties:dpistf:v1" xmlns:iso="urn:oecd:ties:isodpitypes:v1" version="1.0"><dpi:MessageSpec><dpi:TransmittingCountry>FR</dpi:TransmittingCountry><dpi:ReceivingCountry>FR</dpi:ReceivingCountry><dpi:MessageType>DPI</dpi:MessageType><dpi:MessageRefId>${ref}</dpi:MessageRefId><dpi:MessageTypeIndic>DPI401</dpi:MessageTypeIndic><dpi:ReportingPeriod>${y}-12-31</dpi:ReportingPeriod><dpi:Timestamp>${new Date().toISOString().slice(0,19)}</dpi:Timestamp></dpi:MessageSpec><dpi:DPIBody><dpi:PlatformOperator><dpi:ResCountryCode>FR</dpi:ResCountryCode><dpi:TIN issuedBy="FR">000000000</dpi:TIN><dpi:Name>${e(LEGAL_CO.name)} SASU</dpi:Name><dpi:PlatformBusinessName>Side by Side</dpi:PlatformBusinessName><dpi:Address legalAddressType="OECD304"><dpi:CountryCode>FR</dpi:CountryCode><dpi:AddressFree>${e(LEGAL_CO.addr)}</dpi:AddressFree></dpi:Address><dpi:Nexus>RPONEX1</dpi:Nexus><dpi:AssumedReporting>false</dpi:AssumedReporting><dpi:DocSpec><stf:DocTypeIndic>OECD11</stf:DocTypeIndic><stf:DocRefId>${ref}_P</stf:DocRefId></dpi:DocSpec></dpi:PlatformOperator>`+
  L.map((x,i)=>{const n=x.c.name.split(' ');return `<dpi:ReportableSeller><dpi:Identity><dpi:IndividualSeller><dpi:Standard><dpi:IndSellerID><dpi:ResCountryCode>${x.t.country||'FR'}</dpi:ResCountryCode>${x.t.nif?`<dpi:TIN issuedBy="${x.t.country||'FR'}">${e(x.t.nif)}</dpi:TIN>`:'<dpi:TIN unknown="true">NOTIN</dpi:TIN>'}<dpi:Name><dpi:FirstName>${e(n[0])}</dpi:FirstName><dpi:LastName>${e(n.slice(1).join(' ')||n[0])}</dpi:LastName></dpi:Name><dpi:Address><dpi:CountryCode>${x.t.country||'FR'}</dpi:CountryCode><dpi:AddressFree>${e(x.t.addr||'')}</dpi:AddressFree></dpi:Address><dpi:BirthInfo><dpi:BirthDate>${x.t.dob||'1900-01-01'}</dpi:BirthDate></dpi:BirthInfo></dpi:IndSellerID></dpi:Standard></dpi:IndividualSeller></dpi:Identity><dpi:RelevantActivities><dpi:PersonalServices><dpi:Consideration>${q4('ConsQ',q=>netOf(x.Q[q]))}</dpi:Consideration><dpi:NumberOfActivities>${q4('NumbQ',q=>x.Q[q].missions,false)}</dpi:NumberOfActivities><dpi:Fees>${q4('FeesQ',q=>eurInt(x.Q[q].fees))}</dpi:Fees><dpi:Taxes>${q4('TaxesQ',()=>0)}</dpi:Taxes></dpi:PersonalServices></dpi:RelevantActivities><dpi:DocSpec><stf:DocTypeIndic>OECD11</stf:DocTypeIndic><stf:DocRefId>${ref}_V${String(i+1).padStart(5,'0')}</stf:DocRefId></dpi:DocSpec></dpi:ReportableSeller>`}).join('')+`</dpi:DPIBody></dpi:DPI_OECD>`}
function dac7Data(){const y=S.dac7Year||new Date(now()).getFullYear()-1;
  if(LIVE)return S.liveDac7&&S.liveDac7.year===y?S.liveDac7:null;
  const L=demoSellers(y),issues=demoIssues(L),D=S.demoDecl||{};
  return{year:y,companions_total:S.companions.length,concerned:L.length,total_missions:L.reduce((a,x)=>a+x.missions,0),total_consideration:L.reduce((a,x)=>a+x.Q.reduce((s,q)=>s+netOf(q),0),0),total_fees:L.reduce((a,x)=>a+x.Q.reduce((s,q)=>s+eurInt(q.fees),0),0),
    sellers:L.map(x=>({name:x.c.name,missions:x.missions,consideration:x.Q.reduce((s,q)=>s+netOf(q),0),fees:x.Q.reduce((s,q)=>s+eurInt(q.fees),0),issues:issues.filter(i=>i.who===x.c.name).length})),issues,blocking:issues.filter(i=>i.blocking).length,declarations:D[y]||[],certificates_published:0,deadline:`${y+1}-01-31`,portal:DAC7_PORTAL,demo:true}}
function dac7Load(){if(!LIVE)return;const y=S.dac7Year||new Date(now()).getFullYear()-1;S.liveDac7=null;liveCall('tax-admin',{action:'overview',year:y}).then(d=>{S.liveDac7=d;render()}).catch(e=>tr_(e.message,true))}
const DST={brouillon:['Brouillon','t-warn'],validee:['Validée','t-info'],transmise:['Transmise','t-ok'],acceptee:['Acceptée','t-ok'],rejetee:['Rejetée','t-bad'],annulee:['Remplacée','muted']};
function dac7Sheet(s,head){const D=dac7Data(),y=S.dac7Year||new Date(now()).getFullYear()-1,cur=new Date(now()).getFullYear();
  const top=head('Fiscalité et déclarations DAC7',`Revenus ${y} · à transmettre avant le 31 janvier ${y+1}`)+`<div class="row"><label class="sm" for="d7y">Année fiscale</label><select id="d7y">${[cur-1,cur-2,cur-3,cur].map(v=>`<option ${v===y?'selected':''}>${v}</option>`).join('')}</select></div>`;
  if(!D)return top+'<p class="muted">Chargement…</p>';
  const decl=D.declarations||[],last=decl[decl.length-1],active=decl.find(d=>['validee','transmise','acceptee'].includes(d.status)),draft=decl.find(d=>d.status==='brouillon');
  const K=(l,v)=>`<div class="card kpi"><span class="lbl">${l}</span><span class="num">${v}</span></div>`;
  return top+`${D.demo?'<div class="note t-warn sm">Démonstration : données fictives. Le fichier produit est un fichier de test, à ne jamais transmettre.</div>':''}
  <div class="kpis">${K('Accompagnateurs',D.companions_total)}${K('Concernés par la déclaration',D.concerned)}${K('Rémunérations versées (nettes)',eur(D.total_consideration))}${K('Commissions prélevées',eur(D.total_fees))}${K('Informations manquantes',D.blocking)}${K('Déclaration',last?DST[last.status][0]:'Non préparée')}</div>
  ${D.issues.length?`<details ${D.blocking?'open':''} class="card"><summary class="sm"><b>${D.issues.length} point(s) à vérifier</b>${D.blocking?` dont ${D.blocking} bloquant(s)`:''}</summary>${D.issues.map(i=>`<div class="xs ${i.blocking?'t-bad':'muted'}">${esc(i.who)} · ${esc(i.field)} : ${esc(i.message)}</div>`).join('')}</details>`:'<div class="note t-ok sm">Toutes les informations obligatoires sont complètes.</div>'}
  <div class="tbl"><table class="t"><tr><th>Accompagnateur</th><th>Prestations</th><th>Net</th><th>Commissions</th><th>Dossier</th></tr>${(D.sellers||[]).map(x=>`<tr><td>${esc(x.name)}</td><td class="num">${x.missions}</td><td class="num">${eur(x.consideration)}</td><td class="num">${eur(x.fees)}</td><td>${x.issues?`<span class="pill t-warn">${x.issues} point(s)</span>`:'<span class="pill t-ok">Complet</span>'}</td></tr>`).join('')||'<tr><td colspan="5" class="muted">Aucun versement sur l\'année : déclaration « néant ».</td></tr>'}</table></div>
  <div class="stack"><button class="btn" data-a="dac7-verify">Vérifier les informations fiscales</button>
  <button class="btn pri" data-a="dac7-generate" ${D.blocking&&!D.demo?'disabled':''}>${active?'Corriger une déclaration':'Générer la déclaration DAC7 (XML)'}</button>
  ${draft?`<div class="card stack"><div class="row"><b class="grow sm">${esc(draft.message_ref_id)}</b>${pill2(draft.status)}</div><p class="xs muted">${draft.sellers} accompagnateur(s) · ${eur(draft.total_consideration)} · à valider avant transmission.</p><button class="btn" data-a="dac7-download" data-id="${draft.id}">Télécharger le fichier XML</button><button class="btn pri" data-a="dac7-validate" data-id="${draft.id}">Valider la déclaration</button></div>`:''}
  <button class="btn" data-a="dac7-certs" ${active?'':'disabled'}>Générer les attestations individuelles</button>
  <button class="btn" data-a="dac7-send" ${active?'':'disabled'}>Envoyer toutes les attestations</button>
  <button class="btn" data-a="dac7-export">Télécharger le récapitulatif (tableur Excel)</button>
  <a class="btn ghost" href="${DAC7_PORTAL}" target="_blank" rel="noopener">Accéder au portail officiel (impots.gouv.fr)</a></div>
  ${active&&!['transmise','acceptee'].includes(active.status)?`<form class="card stack" data-form="dac7-receipt" data-id="${active.id}"><span class="lbl">Enregistrer l'accusé de réception</span><div class="field"><label for="d7r">Numéro de l'accusé de réception (impots.gouv.fr)</label><input id="d7r" name="ref" autocomplete="off"></div><button class="btn">Enregistrer</button></form>`:''}
  <span class="lbl">Historique des déclarations ${y}</span>${decl.length?decl.map(d=>`<div class="row sm"><span class="grow">v${d.version} · ${{initiale:'Initiale',corrective:'Corrective',neant:'Néant'}[d.kind]||d.kind} · ${esc(d.message_ref_id)}${d.receipt_ref?` · AR ${esc(d.receipt_ref)}`:''}</span>${pill2(d.status)}${d.id&&d.status!=='brouillon'?`<button class="btn ghost" data-a="dac7-download" data-id="${d.id}">XML</button>`:''}</div>`).join(''):'<p class="xs muted">Aucune déclaration pour cette année.</p>'}
  <p class="xs muted">La transmission se fait par l'administrateur sur impots.gouv.fr, après validation. Chaque consultation, génération et téléchargement est journalisé. Archives conservées pendant la durée légale.</p>`}
const pill2=st=>`<span class="pill ${(DST[st]||['',''])[1]}">${(DST[st]||[st])[0]}</span>`;
function dac7Click(a,el){const y=S.dac7Year||new Date(now()).getFullYear()-1,T=(b,ok)=>liveCall('tax-admin',{year:y,...b}).then(r=>{if(ok)tr_(ok);dac7Load();return r}).catch(e=>tr_(e.message,true));
  switch(a){
  case'dac7':open('dac7admin');if(LIVE)dac7Load();return true;
  case'dac7-year':S.dac7Year=+el.value;if(LIVE)dac7Load();return true;
  case'dac7-verify':if(LIVE)T({action:'verify',notify:true},'Vérification terminée : les accompagnateurs concernés sont prévenus.');else toast(`Vérification terminée : ${dac7Data().blocking} point(s) bloquant(s).`);return true;
  case'dac7-generate':{if(LIVE){const D=dac7Data(),corr=!!(D&&D.declarations.find(d=>['validee','transmise','acceptee'].includes(d.status)));T({action:'generate',correction:corr}).then(r=>{if(r&&r.xml)saveFile(`${r.declaration.message_ref_id}.xml`,new Blob([r.xml],{type:'application/xml'}))});return true}
    const L=demoSellers(y),xml=demoXml(y,L);S.demoDecl=S.demoDecl||{};(S.demoDecl[y]=S.demoDecl[y]||[]).push({id:'demo'+Date.now(),version:(S.demoDecl[y].length+1),kind:'initiale',status:'brouillon',message_ref_id:xml.match(/<dpi:MessageRefId>([^<]+)/)[1],sellers:L.length,total_consideration:dac7Data().total_consideration,xml});
    saveFile(`DAC7-${y}-DEMONSTRATION-test.xml`,new Blob([xml],{type:'application/xml'}));toast('Démonstration : fichier de test généré (à ne jamais transmettre).');return true}
  case'dac7-download':{const id=el.dataset.id;if(LIVE){liveCall('tax-admin',{action:'download',id}).then(r=>saveFile(r.name,new Blob([r.xml],{type:'application/xml'}))).catch(e=>tr_(e.message,true));return false}
    const d=(S.demoDecl[y]||[]).find(x=>x.id===id);if(d)saveFile(`DAC7-${y}-DEMONSTRATION-test.xml`,new Blob([d.xml],{type:'application/xml'}));return false}
  case'dac7-validate':{if(LIVE){T({action:'validate',id:el.dataset.id},'Déclaration validée. Transmettez-la sur impots.gouv.fr, puis enregistrez l\'accusé de réception.');return true}
    const d=(S.demoDecl[y]||[]).find(x=>x.id===el.dataset.id);if(d)d.status='validee';toast('Démonstration : déclaration validée.');return true}
  case'dac7-certs':case'dac7-send':{const pub=a==='dac7-send';if(LIVE){T({action:'certificates',publish:pub},pub?'Attestations envoyées : chaque accompagnateur est prévenu par notification.':'Attestations générées.');return true}
    const c=comp('c1');c.certs=c.certs||[];if(!c.certs.some(x=>x.year===y))c.certs.push({year:y,version:1,published:pub?now():null});else if(pub)c.certs.forEach(x=>{if(x.year===y)x.published=x.published||now()});if(pub)notify('companion',`Votre attestation fiscale ${y} est disponible dans Revenus → Mes documents fiscaux.`);toast(pub?'Démonstration : attestations envoyées.':'Démonstration : attestations générées.');return true}
  case'dac7-export':{if(LIVE){liveCall('tax-admin',{action:'export',year:y}).then(r=>saveFile(r.name,new Blob([r.csv],{type:'text/csv;charset=utf-8'}))).catch(e=>tr_(e.message,true));return false}
    const L=demoSellers(y),rows=[['Année','Nom','Date de naissance','Adresse','Pays','NIF',...[1,2,3,4].flatMap(q=>[`Prestations T${q}`,`Net T${q} (€)`,`Commissions T${q} (€)`]),'Prestations','Net (€)','Commissions (€)']].concat(L.map(x=>[y,x.c.name,x.t.dob||'',x.t.addr||'',x.t.country||'FR',x.t.nif||'',...x.Q.flatMap(q=>[q.missions,netOf(q),eurInt(q.fees)]),x.missions,x.Q.reduce((s,q)=>s+netOf(q),0),x.Q.reduce((s,q)=>s+eurInt(q.fees),0)]));
    saveFile(`Side-by-Side-DAC7-${y}-demonstration.csv`,new Blob(['﻿'+rows.map(r=>r.map(v=>/[;"\n]/.test(String(v))?`"${String(v).replace(/"/g,'""')}"`:v).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));return false}
  case'tax-mail':{const yy=S.fiscalYear||new Date(now()).getFullYear(),Q=quarters(taxMonths('c1',yy)),c=comp('c1');c.certs=c.certs||[];const tmp={year:yy,version:0,data:{quarters:Q.map(q=>({missions:q.missions,consideration:netOf(q),fees:eurInt(q.fees),taxes:0})),missions:Q.reduce((x,q)=>x+q.missions,0),consideration:Q.reduce((x,q)=>x+netOf(q),0),fees:Q.reduce((x,q)=>x+eurInt(q.fees),0)}};
    const list=LIVE?(S.liveCerts=S.liveCerts||[]):c.certs;list.push(tmp);certPdf(yy,0);list.splice(list.indexOf(tmp),1);toast('Récapitulatif PDF généré (envoi par e-mail : bientôt disponible).');return false}
  case'fiscal-year':S.fiscalYear=+el.value;if(LIVE)liveTaxLoad();return true;
  case'cert-pdf':{const [yy,vv]=String(el.dataset.v).split('|');certPdf(yy,vv);return false}
  default:return false}}
function dac7Submit(k,f,d){
  if(k==='dac7-receipt'){const ref=String(d.ref||'').trim();if(ref.length<3){toast('Indiquez le numéro de l\'accusé de réception.',true);return 'stop'}
    if(LIVE){liveCall('tax-admin',{action:'receipt',id:f.dataset.id,receipt_ref:ref}).then(()=>{tr_('Accusé de réception enregistré.');dac7Load()}).catch(e=>tr_(e.message,true));return 'stop'}
    const y=S.dac7Year||new Date(now()).getFullYear()-1,x=(S.demoDecl[y]||[]).find(z=>z.id===f.dataset.id);if(x){x.status='transmise';x.receipt_ref=ref}toast('Démonstration : accusé de réception enregistré.');return true}
  if(k==='taxinfo2'){const e=m=>{const p=document.getElementById('t2-err');p.textContent=tr(m);p.hidden=false;return 'stop'},nif=String(d.nif||'').replace(/\s/g,''),bc=String(d.bcountry||'').trim().toUpperCase();
    if(d.country==='FR'&&nif&&!/^\d{13}$/.test(nif))return e('Le numéro fiscal français comporte 13 chiffres.');if(String(d.bcity||'').trim().length<2)return e('Indiquez votre ville de naissance.');if(!/^[A-Z]{2}$/.test(bc))return e('Pays de naissance : code à 2 lettres (FR, MA, BE…).');
    const c=comp('c1');c.tax={...(c.tax||{}),nif,country:d.country,birthCity:String(d.bcity).trim(),birthCountry:bc};
    if(LIVE)SB.from('companions').update({nif:nif||null,tax_country:d.country,birth_city:c.tax.birthCity,birth_country:bc}).eq('id',ME.id).then(({error})=>tr_(error?'Enregistrement impossible.':'Informations fiscales enregistrées.',!!error));else toast('Informations fiscales enregistrées.');return true}
  return false}
function liveTaxLoad(){if(!LIVE||!ME||ME.role!=='companion')return;const y=S.fiscalYear||new Date(now()).getFullYear();
  Promise.all([SB.rpc('my_tax_year',{p_year:y}),SB.from('tax_certificates').select('year,version,data,published_at').order('year',{ascending:false}),SB.from('companions').select('nif,tax_country,birth_city,birth_country,tax_id,postal_address').eq('id',ME.id).single()]).then(([m,c,p])=>{
    S.liveTax={year:y,months:m.data||[]};S.liveCerts=c.data||[];const x=p.data||{},cc=comp('c1');if(cc)cc.tax={...(cc.tax||{}),nif:x.nif||'',country:x.tax_country||'FR',birthCity:x.birth_city||'',birthCountry:x.birth_country||'FR',id:x.tax_id||'',addr:x.postal_address||'',dob:ME.birth_date};render()})}
function v27Init(){if(window.__v27)return;window.__v27=1;
  // listes déroulantes : traitées au changement de valeur (un clic ne doit pas refermer la liste)
  const _ec=extChange;extChange=el=>{const map={buf:'buffer',fy:'fiscal-year',d7y:'dac7-year'}[el.id];if(map){const r=map==='buffer'?v26Click('buffer',el):dac7Click(map,el);if(r)render();return true}return _ec(el)};
  const _py=pYearCard;pYearCard=(...x)=>fiscalDocs()+_py(...x);
  EXTRA_SHEETS.dac7admin=(s,h)=>dac7Sheet(s,h);
  const c=comp('c1');if(c){c.tax={...(c.tax||{}),nif:'1 93 04 75 112 233 44'.replace(/\s/g,'').slice(0,13),country:'FR',birthCity:'Lyon',birthCountry:'FR'};const y=new Date(now()).getFullYear()-1;c.certs=[{year:y-1,version:1,published:new Date(y,0,20).getTime()}]}
  if(LIVE){const _l=liveLoad;liveLoad=async(...x)=>{const r=await _l(...x);liveTaxLoad();return r};
    const _d=lAdmDash;aDash=lAdmDash=(...x)=>_d(...x)+`<section class="section"><button class="btn full" data-a="dac7">Fiscalité et déclarations DAC7</button></section>`;
    const _sub=v23Submit;v23Submit=(k,f,d)=>{const r=_sub(k,f,d);if(k==='taxinfo'&&r&&r!=='stop'){const t=comp('c1').tax||{};SB.from('companions').update({tax_id:(t.id||'').replace(/\s/g,'')||null,postal_address:t.addr||null}).eq('id',ME.id).then(({error})=>{if(error)tr_('Enregistrement impossible.',true)})}return r}}}

/* ================= V2.8 — Assurance responsabilité civile des accompagnateurs ; compléments fiscaux DAC7 ================= */
// Side by Side n'est pas un assureur : chaque accompagnateur souscrit son propre contrat, la plateforme vérifie l'attestation.
const INS_ST={valide:['Validée','t-ok'],expire_bientot:['Expire bientôt','t-warn'],en_attente:['En attente de validation','t-info'],refusee:['Refusée','t-bad'],expiree:['Expirée','t-bad'],aucune:['Aucune attestation','t-warn']};
const INS_DEC={depot:'Dépôt',validee:'Validation',refusee:'Refus',expiree:'Expiration',consultation:'Consultation du justificatif'};
const isoDay=t=>new Date(t).toLocaleDateString('en-CA',{timeZone:'Europe/Paris'});
const frDay=s=>s?String(s).slice(0,10).split('-').reverse().join('/'):'';
const insPill=st=>`<span class="pill ${(INS_ST[st]||['',''])[1]}">${(INS_ST[st]||[st])[0]}</span>`;
function insState(i,t){const d=isoDay(t||now());if(i.status==='validee'){if(i.end<d)return'expiree';return (Date.parse(i.end)-Date.parse(d))/DAY<=30?'expire_bientot':'valide'}return i.status}
function insList(cid){if(LIVE&&cid==='c1')return S.liveIns||[];const c=comp(cid);return (c&&c.ins)||[]}
// Réservable : attestation validée couvrant toute la prestation (sauf si la direction a désactivé l'obligation)
function insOk(cid,start,hours){if(S.insRequired===false)return true;const a=isoDay(start),z=isoDay(start+(hours||1)*H);return insList(cid).some(i=>i.status==='validee'&&i.start<=a&&i.end>=z)}
function insCurrent(cid){const L=insList(cid).slice().sort((a,b)=>b.created-a.created),d=isoDay(now());
  const ok=L.filter(i=>i.status==='validee'&&i.end>=d).sort((a,b)=>b.end.localeCompare(a.end))[0];return{ok,last:L[0],L}}

/* ---------- Espace accompagnateur : « Mon assurance » ---------- */
function insCard(){const {ok,last,L}=insCurrent('c1'),st=ok?insState(ok):last?insState(last):'aucune',d=isoDay(now());
  return `<section class="section"><form class="card stack" data-form="ins-up"><div class="row"><span class="lbl grow">Mon assurance</span>${insPill(st)}</div>
  <p class="xs muted">Chaque accompagnateur souscrit, à ses frais, une assurance responsabilité civile couvrant son activité rémunérée d'accompagnement. Side by Side n'est pas un assureur et ne fournit aucune garantie : la plateforme vérifie uniquement votre attestation.</p>
  ${ok?`<div class="note ${st==='expire_bientot'?'t-warn':'t-ok'} sm">${esc(ok.insurer)} · contrat n° ${esc(ok.policy)} · valable du ${frDay(ok.start)} au ${frDay(ok.end)}${st==='expire_bientot'?' — pensez à déposer votre nouvelle attestation':''}</div>`:'<div class="note t-warn sm">Sans attestation validée et en cours de validité, vous ne pouvez pas recevoir de nouvelles réservations.</div>'}
  ${last&&last.status==='refusee'?`<div class="note t-bad sm">Dernière attestation refusée : ${esc(last.reason||'motif non précisé')}</div>`:''}
  ${last&&last.status==='en_attente'?'<p class="xs t-info">Attestation en cours de vérification par l\'équipe Side by Side.</p>':''}
  <div class="field"><label for="in-co">Compagnie d'assurance</label><input id="in-co" name="insurer" maxlength="100" autocomplete="organization"></div>
  <div class="field"><label for="in-no">Numéro du contrat</label><input id="in-no" name="policy" maxlength="50" autocomplete="off"></div>
  <div class="row"><div class="field grow"><label for="in-s">Début de validité</label><input id="in-s" name="start" type="date"></div><div class="field grow"><label for="in-e">Date d'expiration</label><input id="in-e" name="end" type="date" min="${d}"></div></div>
  <div class="field"><label for="in-f">Attestation d'assurance (PDF, JPG ou PNG, 10 Mo maximum)</label><input id="in-f" name="doc" type="file" accept="application/pdf,image/jpeg,image/png"></div>
  <label class="row sm"><input type="checkbox" name="covers" value="1"> Je confirme que mes garanties couvrent les prestations rémunérées d'accompagnement réalisées par l'intermédiaire de Side by Side.</label>
  <p class="xs muted">Rappels automatiques 30, 15, 7 et 1 jour avant l'expiration. Document conservé dans un espace privé, consultable uniquement par vous et les administrateurs habilités.</p>
  <p class="note t-bad sm" id="ins-err" hidden></p><button class="btn pri">${ok?'Déposer une nouvelle attestation':'Transmettre pour vérification'}</button>
  ${L.length?`<details><summary class="sm">Historique de mes attestations</summary>${L.map(i=>`<div class="row xs"><span class="grow">${esc(i.insurer)} · ${frDay(i.start)} → ${frDay(i.end)} · déposée le ${fshort(i.created)}${i.status==='refusee'&&i.reason?` · ${esc(i.reason)}`:''}</span>${insPill(insState(i))}</div>`).join('')}</details>`:''}
  </form></section>`}

/* ---------- Espace administrateur : « Gestion des assurances » ---------- */
function insData(){
  if(LIVE)return S.liveInsAdm||null;
  const rows=[];S.companions.forEach(c=>(c.ins||[]).forEach(i=>rows.push({...i,cid:c.id,name:c.name,state:insState(i)})));
  const insured=new Set(rows.filter(r=>['valide','expire_bientot'].includes(r.state)).map(r=>r.cid));
  const uninsured=S.companions.filter(c=>c.verified==='ok'&&!insured.has(c.id)).map(c=>({cid:c.id,name:c.name}));
  const affected=S.bookings.filter(b=>['en_attente','acceptee','paiement_confirme','confirmee','controle'].includes(b.status)&&b.start>now()&&!insOk(b.companionId,b.start,b.hours)).map(b=>({id:b.id,ref:b.ref,name:(comp(b.companionId)||{}).name,start:b.start}));
  const st=rows.map(r=>r.state);
  return{rows,uninsured,affected,history:S.insHist||[],required:S.insRequired!==false,demo:true,
    counts:{assures:insured.size,attente:st.filter(s=>s==='en_attente').length,bientot:st.filter(s=>s==='expire_bientot').length,expirees:st.filter(s=>s==='expiree').length,sans:uninsured.length}}}
function insLoad(){if(!LIVE)return;liveCall('insurance',{action:'list'}).then(r=>{
  S.liveInsAdm={...r,rows:(r.rows||[]).map(i=>({id:i.id,cid:i.companion_id,name:i.name,insurer:i.insurer,policy:i.policy_number,start:i.starts_on,end:i.ends_on,status:i.status,reason:i.refusal_reason,created:Date.parse(i.created_at),state:i.state})),
    uninsured:(r.uninsured||[]).map(u=>({cid:u.companion_id,name:u.name})),affected:(r.affected||[]).map(b=>({id:b.booking_id,ref:b.ref,name:b.companion_name,start:Date.parse(b.starts_at)})),
    history:(r.history||[]).map(h=>({insId:h.insurance_id,decision:h.decision,reason:h.reason,t:Date.parse(h.created_at)}))};render()}).catch(e=>tr_(e.message,true))}
const INS_F=[['tous','Toutes les attestations'],['attente','En attente de validation'],['assures','Accompagnateurs assurés'],['bientot','Expirent sous 30 jours'],['expirees','Expirées'],['refusees','Refusées']];
function insSheet(s,head){const D=insData(),top=head('Gestion des assurances','Attestations de responsabilité civile des accompagnateurs');
  if(!D)return top+'<p class="muted">Chargement…</p>';
  const q=(S.insQ||'').toLowerCase(),f=S.insF||'tous',match={tous:()=>true,attente:r=>r.state==='en_attente',assures:r=>['valide','expire_bientot'].includes(r.state),bientot:r=>r.state==='expire_bientot',expirees:r=>r.state==='expiree',refusees:r=>r.state==='refusee'}[f]||(()=>true);
  const rows=D.rows.filter(match).filter(r=>!q||`${r.name} ${r.insurer} ${r.policy}`.toLowerCase().includes(q)).sort((a,b)=>(a.state==='en_attente'?0:1)-(b.state==='en_attente'?0:1)||b.created-a.created);
  const K=(l,v)=>`<div class="card kpi"><span class="lbl">${l}</span><span class="num">${v}</span></div>`,byId=id=>D.rows.find(r=>r.id===id);
  return top+`${D.demo?'<div class="note t-warn sm">Démonstration : attestations fictives.</div>':''}
  <p class="xs muted">Side by Side ne finance pas d'assurance collective et n'est pas assureur : chaque accompagnateur souscrit son propre contrat. L'équipe vérifie l'attestation ; sans attestation validée et en cours de validité, les nouvelles réservations sont bloquées automatiquement, puis réactivées dès la validation d'une nouvelle attestation.</p>
  <div class="kpis">${K('Accompagnateurs assurés',D.counts.assures)}${K('En attente de validation',D.counts.attente)}${K('Expirent sous 30 jours',D.counts.bientot)}${K('Attestations expirées',D.counts.expirees)}${K('Sans assurance valide',D.counts.sans)}</div>
  <div class="row sm"><span class="grow">Assurance obligatoire pour être réservé : <b>${D.required?'activée':'désactivée'}</b></span><button class="btn ghost" data-a="ins-required">${D.required?'Désactiver':'Activer'}</button></div>
  <form class="row" data-form="ins-search"><input name="q" aria-label="Rechercher" placeholder="Nom, compagnie, n° de contrat" value="${esc(S.insQ||'')}" class="grow"><select name="f" aria-label="Filtre">${INS_F.map(([k,l])=>`<option value="${k}" ${k===f?'selected':''}>${l}</option>`).join('')}</select><button class="btn">Rechercher</button></form>
  <span class="lbl">${(INS_F.find(x=>x[0]===f)||INS_F[0])[1]} (${rows.length})</span>
  ${rows.map(r=>`<div class="card stack"><div class="row"><b class="grow">${esc(r.name)}</b>${insPill(r.state)}</div>
    <div class="xs muted">${esc(r.insurer)} · contrat n° ${esc(r.policy)} · du ${frDay(r.start)} au ${frDay(r.end)} · déposée le ${fshort(r.created)}${r.reason?` · motif : ${esc(r.reason)}`:''}</div>
    <div class="row"><button class="btn ghost" data-a="ins-doc" data-id="${r.id}">Consulter le justificatif</button>${r.state==='en_attente'?`<button class="btn pri" data-a="ins-ok" data-id="${r.id}">Valider</button>`:''}</div>
    ${r.state==='en_attente'?`<form class="row" data-form="ins-refuse" data-id="${r.id}"><input name="reason" class="grow" maxlength="500" aria-label="Motif du refus" placeholder="Motif du refus (obligatoire)"><button class="btn bad">Refuser</button></form>`:''}</div>`).join('')||'<p class="xs muted">Aucune attestation pour ce filtre.</p>'}
  <span class="lbl">Réservations à venir non couvertes (${D.affected.length})</span>
  ${D.affected.map(b=>`<div class="row sm"><span class="grow">${esc(b.ref)} · ${esc(b.name||'')} · ${fshort(b.start)}</span><span class="pill t-warn">À examiner</span></div>`).join('')||'<p class="xs muted">Aucune réservation existante affectée.</p>'}
  <span class="lbl">Accompagnateurs sans assurance valide (${D.uninsured.length})</span>
  <p class="xs">${D.uninsured.map(u=>esc(u.name)).join(' · ')||'<span class="muted">Aucun.</span>'}</p>
  <details><summary class="sm"><b>Historique des vérifications</b></summary>${D.history.slice(0,60).map(h=>{const r=byId(h.insId);return `<div class="xs row"><span class="grow">${fshort(h.t)} · ${INS_DEC[h.decision]||h.decision}${r?` · ${esc(r.name)} (${esc(r.insurer)})`:''}${h.reason?` · ${esc(h.reason)}`:''}</span></div>`}).join('')||'<p class="xs muted">Aucune vérification.</p>'}</details>
  <p class="xs muted">Chaque consultation, validation et refus est journalisé. Justificatifs conservés dans un espace privé, accessibles uniquement aux administrateurs avec double authentification.</p>`}

/* ---------- Fiscalité : informations selon le statut et ventilation des montants ---------- */
const luhnOk=v=>/^\d+$/.test(v)&&[...v].reverse().reduce((a,c,i)=>{let d=+c;if(i%2){d*=2;if(d>9)d-=9}return a+d},0)%10===0;
const EU27=['AT','BE','BG','CY','CZ','DE','DK','EE','ES','FI','FR','GR','HR','HU','IE','IT','LT','LU','LV','MT','NL','PL','PT','RO','SE','SI','SK'];
// Mêmes règles que le serveur (fonction tax_profile_issues) : informations manquantes ou incorrectes
function taxIssues(c){const t=c.tax||{},a=c.adm||{},legal=a.legal||t.legal||'',nif=(t.nif||'').replace(/\s/g,''),siret=(a.siret||t.id||'').replace(/\s/g,''),vat=t.vat||'',out=[],add=(field,message,blocking=true)=>out.push({field,message,blocking});
  if(!legal)add('statut','Statut à indiquer : particulier, micro-entrepreneur ou société (Profil → Informations administratives)');
  if(!/\d{5}/.test(t.addr||''))add('adresse','Adresse postale manquante ou incomplète (rue, code postal, ville)');
  if(legal!=='societe'){if(!t.dob)add('naissance','Date de naissance manquante');if(!t.birthCity)add('lieu de naissance','Ville de naissance manquante');
    if(!nif)add('NIF','Numéro fiscal manquant (il figure sur votre avis d\'impôt)',false);else if((t.country||'FR')==='FR'&&!/^[0-3]\d{12}$/.test(nif))add('NIF','Numéro fiscal incorrect : 13 chiffres commençant par 0, 1, 2 ou 3')}
  if(legal==='micro'||legal==='societe'){if(!/^\d{14}$/.test(siret))add('SIRET','Numéro SIRET manquant ou incorrect (14 chiffres)');else if(!luhnOk(siret))add('SIRET','Numéro SIRET à vérifier (clé de contrôle invalide)',false)}
  if(legal==='societe'&&!t.business)add('raison sociale','Raison sociale de la société manquante');
  if(vat.startsWith('FR')&&!/^FR[0-9A-Z]{2}\d{9}$/.test(vat))add('TVA','Numéro de TVA intracommunautaire incorrect (FR + 2 caractères + SIREN)');
  if(!EU27.includes(t.country||'FR'))add('résidence','Résidence fiscale hors Union européenne : situation à vérifier',false);return out}
// Ventilation par accompagnateur : payé par le client, frais client, commission, net versé, remboursements, annulations, taxes
function demoBreakdown(y){return S.companions.map(c=>{const o={companion_id:c.id,name:c.name,missions:0,client_paid:0,client_fees:0,client_vat:0,gross:0,commission:0,annex:0,tips:0,net_paid:0,declarable:0,cancelled:0,refunds:0,taxes:0},mine=S.bookings.filter(b=>b.companionId===c.id);
  mine.filter(b=>b.status==='cloturee'&&payoutDone(b)&&new Date(stepT(b,'cloturee')||endOf(b)).getFullYear()===y).forEach(b=>{const g=b.prest+(b.extensions||[]).reduce((s,e)=>s+(e.prest||0),0),tip=b.tip||0;
    o.missions++;o.client_paid+=(b.total||0)+tip;o.client_fees+=b.service||0;o.client_vat+=b.tva||0;o.gross+=g;o.commission+=b.comm||0;o.annex+=b.annex||0;o.tips+=tip;o.net_paid+=(b.payout||0)+tip;o.declarable+=g-(b.comm||0)+tip});
  const refs=new Set(mine.map(b=>b.ref));o.refunds=-S.ledger.filter(l=>String(l.type).startsWith('Remboursement')&&refs.has(l.ref)&&new Date(l.t).getFullYear()===y).reduce((a,l)=>a+l.amount,0);
  o.cancelled=mine.filter(b=>b.status==='annulee'&&new Date(b.start).getFullYear()===y).length;return o}).filter(o=>o.missions||o.refunds||o.cancelled)}
function myBreakdownHtml(y){const B=LIVE?(S.liveMyBd&&S.liveMyBd.year===y?S.liveMyBd.row:null):demoBreakdown(y).find(x=>x.companion_id==='c1');const b=B||{missions:0,gross:0,commission:0,annex:0,tips:0,net_paid:0,declarable:0,cancelled:0,taxes:0};
  const R=(l,v,x='')=>`<div class="row sm"><span class="grow">${l}</span><span class="num ${x}">${v}</span></div>`;
  return `<details class="card"><summary class="sm"><b>Détail des montants ${y}</b></summary>
  ${R('Montant brut des prestations',eur(+b.gross))}${R('Commission Side by Side retenue',eur(-b.commission))}${R('Pourboires reçus',eur(+b.tips))}${R('Montant net versé pour vos prestations',eur(+b.declarable),'t-ok')}${R('Frais annexes remboursés (non imposables, non déclarés)',eur(+b.annex))}${R('Réservations annulées dans l\'année',b.cancelled||0)}${R('Taxes prélevées par Side by Side',eur(+b.taxes||0))}
  <p class="xs muted">Montant déclaré à l'administration fiscale : le net versé pour vos prestations, rattaché à la date de chaque versement. Les frais de service payés par les clients ne font pas partie de vos revenus. En cas de remboursement partiel du client après un litige, seul le montant réellement versé est retenu.</p></details>`}
function taxStatusCard(){const c=comp('c1');if(!c)return'';const t=c.tax||{},legal=(c.adm&&c.adm.legal)||t.legal||'',I=LIVE&&S.liveIssues?S.liveIssues:taxIssues(c),bl=I.filter(i=>i.blocking);
  const L={particulier:'Particulier (activité occasionnelle)',micro:'Micro-entrepreneur',societe:'Société'}[legal];
  return `<section class="section"><form class="card stack" data-form="taxinfo3"><div class="row"><span class="lbl grow">Contrôle de mes informations fiscales</span>${bl.length?`<span class="pill t-warn">${bl.length} à compléter</span>`:'<span class="pill t-ok">Complètes</span>'}</div>
  <p class="xs">Statut : <b>${L||'non indiqué'}</b> <span class="muted">(modifiable dans Profil → Informations administratives)</span></p>
  ${I.length?I.map(i=>`<div class="xs ${i.blocking?'t-bad':'t-warn'}">• ${esc(i.message)}</div>`).join(''):'<p class="xs t-ok">Toutes les informations exigées pour votre statut sont renseignées.</p>'}
  <p class="xs muted">Particulier et micro-entrepreneur : identité, date et lieu de naissance, adresse, numéro fiscal${legal==='micro'?', SIRET':''}. Société : raison sociale, SIRET, adresse du siège, numéro de TVA s'il existe.</p>
  ${legal==='societe'?`<div class="field"><label for="t3-bn">Raison sociale</label><input id="t3-bn" name="business" maxlength="120" value="${esc(t.business||'')}"></div>`:''}
  ${legal==='micro'||legal==='societe'?`<div class="field"><label for="t3-vat">Numéro de TVA intracommunautaire (s'il existe)</label><input id="t3-vat" name="vat" maxlength="15" value="${esc(t.vat||'')}" placeholder="FR00123456789" autocomplete="off" style="text-transform:uppercase"></div><p class="note t-bad sm" id="t3-err" hidden></p><button class="btn">Enregistrer</button>`:''}
  </form></section>`}

/* ---------- Déclarations DAC7 : statuts, documents officiels, téléchargement groupé ---------- */
const STAGE={a_preparer:['À préparer','t-info'],incomplet:['Incomplet','t-warn'],pret:['Prêt','t-info'],transmis:['Transmis','t-ok'],accepte:['Accepté','t-ok'],rejete:['Rejeté','t-bad'],a_corriger:['À corriger','t-warn']};
const STAGE_TXT={a_preparer:'Aucune déclaration préparée pour cette année.',incomplet:'Des informations obligatoires manquent : vérifiez-les avant de générer la déclaration.',pret:'Déclaration prête : validez-la, puis transmettez-la sur impots.gouv.fr.',transmis:'Déclaration transmise : en attente du compte rendu officiel de l\'administration fiscale.',accepte:'Acceptation confirmée par un document officiel importé.',rejete:'Déclaration rejetée par l\'administration : générez et transmettez un nouveau fichier.',a_corriger:'Erreurs signalées par l\'administration : générez une déclaration corrective.'};
const OFF={recu:'Accusé de réception (dépôt reçu)',accepte:'Acceptée',accepte_avec_erreurs:'Acceptée avec erreurs à corriger',rejete:'Rejetée'};
function stageOf(decls,blocking){const base=decls.filter(d=>!['annulee','brouillon'].includes(d.status)).pop(),draft=decls.some(d=>d.status==='brouillon');
  if(!base)return blocking?'incomplet':draft?'pret':'a_preparer';return{validee:'pret',transmise:'transmis',acceptee:'accepte',rejetee:'rejete',a_corriger:'a_corriger'}[base.status]||'a_preparer'}
function parseSM(xml){const all=n=>[...xml.matchAll(new RegExp(`<(?:\\w+:)?${n}>([^<]*)</(?:\\w+:)?${n}>`,'g'))].map(m=>m[1].trim());
  const st=(all('Status')[0]||all('FileAcceptanceStatus')[0]||'').toLowerCase();
  const errors=[...xml.matchAll(/<(?:\w+:)?RecordError>([\s\S]*?)<\/(?:\w+:)?RecordError>/g)].map(m=>({code:(m[1].match(/<(?:\w+:)?Code>([^<]*)</)||[])[1]||'',details:((m[1].match(/<(?:\w+:)?Details[^>]*>([^<]*)</)||[])[1]||'').slice(0,300),doc_ref_id:(m[1].match(/<(?:\w+:)?DocRefIDInError>([^<]*)</)||[])[1]||''}));
  const rejected=/reject|rejet/.test(st)||/<(?:\w+:)?FileError>/.test(xml),accepted=/accept/.test(st);
  return{original:all('OriginalMessageRefID')[0]||'',official:rejected?'rejete':accepted?(errors.length?'accepte_avec_erreurs':'accepte'):'recu',errors}}
function dac7Extra(D,y){const decl=D.declarations||[],stage=D.stage||stageOf(decl,D.blocking>0),errs=decl.filter(d=>d.status==='a_corriger').flatMap(d=>(d.errors||[]).map(e=>({...e,ref:d.message_ref_id})));
  const bd=D.breakdown||(D.demo?demoBreakdown(y):[]),tot=k=>bd.reduce((a,x)=>a+(+x[k]||0),0),rc=D.receipts||((S.demoRcpt||{})[y]||[]);
  const target=decl.filter(d=>['validee','transmise','a_corriger'].includes(d.status));
  return `<span class="lbl">Ventilation des montants ${y}</span>
  <div class="tbl"><table class="t"><tr><th>Accompagnateur</th><th>Payé par le client</th><th>Frais client (TTC)</th><th>Commission</th><th>Net versé</th><th>Rembours.</th><th>Déclarable</th></tr>
  ${bd.map(x=>`<tr><td>${esc(x.name)}${x.cancelled?` <span class="xs muted">· ${x.cancelled} annulation(s)</span>`:''}</td><td class="num">${eur(+x.client_paid)}</td><td class="num">${eur(+x.client_fees+ +x.client_vat)}</td><td class="num">${eur(+x.commission)}</td><td class="num">${eur(+x.net_paid)}</td><td class="num">${eur(+x.refunds)}</td><td class="num"><b>${eur(+x.declarable)}</b></td></tr>`).join('')||'<tr><td colspan="7" class="muted">Aucun mouvement sur l\'année.</td></tr>'}
  ${bd.length?`<tr class="tot"><td><b>Total</b></td><td class="num"><b>${eur(tot('client_paid'))}</b></td><td class="num"><b>${eur(tot('client_fees')+tot('client_vat'))}</b></td><td class="num"><b>${eur(tot('commission'))}</b></td><td class="num"><b>${eur(tot('net_paid'))}</b></td><td class="num"><b>${eur(tot('refunds'))}</b></td><td class="num"><b>${eur(tot('declarable'))}</b></td></tr>`:''}</table></div>
  <p class="xs muted">Taux appliqués à chaque réservation : frais de service client ${S.settings&&S.settings.clientFee||15} % (+ TVA), commission accompagnateur ${S.settings&&S.settings.compFee||20} %. Déclarable = prestations − commission + pourboires, après remboursement partiel éventuel (litige) ; frais annexes remboursés, frais client et TVA exclus. Net versé = virement réel à l'accompagnateur, frais annexes compris. Taxes prélevées par la plateforme : 0 €.</p>
  ${errs.length?`<div class="card stack"><span class="lbl t-bad">Erreurs signalées par l'administration fiscale (${errs.length})</span>${errs.map(e=>`<div class="xs">${esc(e.code)} · ${esc(e.details||'')} <span class="muted">(${esc(e.doc_ref_id)})</span></div>`).join('')}<button class="btn pri" data-a="dac7-fix">Générer la déclaration corrective</button></div>`:''}
  <form class="card stack" data-form="dac7-import"><span class="lbl">Importer un accusé de réception ou un compte rendu officiel</span>
  ${target.length?`<div class="field"><label for="d7d">Déclaration concernée</label><select id="d7d" name="id">${target.map(d=>`<option value="${d.id}">v${d.version} · ${esc(d.message_ref_id)}</option>`).join('')}</select></div>
  <div class="field"><label for="d7f">Document (XML de compte rendu DGFiP ou PDF, 5 Mo maximum)</label><input id="d7f" name="file" type="file" accept=".xml,.pdf,application/xml,text/xml,application/pdf"></div>
  <div class="field"><label for="d7o">Statut indiqué sur le document (obligatoire pour un PDF ; lu automatiquement dans un XML)</label><select id="d7o" name="official"><option value="">Lire dans le document XML</option>${Object.entries(OFF).map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select></div>
  <div class="field"><label for="d7ref">Référence figurant sur le document</label><input id="d7ref" name="reference" autocomplete="off" maxlength="120"></div>
  <p class="xs muted">Une déclaration n'est jamais considérée comme acceptée sans document officiel importé.</p><button class="btn">Importer le document</button>`:'<p class="xs muted">Disponible après la validation d\'une déclaration.</p>'}</form>
  <button class="btn" data-a="dac7-zip" ${decl.some(d=>['validee','transmise','acceptee','a_corriger'].includes(d.status))?'':'disabled'}>Télécharger toutes les attestations (ZIP)</button>
  <span class="lbl">Documents officiels reçus</span>${rc.length?rc.map(r=>`<div class="row sm"><span class="grow">${fshort(Date.parse(r.created_at)||r.t)} · ${esc(r.reference)} · ${esc(r.file_name||'')}</span><span class="pill ${{accepte:'t-ok',recu:'t-info',accepte_avec_erreurs:'t-warn',rejete:'t-bad'}[r.official_status]}">${OFF[r.official_status]}</span></div>`).join(''):'<p class="xs muted">Aucun document officiel importé.</p>'}`}
function stageBanner(D,y){const st=D.stage||stageOf(D.declarations||[],D.blocking>0),p=STAGE[st];return `<div class="card row"><span class="grow sm">Déclaration ${y} : <b>${p[0]}</b><br><span class="xs muted">${STAGE_TXT[st]}</span></span><span class="pill ${p[1]}">${p[0]}</span></div>`}

/* ---------- Téléchargement groupé : archive ZIP (sans compression) d'attestations PDF ---------- */
const CRC=(()=>{const t=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xEDB88320^(c>>>1):c>>>1;t[n]=c>>>0}return t})();
const crc32=b=>{let c=0xFFFFFFFF;for(let i=0;i<b.length;i++)c=CRC[(c^b[i])&255]^(c>>>8);return(c^0xFFFFFFFF)>>>0};
function makeZip(files){const enc=new TextEncoder(),parts=[],central=[];let off=0;
  const dt=new Date(now()),dosT=(dt.getHours()<<11)|(dt.getMinutes()<<5)|(dt.getSeconds()>>1),dosD=((dt.getFullYear()-1980)<<9)|((dt.getMonth()+1)<<5)|dt.getDate();
  for(const f of files){const name=enc.encode(f.name),data=f.bytes,crc=crc32(data),h=new DataView(new ArrayBuffer(30));
    [[0,0x04034b50,4],[4,20,2],[6,0x0800,2],[8,0,2],[10,dosT,2],[12,dosD,2],[14,crc,4],[18,data.length,4],[22,data.length,4],[26,name.length,2],[28,0,2]].forEach(([o,v,s])=>s===4?h.setUint32(o,v,true):h.setUint16(o,v,true));
    parts.push(new Uint8Array(h.buffer),name,data);const c=new DataView(new ArrayBuffer(46));
    [[0,0x02014b50,4],[4,20,2],[6,20,2],[8,0x0800,2],[10,0,2],[12,dosT,2],[14,dosD,2],[16,crc,4],[20,data.length,4],[24,data.length,4],[28,name.length,2],[30,0,2],[32,0,2],[34,0,2],[36,0,2],[38,0,4],[42,off,4]].forEach(([o,v,s])=>s===4?c.setUint32(o,v,true):c.setUint16(o,v,true));
    central.push(new Uint8Array(c.buffer),name);off+=30+name.length+data.length}
  const csize=central.reduce((a,x)=>a+x.length,0),e=new DataView(new ArrayBuffer(22));
  [[0,0x06054b50,4],[4,0,2],[6,0,2],[8,files.length,2],[10,files.length,2],[12,csize,4],[16,off,4],[20,0,2]].forEach(([o,v,s])=>s===4?e.setUint32(o,v,true):e.setUint16(o,v,true));
  return new Blob([...parts,...central,new Uint8Array(e.buffer)],{type:'application/zip'})}
function certBytes(year,c){const d=c.data||{},q=d.quarters||[],legal=c.legal_status,nm=legal==='societe'&&c.business_name?c.business_name:(d.name||c.name||'');
  const lines=[`Attestation annuelle ${year}${c.version>1?` · version ${c.version}`:''}`,'',`Plateforme : Side by Side, éditée par ${LEGAL_CO.name} (${LEGAL_CO.form}), ${LEGAL_CO.addr}`,`Prestataire : ${nm}${legal==='societe'&&c.siret?` · SIRET ${c.siret}`:''}`,
    `Numéro fiscal : ${c.nif||'non communiqué'} · résidence fiscale : ${c.tax_country||'FR'}`,`Adresse : ${c.postal_address||'non communiquée'}`,'','Activité : prestations de services personnels (accompagnement)','',
    ...q.map((x,i)=>`Trimestre ${i+1} : ${x.missions} prestation(s) · revenus nets ${x.consideration} € · commissions et frais ${x.fees} € · taxes ${x.taxes||0} €`),'',
    `Total ${year} : ${d.missions||0} prestation(s) · revenus nets ${d.consideration||0} € · commissions et frais ${d.fees||0} €`,'','Montants en euros, arrondis à l\'euro le plus proche. Ces informations sont également transmises à la DGFiP',
    '(article 1649 ter A du Code général des impôts, directive DAC7). Vous devez déclarer vous-même ces revenus.','',LIVE?'':'DÉMONSTRATION : document fictif, sans valeur fiscale.'];
  return new Uint8Array(pdfBytes(`Attestation fiscale ${year}`,lines.join('\n')))}
function dac7Zip(y){const done=certs=>{if(!certs.length){toast('Aucune attestation générée pour cette année.',true);return}
    const used=new Set(),files=certs.map(c=>{let base=`Attestation-${y}-${String(c.business_name||c.data&&c.data.name||c.name||'accompagnateur').normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^A-Za-z0-9]+/g,'-').replace(/^-|-$/g,'')}`;let n=base,i=2;while(used.has(n))n=base+'-'+i++;used.add(n);return{name:n+'.pdf',bytes:certBytes(y,c)}});
    saveFile(`Attestations-fiscales-${y}${LIVE?'':'-demonstration'}.zip`,makeZip(files));toast(`${files.length} attestation(s) réunie(s) dans l'archive ZIP.`)};
  if(LIVE){liveCall('tax-admin',{action:'certificates_bundle',year:y}).then(r=>done(r.certificates||[])).catch(e=>tr_(e.message,true));return}
  if(!(comp('c1').certs||[]).some(x=>x.year===y)){toast('Générez d\'abord les attestations individuelles.',true);return}
  done(demoSellers(y).map(x=>({name:x.c.name,version:1,nif:x.t.nif,postal_address:x.t.addr,tax_country:x.t.country||'FR',data:{name:x.c.name,quarters:x.Q.map(q=>({missions:q.missions,consideration:netOf(q),fees:eurInt(q.fees),taxes:0})),missions:x.missions,consideration:x.Q.reduce((s,q)=>s+netOf(q),0),fees:x.Q.reduce((s,q)=>s+eurInt(q.fees),0)}})))}
const b64Of=file=>file.arrayBuffer().then(buf=>{let s='';const u=new Uint8Array(buf);for(let i=0;i<u.length;i+=32768)s+=String.fromCharCode.apply(null,u.subarray(i,i+32768));return btoa(s)});

/* ---------- Actions ---------- */
function v28Click(a,el,id,v,b){switch(a){
  case'ins-admin':S.insQ='';S.insF='tous';open('insadmin');insLoad();return true;
  case'ins-required':{const on=!(insData()||{}).required;if(LIVE){liveCall('insurance',{action:'required',on}).then(()=>{tr_(on?'Assurance obligatoire activée.':'Assurance obligatoire désactivée.');insLoad()}).catch(e=>tr_(e.message,true));return false}
    S.insRequired=on;log('Administrateur Side by Side',`Assurance obligatoire pour réserver : ${on?'activée':'désactivée'}`,'—');toast(on?'Assurance obligatoire activée.':'Assurance obligatoire désactivée.');return true}
  case'ins-doc':{const iid=el.dataset.id;if(LIVE){liveCall('insurance',{action:'doc',id:iid}).then(r=>{window.open(r.url,'_blank','noopener');insLoad()}).catch(e=>tr_(e.message,true));return false}
    const r=insData().rows.find(x=>x.id===iid);(S.insHist=S.insHist||[]).unshift({insId:iid,decision:'consultation',t:now()});log('Administrateur Side by Side','Assurance : consultation d\'un justificatif',r?r.name:'—');
    if(r&&r.file)saveFile(r.file.name,r.file);else toast('Démonstration : attestation fictive, aucun fichier réel.');return true}
  case'ins-ok':{const iid=el.dataset.id;if(LIVE){liveCall('insurance',{action:'review',id:iid,approve:true}).then(()=>{tr_('Attestation validée : réservations réactivées.');insLoad()}).catch(e=>tr_(e.message,true));return false}
    insReview(iid,true,'');return true}
  case'dac7-generate':{if(!LIVE)return false;const D=dac7Data(),corr=!!(D&&D.declarations.find(d=>['validee','transmise','acceptee','a_corriger'].includes(d.status)));
    liveCall('tax-admin',{action:'generate',year:S.dac7Year||new Date(now()).getFullYear()-1,correction:corr}).then(r=>{if(r&&r.xml)saveFile(`${r.declaration.message_ref_id}.xml`,new Blob([r.xml],{type:'application/xml'}));dac7Load()}).catch(e=>tr_(e.message,true));return true}
  case'dac7-fix':{const y=S.dac7Year||new Date(now()).getFullYear()-1;if(LIVE){liveCall('tax-admin',{action:'generate',year:y,correction:true}).then(r=>{if(r&&r.xml)saveFile(`${r.declaration.message_ref_id}.xml`,new Blob([r.xml],{type:'application/xml'}));tr_('Déclaration corrective générée : validez-la puis transmettez-la.');dac7Load()}).catch(e=>tr_(e.message,true));return true}
    const L=S.demoDecl[y]||[],src=L.find(d=>d.status==='a_corriger');if(!src)return true;let xml=demoXml(y,demoSellers(y)).replace('<dpi:MessageTypeIndic>DPI401','<dpi:MessageTypeIndic>DPI402').replace(/OECD11/g,'OECD12');
    L.push({id:'demo'+Date.now(),version:L.length+1,kind:'corrective',status:'brouillon',corrects:src.id,message_ref_id:xml.match(/<dpi:MessageRefId>([^<]+)/)[1],sellers:(src.errors||[]).length||1,total_consideration:dac7Data().total_consideration,xml});
    saveFile(`DAC7-${y}-DEMONSTRATION-corrective-test.xml`,new Blob([xml],{type:'application/xml'}));toast('Démonstration : déclaration corrective de test générée (à ne jamais transmettre).');return true}
  case'dac7-zip':dac7Zip(S.dac7Year||new Date(now()).getFullYear()-1);return false;
  default:return false}}
function insReview(iid,approve,reason){let r=null,cc=null;S.companions.forEach(c=>(c.ins||[]).forEach(i=>{if(i.id===iid){r=i;cc=c}}));if(!r||r.status!=='en_attente'){toast('Attestation déjà traitée.',true);return}
  if(approve&&r.end<isoDay(now())){r.status='expiree';toast('Attestation expirée : validation impossible.',true);return}
  r.status=approve?'validee':'refusee';r.reason=approve?null:reason;r.reviewed=now();(S.insHist=S.insHist||[]).unshift({insId:iid,decision:approve?'validee':'refusee',reason:approve?null:reason,t:now()});
  log('Administrateur Side by Side',`Assurance ${approve?'validée':'refusée'} : ${cc.name}${approve?'':` (${reason})`}`,'—');
  if(cc.id==='c1')notify('companion',approve?`Votre attestation d'assurance (${r.insurer}) est validée jusqu'au ${frDay(r.end)}. Vous pouvez recevoir des réservations.`:`Votre attestation d'assurance a été refusée : ${reason}. Déposez une nouvelle attestation dans Profil → Mon assurance.`);
  toast(approve?`Attestation de ${cc.name} validée : réservations réactivées.`:`Attestation de ${cc.name} refusée.`)}
function v28Submit(k,f,d){
  if(k==='ins-search'){S.insQ=String(d.q||'').trim();S.insF=d.f||'tous';return true}
  if(k==='ins-refuse'){const reason=String(d.reason||'').trim();if(reason.length<5){toast('Indiquez le motif du refus.',true);return 'stop'}
    if(LIVE){liveCall('insurance',{action:'review',id:f.dataset.id,approve:false,reason}).then(()=>{tr_('Attestation refusée : l\'accompagnateur est informé du motif.');insLoad()}).catch(e=>tr_(e.message,true));return 'stop'}
    insReview(f.dataset.id,false,reason);return true}
  if(k==='ins-up'){const e=m=>{const p=document.getElementById('ins-err');p.textContent=tr(m);p.hidden=false;return 'stop'},file=f.querySelector('[name=doc]').files[0],today=isoDay(now());
    const insurer=String(d.insurer||'').trim(),policy=String(d.policy||'').trim();
    if(insurer.length<2)return e('Indiquez le nom de la compagnie d\'assurance.');if(policy.length<3)return e('Indiquez le numéro du contrat.');
    if(!d.start||!d.end)return e('Indiquez les dates de début et d\'expiration.');if(d.end<=d.start)return e('La date d\'expiration doit suivre la date de début.');if(d.end<today)return e('Cette attestation est déjà expirée.');
    if(!file)return e('Ajoutez l\'attestation d\'assurance.');if(file.size>10*1024*1024||!/^(application\/pdf|image\/(jpeg|png))$/.test(file.type))return e('Attestation : PDF, JPG ou PNG, 10 Mo maximum.');
    if(!d.covers)return e('Confirmez que vos garanties couvrent les prestations rémunérées d\'accompagnement.');
    if(LIVE){(async()=>{const path=`${ME.id}/rc-${Date.now()}.${file.type==='application/pdf'?'pdf':file.type==='image/png'?'png':'jpg'}`;const up=await SB.storage.from('insurance').upload(path,file,{contentType:file.type});if(up.error)return tr_('Envoi de l\'attestation impossible.',true);
      const {error}=await SB.from('companion_insurances').insert({companion_id:ME.id,insurer,policy_number:policy,starts_on:d.start,ends_on:d.end,doc_path:path,covers_paid_activity:true});
      if(error)return tr_(/expir/.test(error.message)?'Cette attestation est déjà expirée.':'Enregistrement impossible.',true);tr_('Attestation transmise : vérification par l\'équipe Side by Side.');liveInsLoad()})();return true}
    const c=comp('c1'),it={id:'ins'+Date.now(),insurer,policy,start:d.start,end:d.end,status:'en_attente',created:now(),file};(c.ins=c.ins||[]).push(it);(S.insHist=S.insHist||[]).unshift({insId:it.id,decision:'depot',t:now()});
    notify('admin',`Nouvelle attestation d'assurance à vérifier (${c.name}).`);log(c.name,'Attestation d\'assurance déposée','—');toast('Attestation transmise : vérification par l\'équipe Side by Side.');return true}
  if(k==='taxinfo3'){const e=m=>{const p=document.getElementById('t3-err');p.textContent=tr(m);p.hidden=false;return 'stop'},vat=String(d.vat||'').replace(/\s/g,'').toUpperCase(),bn=String(d.business||'').trim(),c=comp('c1'),legal=(c.adm&&c.adm.legal)||'';
    if(legal==='societe'&&bn.length<2)return e('Indiquez la raison sociale.');if(vat&&!/^[A-Z]{2}[0-9A-Z]{2,13}$/.test(vat))return e('Numéro de TVA : 2 lettres du pays puis le numéro (ex. FR00123456789).');if(vat.startsWith('FR')&&!/^FR[0-9A-Z]{2}\d{9}$/.test(vat))return e('Numéro de TVA français : FR + 2 caractères + SIREN (9 chiffres).');
    c.tax={...(c.tax||{}),vat,...(legal==='societe'?{business:bn}:{})};
    if(LIVE){SB.from('companions').update({vat_number:vat||null,...(legal==='societe'?{business_name:bn}:{})}).eq('id',ME.id).then(({error})=>{tr_(error?'Enregistrement impossible.':'Informations enregistrées.',!!error);liveTaxLoad()})}else toast('Informations enregistrées.');return true}
  if(k==='dac7-import'){const file=f.querySelector('[name=file]').files[0],y=S.dac7Year||new Date(now()).getFullYear()-1,ref=String(d.reference||'').trim();
    if(!file){toast('Choisissez le document officiel (XML ou PDF).',true);return 'stop'}if(file.size>5*1024*1024){toast('Document trop volumineux (5 Mo au plus).',true);return 'stop'}
    const pdf=/pdf$/i.test(file.type)||/\.pdf$/i.test(file.name);if(pdf&&!d.official){toast('PDF : indiquez le statut figurant sur le document officiel.',true);return 'stop'}
    if(LIVE){b64Of(file).then(content_b64=>liveCall('tax-admin',{action:'import_receipt',year:y,id:d.id,file_name:file.name,content_b64,official_status:d.official||undefined,reference:ref||undefined}))
      .then(r=>{tr_(`Document importé : ${OFF[r.official]||r.official}${r.errors&&r.errors.length?` (${r.errors.length} erreur(s) à corriger)`:''}.`);dac7Load()}).catch(e=>tr_(e.message,true));return 'stop'}
    file.text().then(txt=>{const x=(S.demoDecl[y]||[]).find(z=>z.id===d.id);if(!x)return;let off=d.official,errors=[],reference=ref;
      if(!pdf){const p=parseSM(txt);if(p.original&&p.original!==x.message_ref_id){toast(`Ce compte rendu concerne une autre déclaration (${p.original}).`,true);return}off=p.official==='recu'&&d.official?d.official:p.official;errors=p.errors;reference=reference||p.original||x.message_ref_id}
      if(reference.length<3){toast('Indiquez la référence figurant sur le document officiel.',true);return}
      ((S.demoRcpt=S.demoRcpt||{})[y]=S.demoRcpt[y]||[]).push({reference,file_name:file.name,official_status:off,errors,t:now()});
      x.status={recu:'transmise',accepte:'acceptee',accepte_avec_erreurs:'a_corriger',rejete:'rejetee'}[off];x.errors=errors;x.receipt_ref=reference;
      if(x.status==='acceptee'&&x.corrects){const o=(S.demoDecl[y]||[]).find(z=>z.id===x.corrects&&z.status==='a_corriger');if(o){o.status='acceptee';o.errors=[]}}
      log('Administrateur Side by Side',`Fiscalité ${y} : document officiel importé (${OFF[off]})`,x.message_ref_id);toast(`Démonstration : document importé — ${OFF[off]}.`);render()});return 'stop'}
  return false}

/* ---------- Mode connecté : chargements ---------- */
function liveInsLoad(){if(!LIVE||!ME||ME.role!=='companion')return;SB.from('companion_insurances').select('id,insurer,policy_number,starts_on,ends_on,status,refusal_reason,created_at').order('created_at',{ascending:false}).then(({data})=>{
  S.liveIns=(data||[]).map(i=>({id:i.id,insurer:i.insurer,policy:i.policy_number,start:i.starts_on,end:i.ends_on,status:i.status,reason:i.refusal_reason,created:Date.parse(i.created_at)}));render()})}
function liveTax28(){if(!LIVE||!ME||ME.role!=='companion')return;const y=S.fiscalYear||new Date(now()).getFullYear();
  Promise.all([SB.rpc('tax_profile_issues',{p_companion:ME.id}),SB.rpc('my_tax_breakdown',{p_year:y}),SB.from('companions').select('business_name,vat_number').eq('id',ME.id).single()]).then(([i,b,c])=>{
    S.liveIssues=i.error?null:(i.data||[]);S.liveMyBd={year:y,row:(b.data||[])[0]||null};const cc=comp('c1'),x=c.data||{};if(cc)cc.tax={...(cc.tax||{}),business:x.business_name||'',vat:x.vat_number||''};render()})}

function v28Init(){if(window.__v28)return;window.__v28=1;
  Object.assign(DST,{a_corriger:['À corriger','t-warn']});
  EXTRA_SHEETS.insadmin=(s,h)=>insSheet(s,h);
  const _pP=pProfile;pProfile=(...x)=>_pP(...x)+insCard();
  const btn=`<section class="section"><button class="btn full" data-a="ins-admin">Gestion des assurances</button></section>`;
  const _aD=aDash;aDash=(...x)=>_aD(...x)+btn;if(LIVE&&typeof lAdmDash==='function'&&lAdmDash!==aDash){const _l=lAdmDash;lAdmDash=(...x)=>_l(...x)+btn}
  // Mes documents fiscaux : un seul contrôle des informations (selon le statut) et le détail des montants
  const _fd=fiscalDocs;fiscalDocs=(...x)=>{const y=S.fiscalYear||new Date(now()).getFullYear();return _fd(...x).replace(/<div class="note t-warn sm">Informations fiscales à compléter :[^<]*<\/div>/,'').replace('<span class="lbl">Attestations annuelles</span>',myBreakdownHtml(y)+'<span class="lbl">Attestations annuelles</span>')+taxStatusCard()};
  // Déclarations : statut détaillé, ventilation, documents officiels, ZIP
  const _ds=EXTRA_SHEETS.dac7admin;EXTRA_SHEETS.dac7admin=(s,h)=>{let x=_ds(s,h);const D=dac7Data(),y=S.dac7Year||new Date(now()).getFullYear()-1;if(!D)return x;
    const decl=D.declarations||[],fix=decl.some(d=>d.status==='a_corriger')&&!decl.some(d=>['validee','transmise','acceptee'].includes(d.status));
    if(fix)x=x.replace('Générer la déclaration DAC7 (XML)','Corriger une déclaration').replace('data-a="dac7-certs" disabled','data-a="dac7-certs"').replace('data-a="dac7-send" disabled','data-a="dac7-send"');
    return x.replace('<div class="kpis">',stageBanner(D,y)+'<div class="kpis">').replace('<span class="lbl">Historique des déclarations',dac7Extra(D,y)+'<span class="lbl">Historique des déclarations')};
  // Réservation : bloquée sans assurance valide de l'accompagnateur pendant toute la prestation
  const _cr=api.create.bind(api);api.create=(cid,fm)=>{const c=comp(cid),st=new Date(fm.start).getTime();if(!LIVE&&c&&!isNaN(st)&&!insOk(cid,st,+fm.hours||1))return{err:`${c.name} ne peut pas recevoir de réservation pour le moment (attestation d'assurance à jour en attente).`};return _cr(cid,fm)};
  // Données de démonstration (fictives) : la plupart des accompagnateurs assurés, un en attente, un expiré, un qui expire bientôt
  const CO=['AXA','MAIF','Hiscox','MMA','Groupama','Allianz','MACIF','Generali','Matmut','April'],d0=now();
  S.companions.forEach((c,i)=>{if(c.ins)return;const id='ins-'+c.id,start=isoDay(d0-(60+i*9)*DAY);
    if(c.id==='c13'){c.ins=[{id,insurer:'Matmut',policy:'RC-'+(482910+i),start:isoDay(d0-380*DAY),end:isoDay(d0-15*DAY),status:'expiree',created:d0-382*DAY}];return}
    if(c.id==='c12'){c.ins=[{id:id+'-1',insurer:'Generali',policy:'RC-'+(482910+i),start:isoDay(d0-370*DAY),end:isoDay(d0-5*DAY),status:'expiree',created:d0-372*DAY},{id,insurer:'Generali',policy:'RC-'+(582910+i),start:isoDay(d0-4*DAY),end:isoDay(d0+361*DAY),status:'en_attente',created:d0-DAY}];return}
    c.ins=[{id,insurer:CO[i%CO.length],policy:'RC-'+(482910+i*37),start,end:isoDay(d0+(c.id==='c6'?12:200+i*11)*DAY),status:'validee',created:d0-(62+i*9)*DAY,reviewed:d0-(61+i*9)*DAY}]});
  S.insHist=S.insHist||S.companions.flatMap(c=>(c.ins||[]).flatMap(i=>[{insId:i.id,decision:'depot',t:i.created},...(i.reviewed?[{insId:i.id,decision:'validee',t:i.reviewed}]:[]),...(i.status==='expiree'?[{insId:i.id,decision:'expiree',t:Date.parse(i.end)+DAY}]:[])])).sort((a,b)=>b.t-a.t);
  if(S.insRequired===undefined)S.insRequired=true;
  if(LIVE){const _l=liveLoad;liveLoad=async(...x)=>{const r=await _l(...x);liveInsLoad();liveTax28();return r};const _t=liveTaxLoad;liveTaxLoad=(...x)=>{_t(...x);liveTax28()}}}

