    if(!d.first||d.first.trim().length<2||!d.last||!d.last.trim())return err('cp-err','Indiquez votre prénom et votre nom.');if(!d.dob)return err('cp-err','Indiquez votre date de naissance.');{const b=new Date(d.dob+'T12:00:00'),a=new Date();a.setFullYear(a.getFullYear()-18);if(b>a)return err('cp-err','Inscription impossible : Side by Side est réservé aux personnes majeures.')}
    if(!String(d.city||'').trim())return err('cp-err','Indiquez votre ville.');const pe=phoneErr(d.dial,d.tel);if(pe)return err('cp-err',pe);
