      const {error}=await SB.from('profiles').update({first_name:first,last_name:last||'-',city,country:d.country,phone:d.tel?phoneE164(d.dial,d.tel):null,...(avatar_path?{avatar_path}:{})}).eq('id',ME.id);if(error)return tr_(/phone/.test(error.message)?'Ce numéro est déjà utilisé.':'Enregistrement impossible.',true);
