/* =====================================================================
   V3.0 — Application mobile : assistance intégrée, accès administrateur retiré,
   photos des accompagnateurs vérifiées avant publication
   ===================================================================== */
var ADMIN_TABS = ['dashboard'];
var ADMIN_VIEWS = { dashboard: () => '' };
var ADMIN_WEB = !!(window.SBS_ADMIN_WEB);

/* ---------- Comptes de l'équipe : refusés dans l'application mobile ---------- */
function adminRefusedPage() {
  if (LIVE && !S._admOut) { S._admOut = true; setTimeout(async () => { try { await SB.auth.signOut(); } catch (e) {} ME = null; S.role = null; S.adminOk = false; S._admOut = false; toast('Les comptes de l\'équipe Side by Side se connectent uniquement à l\'espace de gestion, sur ordinateur.', true); render(); }, 0); }
  return `<section class="section"><div class="card stack"><h2>Espace réservé à l'équipe</h2><p class="muted">Les comptes de l'équipe Side by Side se connectent uniquement à l'espace de gestion sécurisé, sur ordinateur.</p></div></section>`;
}

/* ---------- Assistance : mes demandes ---------- */
const SUP_CAT = [['reservation', 'Une réservation'], ['paiement', 'Paiement ou remboursement'], ['compte', 'Mon compte'], ['securite', 'Sécurité'], ['accompagnateur', 'Mon activité d\'accompagnateur'], ['technique', 'Problème technique'], ['suppression', 'Suppression de compte'], ['autre', 'Autre question']];
const SUP_ST = { ouverte: ['Envoyée', 'info'], en_cours: ['En cours de traitement', 'warn'], repondue: ['Réponse reçue', 'ok'], resolue: ['Résolue', 'muted'], fermee: ['Fermée', 'muted'] };
function supState() { if (!S.sup) S.sup = { list: [], loaded: false, msgs: {}, busy: false }; return S.sup; }
function supDemoSeed() {
  const Q = supState(); if (Q.loaded) return; Q.loaded = true;
  const t0 = now() - 2 * DAY;
  Q.list = [{ id: 'sd1', ref: 'AS-1001', category: 'paiement', subject: 'Question sur ma facture', status: 'repondue', created_at: new Date(t0).toISOString(), last_message_at: new Date(t0 + 3 * 3600e3).toISOString() }];
  Q.msgs.sd1 = [{ from_staff: false, body: 'Bonjour, je ne trouve pas la facture de ma dernière sortie.', created_at: new Date(t0).toISOString() },
                { from_staff: true, body: 'Bonjour, vos factures se trouvent dans Réservations, puis Détails de la réservation, rubrique Facture. Bonne journée !', created_at: new Date(t0 + 3 * 3600e3).toISOString() }];
}
async function supLoad() {
  const Q = supState(); if (!LIVE) { supDemoSeed(); render(); return; }
  if (Q.busy) return; Q.busy = true;
  const { data, error } = await SB.from('support_tickets').select('id, ref, category, subject, status, created_at, last_message_at, booking_id').order('last_message_at', { ascending: false }).limit(30);
  Q.busy = false; Q.loaded = true; if (!error) Q.list = data || []; render();
}
async function supLoadMsgs(id) {
  const Q = supState(); if (!LIVE) return;
  const { data } = await SB.from('support_messages').select('from_staff, body, created_at').eq('ticket_id', id).order('created_at');
  Q.msgs[id] = data || []; render();
}
function supCard() {
  const Q = supState(); if (!Q.loaded) setTimeout(supLoad, 0);
  const rows = Q.list.map(t => { const st = SUP_ST[t.status] || [t.status, 'muted'];
    return `<button class="accrow" data-a="sup-open" data-id="${esc(t.id)}"><span class="grow"><b>${esc(t.subject)}</b><small>${esc(t.ref)} · ${fdt(Date.parse(t.last_message_at || t.created_at))}</small></span><span class="pill t-${st[1]}">${esc(st[0])}</span></button>`; }).join('');
  return `<section class="section"><div class="card stack"><div class="row"><h3 class="grow">Mes demandes d'assistance</h3><button class="btn pri" data-a="sup-new">Nouvelle demande</button></div>
  ${Q.loaded ? (rows || '<p class="sm muted">Aucune demande pour le moment.</p>') : '<p class="sm muted">Chargement…</p>'}
  <p class="xs muted">Réponse sous 24 h ouvrées, ici et dans vos notifications. Vous pouvez aussi écrire à contact@zyntell.fr. En cas de danger, appelez le 112.</p></div></section>`;
}
EXTRA_SHEETS.supnew = (s, h) => {
  const refs = (S.bookings || []).slice().sort((a, b) => b.start - a.start).slice(0, 15).map(b => b.ref).filter(Boolean);
  return h('Nouvelle demande d\'assistance', 'L\'équipe Side by Side vous répond sous 24 h ouvrées') + `<form class="stack" data-form="sup-new">
  <div class="field"><label for="sup-cat">Sujet</label><select id="sup-cat" name="category">${SUP_CAT.map(([k, l]) => `<option value="${k}">${esc(l)}</option>`).join('')}</select></div>
  <div class="field"><label for="sup-ref">Réservation concernée (facultatif)</label><select id="sup-ref" name="ref"><option value="">Aucune</option>${refs.map(r => `<option>${esc(r)}</option>`).join('')}</select></div>
  <div class="field"><label for="sup-sub">Titre</label><input id="sup-sub" name="subject" maxlength="120" placeholder="Ex. : Remboursement non reçu"></div>
  <div class="field"><label for="sup-body">Votre message</label><textarea id="sup-body" name="body" rows="5" maxlength="3000" placeholder="Décrivez votre demande. N'indiquez jamais de mot de passe ni de numéro de carte."></textarea></div>
  <p class="note t-bad sm" id="sup-err" hidden></p><button class="btn pri full">Envoyer ma demande</button></form>`;
};
EXTRA_SHEETS.supthread = (s, h) => {
  const Q = supState(), t = Q.list.find(x => x.id === s.id); if (!t) return h('Demande', '') + '<p class="muted">Demande introuvable.</p>';
  const m = Q.msgs[t.id], st = SUP_ST[t.status] || [t.status, 'muted'];
  if (!m && LIVE) setTimeout(() => supLoadMsgs(t.id), 0);
  return h(esc(t.subject), `${esc(t.ref)} · ${esc((SUP_CAT.find(c => c[0] === t.category) || [0, ''])[1])}`) + `<div class="row"><span class="pill t-${st[1]}">${esc(st[0])}</span></div>
  <div class="stack">${(m || []).map(x => `<div class="card sm ${x.from_staff ? '' : 'mine'}"><b>${x.from_staff ? 'Assistance Side by Side' : 'Vous'}</b> <span class="xs muted">${fdt(Date.parse(x.created_at))}</span><p class="ugc" style="margin:.3em 0 0;white-space:pre-wrap">${esc(x.body)}</p></div>`).join('') || '<p class="muted sm">Chargement…</p>'}</div>
  ${t.status === 'fermee' ? '<p class="xs muted">Cette demande est fermée. Ouvrez une nouvelle demande si besoin.</p>' : `<form class="stack" data-form="sup-reply" data-id="${esc(t.id)}"><div class="field"><label for="sup-rep">Répondre</label><textarea id="sup-rep" name="body" rows="3" maxlength="3000"></textarea></div><p class="note t-bad sm" id="sup-err" hidden></p><div class="pbar"><button class="btn pri">Envoyer</button>${t.status !== 'resolue' ? `<button class="btn ghost" type="button" data-a="sup-resolve" data-id="${esc(t.id)}">Ma demande est résolue</button>` : ''}</div></form>`}`;
};
function supErr(m) { const p = document.getElementById('sup-err'); if (p) { p.textContent = tr(m); p.hidden = false; } else toast(m, true); }

function v30Click(a, el, id, v, b) {
  switch (a) {
    case 'role': if (v === 'admin') return true; return false;   // plus aucun accès administrateur dans l'application
    case 'sup-new': open('supnew'); return true;
    case 'sup-open': open('supthread', { id }); return true;
    case 'sup-resolve': {
      const Q = supState();
      if (!LIVE) { const t = Q.list.find(x => x.id === id); if (t) t.status = 'resolue'; toast('Demande marquée comme résolue.'); render(); return true; }
      SB.rpc('support_resolve', { p_ticket: id }).then(({ error }) => { if (error) return toast(error.message, true); toast('Demande marquée comme résolue.'); supLoad(); });
      return true;
    }
    default: return false;
  }
}
function v30Submit(k, f, d) {
  if (k === 'sup-new') {
    const subject = (d.subject || '').trim(), body = (d.body || '').trim();
    if (subject.length < 3) return (supErr('Indiquez un titre (3 caractères minimum).'), 'stop');
    if (body.length < 10) return (supErr('Décrivez votre demande (10 caractères minimum).'), 'stop');
    const Q = supState();
    if (!LIVE) { const id = 'sd' + (Q.list.length + 2), ref = 'AS-' + (1001 + Q.list.length);
      Q.list.unshift({ id, ref, category: d.category, subject, status: 'ouverte', created_at: new Date().toISOString(), last_message_at: new Date().toISOString() });
      Q.msgs[id] = [{ from_staff: false, body, created_at: new Date().toISOString() }];
      S.sheet = null; toast(`Demande ${ref} envoyée. L'équipe vous répondra ici.`); render(); return true; }
    SB.rpc('support_open', { p_category: d.category, p_subject: subject, p_body: body, p_booking_ref: d.ref || null }).then(({ data, error }) => {
      if (error) return supErr(error.message);
      S.sheet = null; toast(`Demande ${data && data.ref || ''} envoyée. L'équipe vous répondra ici.`); supLoad(); });
    return true;
  }
  if (k === 'sup-reply') {
    const body = (d.body || '').trim(), id = f.dataset.id; if (body.length < 2) return (supErr('Message vide.'), 'stop');
    const Q = supState();
    if (!LIVE) { (Q.msgs[id] = Q.msgs[id] || []).push({ from_staff: false, body, created_at: new Date().toISOString() }); const t = Q.list.find(x => x.id === id); if (t) t.status = 'ouverte'; render(); return true; }
    SB.rpc('support_reply', { p_ticket: id, p_body: body }).then(({ error }) => { if (error) return supErr(error.message); toast('Message envoyé.'); supLoadMsgs(id); supLoad(); });
    return true;
  }
  return false;
}

/* ---------- Photos validées des accompagnateurs (liens temporaires) ---------- */
async function livePhotos() {
  if (!LIVE || !SB) return;
  const list = (S.companions || []).filter(c => c._photo && !PHOTOS[c.id]);
  if (!list.length) return;
  const { data } = await SB.storage.from('photos').createSignedUrls(list.map(c => c._photo), 3600);
  (data || []).forEach((x, i) => { if (x && x.signedUrl) PHOTOS[list[i].id] = x.signedUrl; });
  render();
}

function v30Init() {
  if (window.__v30) return; window.__v30 = 1;
  const add = { fr: ['Mes demandes d\'assistance', 'Nouvelle demande', 'Nouvelle demande d\'assistance', 'Envoyer ma demande', 'Ma demande est résolue', 'Réponse reçue', 'Résolue', 'Fermée', 'Envoyée', 'En cours de traitement'] };
  void add;
  // L'écran « Aide et assistance » affiche les demandes de l'utilisateur
  const _as = accScreen; accScreen = (k, role, sec) => { const h = _as(k, role, sec); return k === 'aide' ? supCard() + h : h; };
  // Mobile : un compte administrateur n'ouvre jamais l'administration
  if (!ADMIN_WEB) { mfa = () => adminRefusedPage(); if (typeof liveMfaHtml === 'function') liveMfaHtml = () => adminRefusedPage(); if (typeof liveMfaInit === 'function') liveMfaInit = () => {}; }
  // Photos validées dans l'annuaire (mode connecté)
  if (LIVE && typeof adaptCompanion === 'function') {
    const _ac = adaptCompanion; adaptCompanion = r => { const c = _ac(r); if (r && r.photo_path) c._photo = r.photo_path; return c; };
    const _ll = liveLoad; liveLoad = async (...x) => { const r = await _ll(...x); livePhotos(); return r; };
  }
}

/* =====================================================================
   V3.0 — ESPACE DE GESTION (sidebyside.zyntell.fr/gestion)
   Construit à partir de l'administration existante (même design, mêmes composants),
   branché sur les données réelles de Supabase. Aucune donnée fictive.
   Sécurité : mot de passe + TOTP via la fonction admin-auth, déconnexion après 15 min
   d'inactivité, nouvelle saisie du code avant les opérations sensibles (réponse 428).
   ===================================================================== */
const G = { step: 'login', err: '', busy: false, info: '' };      // état de connexion
const AD = {};                                                     // données chargées par écran
const IDLE_MS = 15 * 60_000, WARN_MS = 14 * 60_000, PING_MS = 60_000;
let admLastAct = Date.now(), admLastPing = 0, admWarned = false, admStepWait = null;
ADMIN_TABS = ['dashboard', 'users', 'verif', 'bookings', 'finances', 'disputes', 'support', 'audit', 'settings'];

const ADM_FN = fn => SBS_CONFIG.url.replace(/\/$/, '') + '/functions/v1/' + fn;
async function admToken() { const { data } = await SB.auth.getSession(); return data && data.session; }
async function admAuth(body, token) {
  const r = await fetch(ADM_FN('admin-auth'), { method: 'POST', headers: { 'Content-Type': 'application/json', apikey: SBS_CONFIG.key, Authorization: 'Bearer ' + (token || SBS_CONFIG.key) }, body: JSON.stringify(body) });
  let j = {}; try { j = await r.json(); } catch (e) {}
  return { status: r.status, ...j };
}
// Appel d'une fonction serveur avec la session de gestion : 428 = nouvelle saisie du code, 401 = session terminée
async function admCall(fn, body, retried) {
  const s = await admToken(); if (!s) { admExpired('Session expirée : reconnectez-vous.'); throw new Error('Session expirée'); }
  let r; try { r = await fetch(ADM_FN(fn), { method: 'POST', headers: { 'Content-Type': 'application/json', apikey: SBS_CONFIG.key, Authorization: 'Bearer ' + s.access_token }, body: JSON.stringify(body || {}) }); }
  catch (e) { throw new Error('Le serveur ne répond pas. Réessayez.'); }
  let j = {}; try { j = await r.json(); } catch (e) {}
  if (r.status === 428 && !retried) { await admStepUp(); return admCall(fn, body, true); }
  if (r.status === 401) { admExpired(j.error || 'Session expirée : reconnectez-vous.'); throw new Error(j.error || 'Session expirée'); }
  if (!r.ok || j.error) throw new Error(j.error || 'Opération impossible pour le moment.');
  admLastPing = Date.now();
  return j;
}
const admApi = (action, body) => admCall('admin-action', { action, ...(body || {}) });

/* ---------- Nouvelle authentification (opérations sensibles) ---------- */
function admStepUp() {
  return new Promise((ok, ko) => { admStepWait = { ok, ko }; open('stepup'); render(); setTimeout(() => { const i = document.getElementById('su-code'); i && i.focus(); }, 50); });
}
EXTRA_SHEETS.stepup = (s, h) => h('Confirmation de sécurité', 'Opération sensible : saisissez un nouveau code') + `<form class="stack" data-form="adm-stepup">
  <p class="sm muted">Ouvrez votre application d'authentification (Google Authenticator…) et saisissez le code à 6 chiffres affiché pour « Side by Side ».</p>
  <div class="field"><label for="su-code">Code à 6 chiffres</label><input id="su-code" name="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="••••••"></div>
  <p class="note t-bad sm" id="su-err" hidden></p><button class="btn pri full">Confirmer</button></form>`;

/* ---------- Déconnexion : volontaire, inactivité, session expirée ---------- */
async function admLogout(reason, msg) {
  const s = await admToken().catch(() => null);
  if (s) await admAuth({ action: 'logout', reason }, s.access_token).catch(() => {});
  try { await SB.auth.signOut({ scope: 'local' }); } catch (e) {}
  for (const k in AD) delete AD[k];
  ME = null; S.role = null; S.adminOk = false; S.sheet = null; G.step = 'login'; G.err = ''; G.info = msg || '';
  if (admStepWait) { admStepWait.ko(new Error('annulé')); admStepWait = null; }
  render();
}
function admExpired(msg) { if (S.role === 'admin') admLogout('expiree', msg); }
function admActivity() {
  admLastAct = Date.now(); admWarned = false;
  if (S.role === 'admin' && S.adminOk && Date.now() - admLastPing > PING_MS) { admLastPing = Date.now(); admApi('ping').catch(() => {}); }
}
function admIdleWatch() {
  if (S.role !== 'admin' || !S.adminOk) return;
  const idle = Date.now() - admLastAct;
  if (idle > IDLE_MS) { admLogout('inactivite', 'Vous avez été déconnecté après 15 minutes d\'inactivité.'); return; }
  if (idle > WARN_MS && !admWarned) { admWarned = true; toast('Sans activité, vous serez déconnecté dans 1 minute.', true); render(); }
}

/* ---------- Écrans de connexion ---------- */
function admLoginPage() {
  const head = `<div class="login-logo">${typeof loginLogo === 'function' ? loginLogo() : ''}</div><h2 style="text-align:center;margin:.2em 0">Espace de gestion</h2><p class="xs muted" style="text-align:center">Accès réservé à l'équipe Side by Side · connexion chiffrée et journalisée</p>`;
  const err = G.err ? `<p class="note t-bad sm" role="alert">${esc(G.err)}</p>` : '', info = G.info ? `<p class="note t-warn sm">${esc(G.info)}</p>` : '';
  let body = '';
  if (G.step === 'login') body = `<form class="card stack" data-form="adm-login" autocomplete="on">${info}<div class="field"><label for="al-mail">Adresse e-mail professionnelle</label><input id="al-mail" name="email" type="email" autocomplete="username" required></div>
    <div class="field"><label for="al-pw">Mot de passe</label><input id="al-pw" name="password" type="password" autocomplete="current-password" required></div>${err}
    <button class="btn pri full" ${G.busy ? 'disabled' : ''}>${G.busy ? 'Vérification…' : 'Continuer'}</button>
    <p class="xs muted">Après 5 échecs, l'accès est bloqué 15 minutes et l'équipe est alertée. Mot de passe ou téléphone perdu : contactez le dirigeant.</p></form>`;
  else if (G.step === 'enroll') body = `<form class="card stack" data-form="adm-mfa"><h3>Activer la double authentification</h3><p class="sm muted">Première connexion : scannez ce QR code avec Google Authenticator (ou Microsoft Authenticator), puis saisissez le code affiché.</p>
    <div style="text-align:center"><img src="${G.qr}" alt="QR code de double authentification" style="width:200px;height:200px;background:#fff;padding:8px;border-radius:12px;display:inline-block"></div>
    <p class="xs muted">Ou saisissez la clé : <b class="sel num">${esc(G.secret || '')}</b></p>
    <div class="field"><label for="am-code">Code à 6 chiffres</label><input id="am-code" name="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="••••••"></div>${err}
    <button class="btn pri full" ${G.busy ? 'disabled' : ''}>Valider</button><button class="btn ghost full" type="button" data-a="adm-cancel">Annuler</button></form>`;
  else if (G.step === 'verify') body = `<form class="card stack" data-form="adm-mfa"><h3>Double authentification</h3><p class="sm muted">Saisissez le code à 6 chiffres de votre application d'authentification.</p>
    <div class="field"><label for="am-code">Code</label><input id="am-code" name="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="••••••" autofocus></div>${err}
    <button class="btn pri full" ${G.busy ? 'disabled' : ''}>Valider</button><button class="btn ghost full" type="button" data-a="adm-cancel">Annuler</button></form>`;
  else if (G.step === 'pw') body = `<form class="card stack" data-form="adm-pw"><h3>Choisissez votre mot de passe</h3><p class="sm muted">Votre mot de passe provisoire doit être remplacé avant d'accéder à l'espace de gestion.</p>
    <div class="field"><label for="ap-1">Nouveau mot de passe</label><input id="ap-1" name="pw" type="password" autocomplete="new-password"></div>
    <div class="field"><label for="ap-2">Confirmation</label><input id="ap-2" name="pw2" type="password" autocomplete="new-password"></div>
    <p class="xs muted">14 caractères minimum, avec minuscules, majuscules, chiffres et symboles. Les mots de passe ayant fuité sur Internet sont refusés.</p>${err}
    <button class="btn pri full" ${G.busy ? 'disabled' : ''}>Enregistrer</button></form>`;
  else body = `<div class="card"><p class="muted">Chargement…</p></div>`;
  return `<main class="login"><div class="wrap login-in" style="max-width:460px">${head}${body}</div></main>`;
}
async function admStartMfa() {
  const { data: f } = await SB.auth.mfa.listFactors();
  const ok = (f && f.totp || []).find(x => x.status === 'verified');
  if (ok) { G.step = 'verify'; G.factorId = ok.id; return; }
  for (const x of (f && f.all || []).filter(x => x.status !== 'verified')) await SB.auth.mfa.unenroll({ factorId: x.id }).catch(() => {});
  const { data: e, error } = await SB.auth.mfa.enroll({ factorType: 'totp', friendlyName: 'Side by Side Gestion ' + new Date().toISOString().slice(0, 10) });
  if (error) throw error;
  G.step = 'enroll'; G.factorId = e.id; G.qr = e.totp.qr_code; G.secret = e.totp.secret;
}
async function admEnter() {
  const me = await admApi('me');
  AD.me = me;
  const { data: p } = await SB.from('profiles').select('*').eq('id', me.id).single();
  ME = p || { id: me.id, first_name: me.first_name, role: 'admin' };
  S.users = { u1: { id: 'u1', name: ME.first_name || '', city: '', verified: 'ok', notif: [] } }; S.companions = []; S.bookings = []; S.msgs = {};
  ['notifs', 'flags', 'logs', 'disputes', 'reviews', 'ledger', 'support'].forEach(k => { if (Array.isArray(S[k])) S[k] = []; });   // aucune donnée de démonstration
  S.lang = 'fr';
  S.role = 'admin'; S.adminOk = true; S.tab = ADMIN_TABS.includes(S.tab) ? S.tab : 'dashboard'; G.step = 'ok'; G.err = ''; G.info = '';
  admLastAct = Date.now(); admLastPing = Date.now(); render();
}
// Reprise d'une session ouverte dans cet onglet (rechargement de la page)
async function admLoad() {
  const s = await admToken();
  if (!s) { S.role = null; G.step = G.step === 'ok' ? 'login' : G.step; render(); return; }
  try { await admEnter(); } catch (e) { try { await SB.auth.signOut({ scope: 'local' }); } catch (x) {} S.role = null; G.step = 'login'; render(); }
}

/* ---------- Petits composants ---------- */
const kpi = (l, v, cls = '') => `<div class="card kpi ${cls}"><span class="lbl">${l}</span><span class="num">${v}</span></div>`;
const loading = () => `<section class="section"><p class="muted">Chargement…</p></section>`;
const dts = s => s ? fdt(Date.parse(s)) : '—';
const dday = s => s ? fshort(Date.parse(s)) : '—';
const roleLbl = r => ({ client: 'Client', business: 'Entreprise', companion: 'Accompagnateur', admin: 'Équipe' }[r] || r);
const pillS = s => (typeof ST !== 'undefined' && ST[s]) ? pill(s) : `<span class="pill t-muted">${esc(s)}</span>`;
const pager = (key, res) => { if (!res || res.total <= res.size) return ''; const p = res.page, last = Math.ceil(res.total / res.size) - 1;
  return `<div class="row" style="justify-content:flex-end;gap:8px"><span class="xs muted">${p * res.size + 1}–${Math.min(res.total, (p + 1) * res.size)} sur ${res.total}</span><button class="btn ghost" data-a="adm-page" data-v="${key}|${p - 1}" ${p <= 0 ? 'disabled' : ''}>Précédent</button><button class="btn ghost" data-a="adm-page" data-v="${key}|${p + 1}" ${p >= last ? 'disabled' : ''}>Suivant</button></div>`; };
function need(key, loader) { if (AD[key] === undefined) { AD[key] = null; loader().then(v => { AD[key] = v; render(); }).catch(e => { AD[key] = { _err: e.message }; render(); }); } return AD[key]; }
const errBox = d => d && d._err ? `<section class="section"><div class="note t-bad">${esc(d._err)}</div><button class="btn" data-a="adm-refresh">Réessayer</button></section>` : '';
function refreshAll(keys) { (keys || Object.keys(AD)).forEach(k => { if (k !== 'me') delete AD[k]; }); render(); }
const admDl = (name, text, type = 'text/csv') => { const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob(['﻿' + text], { type })); a.download = name; document.body.appendChild(a); a.click(); setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 500); };
const csvLine = arr => arr.map(x => `"${String(x ?? '').replace(/"/g, '""')}"`).join(';');

/* ---------- 1. Tableau de bord ---------- */
function vDash() {
  const days = AD.days ?? 30;
  const d = need('dash', () => admApi('dashboard', { days })), ov = need('ov', () => admApi('overview'));
  if (!d) return loading(); if (d._err) return errBox(d);
  const c = d.counts || {}, f = d.finance || {};
  const todo = [['identites_a_verifier', 'pièce(s) d\'identité à vérifier', 'verif'], ['profils_a_valider', 'profil(s) d\'accompagnateur à valider', 'verif'], ['dossiers_a_verifier', 'dossier(s) administratif(s) à vérifier', 'verif'],
    ['photos_a_verifier', 'photo(s) à vérifier', 'verif'], ['avis_a_moderer', 'avis à modérer', 'verif'], ['litiges_ouverts', 'litige(s) ouvert(s)', 'disputes'], ['missions_a_verifier', 'mission(s) à vérifier', 'bookings'], ['assistance_ouverte', 'demande(s) d\'assistance à traiter', 'support']]
    .filter(([k]) => Number(c[k]) > 0).map(([k, l, t]) => `<div class="card row"><div class="grow"><b>${c[k]} ${l}</b></div><button class="btn" data-a="tab" data-v="${t}">Traiter</button></div>`).join('');
  const notes = (d.notifications || []), unread = notes.filter(n => !n.read_at).length;
  const alerts = ov && !ov._err ? ov.alerts || [] : [];
  return `<section class="section"><div class="row"><h2 class="grow">Tableau de bord</h2><div class="field" style="width:auto"><label for="adm-days" class="sr">Période</label><select id="adm-days" data-adm-days>${[[0, 'Depuis le début'], [7, '7 derniers jours'], [30, '30 derniers jours'], [90, '90 derniers jours'], [365, '12 derniers mois']].map(([v, l]) => `<option value="${v}" ${days === v ? 'selected' : ''}>${l}</option>`).join('')}</select></div><button class="btn ghost" data-a="adm-refresh">Actualiser</button></div>
  ${alerts.length ? alerts.slice(0, 3).map(x => `<div class="note t-bad row" role="alert"><div class="grow"><b>${esc(x.kind)}</b> · ${x.bookings ? esc(x.bookings.ref) : 'Hors réservation'} · ${dts(x.created_at)}</div>${x.latitude != null ? `<a class="btn ghost" href="https://www.openstreetmap.org/?mlat=${+x.latitude}&mlon=${+x.longitude}#map=17/${+x.latitude}/${+x.longitude}" target="_blank" rel="noopener">Carte</a>` : ''}<button class="btn" data-a="adm-user" data-id="${esc(x.user_id)}">Voir le membre</button></div>`).join('') : ''}
  <div class="kpis">${kpi('Clients', c.clients ?? 0)}${kpi('Accompagnateurs', c.accompagnateurs ?? 0)}${kpi('Identités vérifiées', c.verifies ?? 0)}${kpi('Réservations', f.reservations ?? 0)}${kpi('Litiges ouverts', c.litiges_ouverts ?? 0)}${kpi('Alertes (7 j)', c.alertes_7j ?? 0)}</div>
  <div class="card stack"><span class="lbl">Finances (données réelles)</span><div class="tbl" style="border:0"><table class="t" style="min-width:0"><tr><th>Indicateur</th><th>Nature</th><th style="text-align:right">Montant</th></tr>
  <tr><td>Montants encaissés</td><td><span class="pill t-ok">Réel</span></td><td class="num" style="text-align:right">${eur(+f.encaisse)}</td></tr>
  <tr><td>Chiffre d'affaires ZYNTELL HT (frais de service + commissions)</td><td><span class="pill t-ok">Acquis</span></td><td class="num" style="text-align:right">${eur(+f.chiffre_affaires_ht)}</td></tr>
  <tr><td>dont commissions ZYNTELL sur les prestations terminées</td><td><span class="pill t-ok">Acquis</span></td><td class="num" style="text-align:right">${eur(+f.commissions)}</td></tr>
  <tr><td>Versements aux accompagnateurs</td><td><span class="pill t-ok">Réel</span></td><td class="num" style="text-align:right">${eur(+f.verse)}</td></tr>
  <tr><td>Remboursements</td><td><span class="pill t-bad">Remboursé</span></td><td class="num" style="text-align:right">${eur(+f.rembourse)}</td></tr>
  <tr><td>Fonds détenus (prestations payées non terminées)</td><td><span class="pill t-warn">En attente</span></td><td class="num" style="text-align:right">${eur(+f.fonds_detenus)}</td></tr></table></div></div>
  ${barChart((f.par_mois || []).slice(-6).map(m => ({ label: new Intl.DateTimeFormat(LOC(), { month: 'short' }).format(new Date(m.mois + '-01T12:00:00')), v: +m.ca_ht })), 'Chiffre d\'affaires ZYNTELL HT par mois')}
  <div class="stack">${todo || '<div class="empty">Rien à traiter pour le moment.</div>'}</div></section>
  <section class="section"><div class="row"><h3 class="grow">Notifications de l'équipe${unread ? ` <span class="pill t-warn">${unread} non lue(s)</span>` : ''}</h3>${unread ? '<button class="btn ghost" data-a="adm-notif-read">Tout marquer comme lu</button>' : ''}</div>
  ${notes.length ? notes.map(n => `<div class="card row ${n.read_at ? '' : 'unread'}"><span class="xs muted">${dts(n.created_at)}</span><span class="grow sm">${esc(n.body)}</span></div>`).join('') : '<div class="empty">Aucune notification.</div>'}</section>
  <section class="section"><h3>Répartition géographique</h3>${(f.par_ville || []).length ? `<div class="tbl"><table class="t"><tr><th>Ville</th><th>Pays</th><th>Réservations</th><th>Volume</th></tr>${f.par_ville.map(v => `<tr><td>${esc(v.ville)}</td><td>${esc(v.pays)}</td><td class="num">${v.reservations}</td><td class="num">${eur(+v.volume)}</td></tr>`).join('')}</table></div>` : '<div class="empty">Aucune réservation sur la période.</div>'}
  <div class="acts"><button class="btn" data-a="dac7">Fiscalité et déclarations DAC7</button><button class="btn" data-a="ins-admin">Gestion des assurances</button></div></section>`;
}

/* ---------- 2. Membres ---------- */
function vUsers() {
  const F = AD.uf || (AD.uf = { q: '', role: '', status: '', page: 0 });
  const d = need('users', () => admApi('users', F));
  return `<section class="section"><h2>Comptes</h2><form class="row" data-form="adm-users" style="flex-wrap:wrap;gap:8px"><input name="q" value="${esc(F.q)}" placeholder="Nom, e-mail, téléphone, ville" aria-label="Rechercher un membre" style="flex:1;min-width:200px">
  <select name="role" aria-label="Type de compte"><option value="">Tous</option><option value="client" ${F.role === 'client' ? 'selected' : ''}>Clients</option><option value="companion" ${F.role === 'companion' ? 'selected' : ''}>Accompagnateurs</option></select>
  <select name="status" aria-label="Statut"><option value="">Tous les statuts</option><option value="non_verifie" ${F.status === 'non_verifie' ? 'selected' : ''}>Identité non vérifiée</option><option value="a_valider" ${F.status === 'a_valider' ? 'selected' : ''}>Profil à valider</option><option value="suspendu" ${F.status === 'suspendu' ? 'selected' : ''}>Suspendus</option></select>
  <button class="btn pri">Rechercher</button></form>
  ${!d ? '<p class="muted">Chargement…</p>' : d._err ? errBox(d) : d.users.length ? `<div class="tbl"><table class="t"><tr><th>Nom</th><th>E-mail</th><th>Type</th><th>Ville</th><th>Vérification</th><th>Réservations</th><th></th></tr>
  ${d.users.map(u => `<tr><td><b>${esc((u.first_name || '') + ' ' + (u.last_name || ''))}</b></td><td class="xs">${esc(u.email || '')}</td><td>${roleLbl(u.role)}${u.tier === 'Prestige' ? ' <span class="chip gold">Prestige</span>' : ''}</td><td>${esc(u.city || '')}</td>
  <td>${u.identity_verified ? '<span class="pill t-ok">Identité vérifiée</span>' : '<span class="pill t-warn">Identité à vérifier</span>'}${u.role === 'companion' ? (u.verified ? ' <span class="pill t-ok">Profil validé</span>' : ' <span class="pill t-warn">Profil à valider</span>') : ''}${u.suspended ? ' <span class="pill t-bad">Suspendu</span>' : ''}</td>
  <td class="num">${u.bookings}</td><td><button class="btn" data-a="adm-user" data-id="${esc(u.id)}">Fiche</button></td></tr>`).join('')}</table></div>${pager('users', d)}` : '<div class="empty">Aucun compte ne correspond.</div>'}
  <p class="xs muted">Les documents d'identité ne sont jamais affichés publiquement ; chaque consultation de fiche est journalisée.</p></section>`;
}
EXTRA_SHEETS.admuser = (s, h) => {
  const d = AD['user:' + s.id];
  if (d === undefined) { AD['user:' + s.id] = null; admApi('user_detail', { user_id: s.id }).then(v => { AD['user:' + s.id] = v; render(); }).catch(e => { AD['user:' + s.id] = { _err: e.message }; render(); }); }
  if (!d) return h('Fiche membre', '') + '<p class="muted">Chargement…</p>';
  if (d._err) return h('Fiche membre', '') + `<p class="note t-bad">${esc(d._err)}</p>`;
  const p = d.profile, c = d.companion;
  return h(esc(`${p.first_name || ''} ${p.last_name || ''}`), `${roleLbl(p.role)} · inscrit le ${dday(p.created_at)}`) + `<div class="stack">
  <div class="card stack sm"><div><b>E-mail</b> : ${esc(p.email || '')}</div><div><b>Téléphone</b> : ${esc(p.phone || '—')}</div><div><b>Ville</b> : ${esc([p.city, p.country].filter(Boolean).join(', ') || '—')}</div><div><b>Date de naissance</b> : ${esc(p.birth_date || '—')}</div>
  <div>${p.identity_verified ? '<span class="pill t-ok">Identité vérifiée</span>' : '<span class="pill t-warn">Identité non vérifiée</span>'} ${p.suspended ? '<span class="pill t-bad">Compte suspendu</span>' : '<span class="pill t-ok">Compte actif</span>'} ${p.privilege_since ? '<span class="pill t-gold">Privilège</span>' : ''}</div></div>
  ${c ? `<div class="card stack sm"><b>Accompagnateur</b><div>${c.verified ? '<span class="pill t-ok">Profil validé</span>' : '<span class="pill t-warn">Profil à valider</span>'} <span class="chip ${c.tier === 'Prestige' ? 'gold' : ''}">${esc(c.tier || 'Standard')}</span> · ${eur(+c.hourly_rate)}/h</div>
    <div>Dossier administratif : <b>${esc({ en_cours: 'à vérifier', valide: 'validé', refuse: 'refusé' }[c.admin_status] || 'non transmis')}</b>${c.legal_status ? ` · statut ${esc(c.legal_status)}` : ''}${c.admin_doc_url ? ` · <a href="${esc(c.admin_doc_url)}" target="_blank" rel="noopener">voir le justificatif (10 min)</a>` : ''}</div>
    <div>Assurance RC : ${(d.insurance || []).length ? d.insurance.map(i => `${esc(i.insurer)} n° ${esc(i.policy_number)} · ${esc(i.status)} · jusqu'au ${dday(i.ends_on)}`).join('<br>') : '<span class="pill t-bad">aucune attestation</span>'}</div>
    ${c.bio ? `<p class="ugc">${esc(c.bio)}</p>` : ''}
    <div class="pbar">${!c.verified ? `<button class="btn pri" data-a="adm-comp" data-id="${esc(p.id)}" data-v="Standard" ${p.identity_verified ? '' : 'disabled'}>Valider (Standard)</button><button class="btn" data-a="adm-comp" data-id="${esc(p.id)}" data-v="Prestige" ${p.identity_verified ? '' : 'disabled'}>Valider (Prestige)</button>` : ''}
    ${c.admin_status === 'en_cours' ? `<button class="btn pri" data-a="adm-dossier" data-id="${esc(p.id)}" data-v="1">Valider le dossier administratif</button>` : ''}</div></div>` : ''}
  ${(d.photos || []).length ? `<div class="card stack sm"><b>Photos</b><div class="row" style="flex-wrap:wrap;gap:8px">${d.photos.map(x => `<figure style="margin:0;width:96px"><img src="${esc(x.url || '')}" alt="" style="width:96px;height:96px;object-fit:cover;border-radius:10px"><figcaption class="xs muted">${esc({ pending: 'à vérifier', ok: 'validée', refused: 'refusée', draft: 'brouillon' }[x.status] || x.status)}</figcaption></figure>`).join('')}</div></div>` : ''}
  <div class="card stack sm"><b>Dernières réservations</b>${(d.bookings || []).length ? `<div class="tbl"><table class="t"><tr><th>Réf.</th><th>Date</th><th>Statut</th><th>Total</th></tr>${d.bookings.map(b => `<tr><td><button class="linkbtn" data-a="adm-resa" data-id="${esc(b.id)}">${esc(b.ref)}</button></td><td>${dts(b.starts_at)}</td><td>${pillS(b.status)}</td><td class="num">${eur(+b.amount_total)}</td></tr>`).join('')}</table></div>` : '<p class="muted">Aucune.</p>'}</div>
  <div class="card stack sm"><b>Demandes d'assistance</b>${(d.tickets || []).length ? d.tickets.map(t => `<button class="accrow" data-a="adm-ticket" data-id="${esc(t.id)}"><span class="grow">${esc(t.ref)} · ${esc(t.subject)}</span><span class="xs muted">${esc(t.status)}</span></button>`).join('') : '<p class="muted">Aucune.</p>'}</div>
  <div class="card stack sm"><b>Historique des décisions</b>${(d.logs || []).length ? d.logs.map(l => `<div class="xs"><span class="muted">${dts(l.created_at)}</span> · ${esc(l.actor)} · ${esc(l.action)}</div>`).join('') : '<p class="muted">Aucune décision.</p>'}</div>
  <form class="card stack" data-form="adm-suspend" data-id="${esc(p.id)}" data-v="${p.suspended ? '0' : '1'}"><b>${p.suspended ? 'Réactiver le compte' : 'Suspendre le compte'}</b><div class="field"><label for="su-r">Motif (obligatoire, communiqué dans le journal)</label><input id="su-r" name="reason" maxlength="300"></div>
  <p class="xs muted">Opération sensible : un nouveau code de double authentification sera demandé.</p><button class="btn ${p.suspended ? 'pri' : 'bad'}">${p.suspended ? 'Réactiver' : 'Suspendre'}</button></form></div>`;
};

/* ---------- 3. Vérifications (identités, profils, dossiers, photos, avis) ---------- */
function vVerif() {
  const ov = need('ov', () => admApi('overview')), ph = need('photos', () => admApi('photos')), rv = need('reviews', () => admApi('reviews', { status: 'moderation' }));
  if (!ov) return loading(); if (ov._err) return errBox(ov);
  const dossiers = (ov.companions || []).filter(c => c.admin_status === 'en_cours'), toValidate = (ov.companions || []).filter(c => !c.verified);
  return `<section class="section"><div class="row"><h2 class="grow">Vérifications</h2><button class="btn ghost" data-a="adm-refresh">Actualiser</button></div>
  <h3>Pièces d'identité à vérifier</h3>${ov.identity.length ? ov.identity.map(x => `<form class="card stack" data-form="adm-id" data-id="${esc(x.id)}"><div class="row"><b class="grow">${esc((x.profiles?.first_name || '') + ' ' + (x.profiles?.last_name || ''))}</b><span class="pill t-warn">${roleLbl(x.profiles?.role)}</span></div>
    <span class="xs muted">Né(e) le ${esc(x.profiles?.birth_date || '—')} · déposé le ${dts(x.created_at)}</span>
    <div class="row">${x.doc_url ? `<a class="btn ghost" href="${esc(x.doc_url)}" target="_blank" rel="noopener">Voir la pièce</a>` : ''}${x.selfie_url ? `<a class="btn ghost" href="${esc(x.selfie_url)}" target="_blank" rel="noopener">Voir le selfie</a>` : ''}</div>
    <p class="xs muted">Liens valables 10 minutes. Vérifiez la majorité, la correspondance du visage et la validité du document.</p>
    <div class="field"><label>Motif en cas de refus</label><input name="reason" maxlength="300" placeholder="Ex. : document expiré, photo illisible"></div>
    <div class="pbar"><button class="btn pri" name="ok" value="1">Valider l'identité</button><button class="btn bad" name="ok" value="0">Refuser</button></div></form>`).join('') : '<div class="empty">Aucune pièce en attente.</div>'}
  <h3>Accompagnateurs à valider</h3>${toValidate.length ? toValidate.map(c => `<div class="card stack"><div class="row"><b class="grow">${esc((c.profiles?.first_name || '') + ' ' + (c.profiles?.last_name || ''))}</b>${c.profiles?.identity_verified ? '<span class="pill t-ok">Identité vérifiée</span>' : '<span class="pill t-warn">Identité non vérifiée</span>'}</div>
    <span class="xs muted">${esc(c.profiles?.city || '')} · ${eur(+c.hourly_rate)}/h · ${esc((c.categories || []).join(', ') || 'aucune activité')}</span>${c.bio ? `<p class="sm ugc">${esc(c.bio)}</p>` : ''}
    <div class="pbar"><button class="btn pri" data-a="adm-comp" data-id="${esc(c.id)}" data-v="Standard" ${c.profiles?.identity_verified ? '' : 'disabled'}>Valider (Standard)</button><button class="btn" data-a="adm-comp" data-id="${esc(c.id)}" data-v="Prestige" ${c.profiles?.identity_verified ? '' : 'disabled'}>Valider (Prestige)</button><button class="btn ghost" data-a="adm-user" data-id="${esc(c.id)}">Fiche</button></div></div>`).join('') : '<div class="empty">Aucun profil en attente.</div>'}
  <h3>Dossiers administratifs (statut, SIRET, justificatif)</h3>${dossiers.length ? dossiers.map(c => `<form class="card stack" data-form="adm-dossier" data-id="${esc(c.id)}"><div class="row"><b class="grow">${esc((c.profiles?.first_name || '') + ' ' + (c.profiles?.last_name || ''))}</b><span class="pill t-warn">À vérifier</span></div>
    <span class="xs muted">Statut : ${esc(c.legal_status || '—')}${c.tax_id ? ` · n° ${esc(c.tax_id)}` : ''}</span>${c.admin_doc_url ? `<a class="btn ghost" href="${esc(c.admin_doc_url)}" target="_blank" rel="noopener">Voir le justificatif (10 min)</a>` : '<span class="xs muted">Aucun justificatif joint.</span>'}
    <div class="field"><label>Motif en cas de refus</label><input name="reason" maxlength="300"></div><div class="pbar"><button class="btn pri" name="ok" value="1">Valider le dossier</button><button class="btn bad" name="ok" value="0">Refuser</button></div></form>`).join('') : '<div class="empty">Aucun dossier en attente.</div>'}
  <h3>Photos à vérifier</h3>${!ph ? '<p class="muted">Chargement…</p>' : ph._err ? errBox(ph) : ph.photos.length ? ph.photos.map(x => `<form class="card stack" data-form="adm-photo" data-id="${esc(x.id)}"><div class="row"><b class="grow">${esc((x.companions?.profiles?.first_name || '') + ' ' + (x.companions?.profiles?.last_name || ''))}</b><span class="pill t-warn">${x.is_reference ? 'Photo de référence' : 'Nouvelle photo'}</span>${x.ai_suspect ? '<span class="pill t-bad">Image IA suspectée</span>' : ''}</div>
    <div class="ivcmp"><div class="gtile">${x.current_url ? `<img src="${esc(x.current_url)}" alt="Photo actuelle" style="width:100%;aspect-ratio:1;object-fit:cover">` : '<span class="muted sm">Aucune photo validée</span>'}<i>Photo actuelle</i></div><div class="gtile"><img src="${esc(x.url || '')}" alt="Nouvelle photo" style="width:100%;aspect-ratio:1;object-fit:cover"><i>Nouvelle photo</i></div></div>
    <div class="field"><label>Motif en cas de refus</label><input name="reason" maxlength="200" placeholder="Ex. : photo retouchée, visage non visible"></div>
    <div class="pbar"><button class="btn pri" name="ok" value="1">Photo authentique, valider</button><button class="btn bad" name="ok" value="0">Refuser</button></div></form>`).join('') : '<div class="empty">Aucune photo en attente.</div>'}
  <p class="xs muted">Chaque photo est vérifiée par une personne de l'équipe avant d'être visible ; une décision peut être contestée.</p>
  <h3>Avis à modérer</h3>${!rv ? '<p class="muted">Chargement…</p>' : rv._err ? errBox(rv) : rv.reviews.length ? rv.reviews.map(r => `<div class="card row"><div class="grow"><span class="stars">${'★'.repeat(r.stars)}</span> <span class="sm ugc">${esc(r.body || '')}</span><div class="xs muted">${esc(r.author)} → ${esc(r.target)} · ${esc(r.bookings?.ref || '')}</div></div><button class="btn pri" data-a="adm-rev" data-id="${esc(r.id)}" data-v="1">Publier</button><button class="btn" data-a="adm-rev" data-id="${esc(r.id)}" data-v="0">Masquer</button></div>`).join('') : '<div class="empty">Aucun avis en attente.</div>'}</section>`;
}

/* ---------- 4. Réservations ---------- */
const BST = ['en_attente', 'acceptee', 'confirmee', 'controle', 'verifie', 'en_cours', 'fin_declaree', 'double_attente', 'terminee', 'versement', 'cloturee', 'annulee', 'refusee', 'expiree', 'absence', 'contestee', 'a_verifier', 'incident'];
function vBookings() {
  const F = AD.bf || (AD.bf = { status: '', q: '', from: '', to: '', page: 0 });
  const d = need('bookings', () => admApi('bookings', F));
  return `<section class="section"><h2>Réservations</h2><form class="row" data-form="adm-bookings" style="flex-wrap:wrap;gap:8px"><input name="q" value="${esc(F.q)}" placeholder="Référence (CMP-…)" aria-label="Référence" style="width:160px">
  <select name="status" aria-label="Statut"><option value="">Tous les statuts</option>${BST.map(s => `<option value="${s}" ${F.status === s ? 'selected' : ''}>${esc((ST[s] || [s])[0])}</option>`).join('')}</select>
  <label class="xs">Du <input type="date" name="from" value="${esc(F.from)}"></label><label class="xs">au <input type="date" name="to" value="${esc(F.to)}"></label><button class="btn pri">Filtrer</button></form>
  ${!d ? '<p class="muted">Chargement…</p>' : d._err ? errBox(d) : d.bookings.length ? `<div class="tbl"><table class="t"><tr><th>Réf.</th><th>Date</th><th>Client</th><th>Accompagnateur</th><th>Statut</th><th>Total</th><th>Commission</th><th></th></tr>
  ${d.bookings.map(b => `<tr><td class="num">${esc(b.ref)}</td><td>${dts(b.starts_at)} · ${b.hours} h</td><td>${esc(b.client)}</td><td>${esc(b.companion)}</td><td>${pillS(b.status)}</td><td class="num">${eur(+b.amount_total)}</td><td class="num">${eur(+b.amount_commission)}</td><td><button class="btn" data-a="adm-resa" data-id="${esc(b.id)}">Détails</button></td></tr>`).join('')}</table></div>${pager('bookings', d)}` : '<div class="empty">Aucune réservation.</div>'}
  <div class="acts"><button class="btn" data-a="adm-csv-b">Export des réservations affichées (CSV)</button></div></section>`;
}
EXTRA_SHEETS.admresa = (s, h) => {
  const k = 'resa:' + s.id, d = AD[k];
  if (d === undefined) { AD[k] = null; admApi('booking_detail', { booking_id: s.id }).then(v => { AD[k] = v; render(); }).catch(e => { AD[k] = { _err: e.message }; render(); }); }
  if (!d) return h('Réservation', '') + '<p class="muted">Chargement…</p>';
  if (d._err) return h('Réservation', '') + `<p class="note t-bad">${esc(d._err)}</p>`;
  const b = d.booking, canCancel = ['en_attente', 'acceptee', 'confirmee', 'controle'].includes(b.status);
  const row = (l, v, cls = '') => `<tr><td>${l}</td><td class="num ${cls}" style="text-align:right">${v}</td></tr>`;
  return h(esc(b.ref), `${esc(b.client || '')} avec ${esc(b.companion || '')} · ${dts(b.starts_at)} · ${b.hours} h`) + `<div class="stack">
  <div class="row">${pillS(b.status)}<span class="xs muted">${esc(b.category)} · ${esc(b.place)}${b.language ? ' · ' + esc(b.language) : ''}</span></div>
  <div class="card"><div class="tbl" style="border:0"><table class="t" style="min-width:0">${row('Prestation', eur(+b.amount_service))}${row('Frais de service client HT', eur(+b.amount_client_fee))}${row('TVA sur les frais', eur(+b.amount_vat))}${+b.amount_annex ? row('Frais annexes', eur(+b.amount_annex)) : ''}${+b.gift_used ? row('Carte cadeau utilisée', '−' + eur(+b.gift_used)) : ''}
  ${row('<b>Total payé par le client</b>', '<b>' + eur(+b.amount_total) + '</b>')}${row('Commission ZYNTELL', eur(+b.amount_commission))}${row('Versement à l\'accompagnateur', eur(+b.amount_payout))}${+b.tip ? row('Pourboire', eur(+b.tip)) : ''}</table></div><p class="xs muted">${b.has_payment ? 'Paiement Stripe enregistré.' : 'Aucun paiement enregistré.'}</p></div>
  <div class="card stack sm"><b>Mouvements financiers</b>${d.ledger.length ? d.ledger.map(l => `<div class="row"><span class="grow">${esc(l.kind)}</span><span class="xs muted">${dts(l.created_at)}</span><span class="num">${eur(+l.amount)}</span></div>`).join('') : '<p class="muted">Aucun.</p>'}</div>
  ${d.disputes.length ? `<div class="card stack sm"><b>Litiges</b>${d.disputes.map(x => `<div>${esc(x.reason)} · ${esc(x.status)}${x.decision ? ' · ' + esc(x.decision) : ''}</div>`).join('')}</div>` : ''}
  ${d.invoices.length ? `<div class="card stack sm"><b>Factures</b>${d.invoices.map(x => `<div>${esc(x.number)} · ${esc(x.kind)} · ${eur(+x.total)}</div>`).join('')}</div>` : ''}
  <div class="card stack sm"><b>Historique</b>${d.events.map(e => `<div class="xs"><span class="muted">${dts(e.created_at)}</span> · ${esc(e.actor_name)} · ${esc(e.status ? (ST[e.status] || [e.status])[0] : '')}${e.note ? ' · ' + esc(e.note) : ''}</div>`).join('') || '<p class="muted">Aucun événement.</p>'}</div>
  <div class="pbar">${canCancel ? `<button class="btn bad" data-a="adm-cancel-resa" data-id="${esc(b.id)}">Annuler et rembourser le client</button>` : ''}${b.status === 'versement' ? `<button class="btn pri" data-a="adm-payout" data-id="${esc(b.id)}">Exécuter le versement</button>` : ''}<button class="btn ghost" data-a="adm-user" data-id="${esc(b.client_id)}">Fiche du client</button><button class="btn ghost" data-a="adm-user" data-id="${esc(b.companion_id)}">Fiche de l'accompagnateur</button></div>
  ${canCancel ? '<p class="xs muted">Une annulation par l\'équipe rembourse le client à 100 % et prévient les deux parties. Un nouveau code de double authentification est demandé.</p>' : ''}</div>`;
};

/* ---------- 5. Finances (chiffre d'affaires, commissions, remboursements, transactions) ---------- */
function vFinances() {
  const y = new Date().getFullYear(), F = AD.ff || (AD.ff = { from: `${y}-01-01`, to: new Date(Date.now() + 86400e3).toISOString().slice(0, 10) });
  const d = need('fin', () => admApi('finance', F)), TF = AD.tf || (AD.tf = { kind: '', page: 0 }), tx = need('tx', () => admApi('transactions', TF));
  const f = d && !d._err ? d.finance : null, R = d && !d._err ? d.rules : null;
  const line = (l, v, n, cls = 't-ok') => `<tr><td>${l}</td><td><span class="pill ${cls}">${n}</span></td><td class="num" style="text-align:right">${eur(+v)}</td></tr>`;
  return `<section class="section"><h2>Finances</h2><form class="row" data-form="adm-fin" style="flex-wrap:wrap;gap:8px"><label class="xs">Du <input type="date" name="from" value="${esc(F.from)}"></label><label class="xs">au <input type="date" name="to" value="${esc(F.to)}"></label><button class="btn pri">Calculer</button></form>
  ${!d ? '<p class="muted">Chargement…</p>' : d._err ? errBox(d) : `<div class="kpis">${kpi('Encaissé', eur(+f.encaisse))}${kpi('Chiffre d\'affaires HT', eur(+f.chiffre_affaires_ht))}${kpi('Commissions ZYNTELL', eur(+f.commissions))}${kpi('Remboursements', eur(+f.rembourse))}</div>
  <div class="card stack"><span class="lbl">Détail de la période</span><div class="tbl" style="border:0"><table class="t" style="min-width:0"><tr><th>Indicateur</th><th>Nature</th><th style="text-align:right">Montant</th></tr>
  ${line('Montants encaissés (paiements clients)', f.encaisse, 'Réel')}${line('Remboursements aux clients', f.rembourse, 'Remboursé', 't-bad')}${line('Versements aux accompagnateurs', f.verse, 'Réel')}${line('Pourboires (reversés en totalité)', f.pourboires, 'Réel')}
  ${line(`Volume des prestations terminées (${f.prestations_terminees})`, f.volume_prestations, 'Acquis')}${line('Frais de service clients HT', f.frais_service_ht, 'Acquis')}${line('Commissions ZYNTELL', f.commissions, 'Acquis')}${line('<b>Chiffre d\'affaires ZYNTELL HT</b>', f.chiffre_affaires_ht, 'Acquis')}${line('TVA collectée sur les frais de service', f.tva_collectee, 'À reverser', 't-warn')}
  ${line('Fonds détenus (prestations payées non terminées)', f.fonds_detenus, 'En attente', 't-warn')}</table></div>
  <p class="xs muted">Règles appliquées à chaque réservation : frais de service client ${R ? R.client_fee_pct : 15} % (+ TVA ${R ? R.vat_pct : 20} %), ${R ? R.privilege_fee_pct : 10} % pour les membres Privilège ; commission accompagnateur ${R ? R.companion_fee_pct : 20} %. Les montants sont ceux enregistrés lors de chaque réservation et dans le grand livre Stripe.</p></div>
  ${barChart((f.par_mois || []).map(m => ({ label: new Intl.DateTimeFormat(LOC(), { month: 'short' }).format(new Date(m.mois + '-01T12:00:00')), v: +m.ca_ht })), 'Chiffre d\'affaires ZYNTELL HT — 12 mois')}
  ${barChart((f.par_mois || []).map(m => ({ label: new Intl.DateTimeFormat(LOC(), { month: 'short' }).format(new Date(m.mois + '-01T12:00:00')), v: +m.rembourse })), 'Remboursements — 12 mois')}`}
  </section><section class="section"><div class="row"><h3 class="grow">Transactions</h3><select data-adm-txkind aria-label="Type de mouvement"><option value="">Tous les mouvements</option>${['Encaissement', 'Remboursement', 'Versement', 'Pourboire'].map(k => `<option ${TF.kind === k ? 'selected' : ''}>${k}</option>`).join('')}</select><button class="btn" data-a="adm-csv-tx">Export CSV</button></div>
  ${!tx ? '<p class="muted">Chargement…</p>' : tx._err ? errBox(tx) : tx.transactions.length ? `<div class="tbl"><table class="t"><tr><th>Date</th><th>Mouvement</th><th>Réservation</th><th>Référence Stripe</th><th style="text-align:right">Montant</th></tr>${tx.transactions.map(t => `<tr><td>${dts(t.created_at)}</td><td>${esc(t.kind)}</td><td class="num">${esc(t.bookings?.ref || '—')}</td><td class="xs num">${esc(t.stripe_object_id || '—')}</td><td class="num" style="text-align:right">${eur(+t.amount)}</td></tr>`).join('')}</table></div>${pager('tx', tx)}` : '<div class="empty">Aucun mouvement.</div>'}</section>`;
}

/* ---------- 6. Litiges ---------- */
function vDisputes() {
  const d = need('disp', () => admApi('disputes')), h = need('disph', () => admApi('disputes', { status: 'decide' }));
  if (!d) return loading(); if (d._err) return errBox(d);
  return `<section class="section"><h2>Centre de résolution</h2><p class="muted sm">Chaque décision est motivée, notifiée aux deux parties et journalisée. Un nouveau code de double authentification est demandé.</p>
  ${d.disputes.length ? d.disputes.map(x => `<form class="card stack" data-form="adm-decide" data-id="${esc(x.id)}"><div class="row"><b class="grow">${esc(x.bookings?.ref || '')} · ${esc(x.reason)}</b><span class="pill ${Date.parse(x.deadline) < Date.now() ? 't-bad' : 't-warn'}">Échéance ${dts(x.deadline)}</span></div><p class="sm ugc">${esc(x.description)}</p><span class="xs muted">Montant payé ${eur(+(x.bookings?.amount_total || 0))} · versement prévu ${eur(+(x.bookings?.amount_payout || 0))}</span>
    <div class="field"><label>Décision</label><select name="decision"><option value="payout">Prestation réalisée : verser l'accompagnateur</option><option value="refund">Rembourser le client</option></select></div><div class="field"><label>Remboursement du client (%)</label><input name="pct" type="number" min="0" max="100" value="100" inputmode="numeric"></div><div class="field"><label>Motif de la décision (obligatoire)</label><textarea name="note" rows="2"></textarea></div><button class="btn pri">Enregistrer la décision</button></form>`).join('') : '<div class="empty">Aucun litige ouvert.</div>'}</section>
  <section class="section"><h3>Historique des décisions</h3>${h && !h._err && h.disputes.length ? `<div class="tbl"><table class="t"><tr><th>Date</th><th>Réservation</th><th>Motif</th><th>Décision</th></tr>${h.disputes.map(x => `<tr><td>${dts(x.created_at)}</td><td class="num">${esc(x.bookings?.ref || '')}</td><td>${esc(x.reason)}</td><td>${esc(x.decision || '')}</td></tr>`).join('')}</table></div>` : '<div class="empty">Aucune décision pour le moment.</div>'}</section>`;
}

/* ---------- 7. Assistance ---------- */
const SUPS = { ouverte: ['Nouvelle', 'warn'], en_cours: ['En cours', 'info'], repondue: ['Répondue', 'ok'], resolue: ['Résolue', 'muted'], fermee: ['Fermée', 'muted'] };
const SUPC = { reservation: 'Réservation', paiement: 'Paiement', compte: 'Compte', securite: 'Sécurité', accompagnateur: 'Accompagnateur', technique: 'Technique', suppression: 'Suppression de compte', autre: 'Autre' };
function vSupport() {
  const F = AD.sf || (AD.sf = { status: '', q: '', page: 0 });
  const d = need('sup', () => admApi('support_list', F));
  return `<section class="section"><div class="row"><h2 class="grow">Assistance</h2><button class="btn ghost" data-a="adm-refresh">Actualiser</button></div>
  <div class="row" role="group" aria-label="Filtrer" style="flex-wrap:wrap;gap:6px">${[['', 'À traiter'], ['repondue', 'Répondues'], ['resolue', 'Résolues'], ['fermee', 'Fermées']].map(([v, l]) => `<button class="chip ${F.status === v ? 'on' : ''}" data-a="adm-supf" data-v="${v}" aria-pressed="${F.status === v}">${l}</button>`).join('')}</div>
  ${!d ? '<p class="muted">Chargement…</p>' : d._err ? errBox(d) : d.tickets.length ? `<div class="tbl"><table class="t"><tr><th>Réf.</th><th>Membre</th><th>Sujet</th><th>Catégorie</th><th>Dernier message</th><th>Statut</th><th></th></tr>${d.tickets.map(t => `<tr><td class="num">${esc(t.ref)}${t.priority === 'haute' ? ' <span class="pill t-bad">Prioritaire</span>' : ''}</td><td>${esc(t.user)}</td><td>${esc(t.subject)}</td><td>${esc(SUPC[t.category] || t.category)}</td><td>${dts(t.last_message_at)}</td><td><span class="pill t-${(SUPS[t.status] || ['', 'muted'])[1]}">${esc((SUPS[t.status] || [t.status])[0])}</span></td><td><button class="btn" data-a="adm-ticket" data-id="${esc(t.id)}">Ouvrir</button></td></tr>`).join('')}</table></div>${pager('sup', d)}` : '<div class="empty">Aucune demande.</div>'}
  <p class="xs muted">Les demandes arrivent depuis l'application (Compte → Aide et assistance). L'assistance par e-mail (contact@zyntell.fr) reste disponible.</p></section>`;
}
EXTRA_SHEETS.admticket = (s, h) => {
  const k = 'tk:' + s.id, d = AD[k];
  if (d === undefined) { AD[k] = null; admApi('support_detail', { ticket_id: s.id }).then(v => { AD[k] = v; render(); }).catch(e => { AD[k] = { _err: e.message }; render(); }); }
  if (!d) return h('Demande d\'assistance', '') + '<p class="muted">Chargement…</p>';
  if (d._err) return h('Demande d\'assistance', '') + `<p class="note t-bad">${esc(d._err)}</p>`;
  const t = d.ticket;
  return h(esc(t.subject), `${esc(t.ref)} · ${esc(SUPC[t.category] || t.category)} · ${esc(t.user || '')}`) + `<div class="stack">
  <div class="card sm stack"><div><b>Membre</b> : ${esc(t.user || '')} (${roleLbl(t.role)}) · ${esc(t.email || '')}${t.phone ? ' · ' + esc(t.phone) : ''}</div>${t.bookings?.ref ? `<div><b>Réservation</b> : ${esc(t.bookings.ref)}${t.booking_id ? ` <button class="linkbtn" data-a="adm-resa" data-id="${esc(t.booking_id)}">voir</button>` : ''}</div>` : ''}<div><span class="pill t-${(SUPS[t.status] || ['', 'muted'])[1]}">${esc((SUPS[t.status] || [t.status])[0])}</span> <button class="linkbtn" data-a="adm-user" data-id="${esc(t.user_id)}">Fiche du membre</button></div></div>
  ${d.messages.map(m => `<div class="card sm" style="${m.from_staff ? 'border-color:var(--gold)' : ''}"><b>${esc(m.author)}</b> <span class="xs muted">${dts(m.created_at)}</span><p class="ugc" style="margin:.3em 0 0;white-space:pre-wrap">${esc(m.body)}</p></div>`).join('')}
  ${t.status === 'fermee' ? '<p class="muted sm">Demande fermée.</p>' : `<form class="card stack" data-form="adm-sup-reply" data-id="${esc(t.id)}"><div class="field"><label for="sr-b">Réponse au membre</label><textarea id="sr-b" name="body" rows="4" maxlength="3000"></textarea></div>
  <div class="field"><label for="sr-s">Statut après la réponse</label><select id="sr-s" name="status"><option value="repondue">Répondue</option><option value="en_cours">En cours (traitement à poursuivre)</option><option value="resolue">Résolue</option><option value="fermee">Fermée</option></select></div>
  <p class="xs muted">Le membre est prévenu dans l'application (et par e-mail si l'envoi est configuré).</p><button class="btn pri">Envoyer la réponse</button></form>
  <div class="pbar"><button class="btn ghost" data-a="adm-sup-st" data-id="${esc(t.id)}" data-v="en_cours">Prendre en charge</button><button class="btn ghost" data-a="adm-sup-st" data-id="${esc(t.id)}" data-v="resolue">Marquer résolue</button><button class="btn ghost" data-a="adm-sup-st" data-id="${esc(t.id)}" data-v="fermee">Fermer</button></div>`}</div>`;
};

/* ---------- 8. Journal (actions et connexions) ---------- */
const EVL = { login_ok: 'Mot de passe correct', login_fail: 'Échec de connexion', mfa_ok: 'Connexion réussie (TOTP)', mfa_fail: 'Code TOTP incorrect', locked: 'Accès bloqué 15 min', unlocked: 'Accès débloqué', logout: 'Déconnexion', timeout: 'Déconnexion après inactivité', stepup_ok: 'Confirmation de sécurité', stepup_fail: 'Confirmation refusée', refused: 'Tentative pendant un blocage', password_changed: 'Mot de passe modifié', totp_reset: 'Double authentification réinitialisée', new_device: 'Nouvel appareil' };
function vAudit() {
  const F = AD.af || (AD.af = { q: '', from: '', to: '', page: 0 }), E = AD.ef || (AD.ef = { page: 0 });
  const d = need('audit', () => admApi('audit', F)), ev = need('authev', () => admApi('auth_events', E));
  return `<section class="section"><h2>Journal d'audit</h2><p class="muted sm">Chaque décision et chaque consultation sensible est horodatée. Le journal ne peut être ni modifié ni supprimé.</p>
  <form class="row" data-form="adm-audit" style="flex-wrap:wrap;gap:8px"><input name="q" value="${esc(F.q)}" placeholder="Rechercher une action" style="flex:1;min-width:180px"><label class="xs">Du <input type="date" name="from" value="${esc(F.from)}"></label><label class="xs">au <input type="date" name="to" value="${esc(F.to)}"></label><button class="btn pri">Filtrer</button></form>
  ${!d ? '<p class="muted">Chargement…</p>' : d._err ? errBox(d) : d.logs.length ? `<div class="tbl"><table class="t"><tr><th>Horodatage</th><th>Acteur</th><th>Action</th><th>Réf.</th></tr>${d.logs.map(l => `<tr><td class="num">${fts(Date.parse(l.created_at))}</td><td>${esc(l.actor)}</td><td>${esc(l.action)}</td><td class="num xs">${esc(l.ref || '')}</td></tr>`).join('')}</table></div>${pager('audit', d)}` : '<div class="empty">Journal vide.</div>'}</section>
  <section class="section"><h3>Connexions à l'espace de gestion</h3>${!ev ? '<p class="muted">Chargement…</p>' : ev._err ? errBox(ev) : ev.events.length ? `<div class="tbl"><table class="t"><tr><th>Horodatage</th><th>Compte</th><th>Événement</th><th>Adresse IP</th><th>Navigateur</th></tr>${ev.events.map(e => `<tr><td class="num">${fts(Date.parse(e.created_at))}</td><td class="xs">${esc(e.email || '')}</td><td>${/fail|locked|refused|new_device/.test(e.event) ? `<span class="pill t-bad">${esc(EVL[e.event] || e.event)}</span>` : esc(EVL[e.event] || e.event)}</td><td class="num xs">${esc(e.ip || '')}</td><td class="xs muted">${esc((e.user_agent || '').slice(0, 60))}</td></tr>`).join('')}</table></div>${pager('authev', ev)}` : '<div class="empty">Aucune connexion enregistrée.</div>'}
  <p class="xs muted">Les mots de passe et codes ne sont jamais enregistrés.</p></section>`;
}

/* ---------- 9. Paramètres, équipe, annonces, sécurité ---------- */
const SET_FIELDS = [['client_fee_pct', 'Frais de service client (%)', 0, 30, .5], ['companion_fee_pct', 'Commission accompagnateur (%)', 0, 40, .5], ['privilege_fee_pct', 'Frais client Privilège (%)', 0, 30, .5], ['privilege_price_eur', 'Abonnement Privilège (€/mois)', 0, 100, .1], ['vat_pct', 'TVA sur les frais (%)', 0, 30, .1],
  ['referral_eur', 'Crédit de parrainage (€)', 0, 100, 1], ['min_hours', 'Durée minimale (h)', 1, 12, 1], ['max_hours', 'Durée maximale (h)', 1, 24, 1], ['dispute_days', 'Délai de traitement d\'un litige (j)', 1, 30, 1], ['noshow_pct', 'Indemnité d\'absence du client (%)', 0, 100, 1],
  ['cancel_early_pct', 'Annulation plus de 48 h avant (% remboursé)', 0, 100, 1], ['cancel_mid_pct', 'Annulation entre 24 et 48 h (% remboursé)', 0, 100, 1], ['cancel_late_pct', 'Annulation moins de 24 h (% remboursé)', 0, 100, 1]];
function vSettings() {
  const st = need('settings', () => admApi('settings_get')), ad = need('admins', () => admApi('admins')), an = need('ann', () => admApi('announcements'));
  const sup = AD.me && AD.me.level === 'super';
  const sv = st && !st._err ? st.settings : null;
  return `<section class="section"><h2>Paramètres</h2>
  ${!st ? '<p class="muted">Chargement…</p>' : st._err ? errBox(st) : `<form class="card stack" data-form="adm-settings"><h3>Paramètres financiers et règles</h3>${sup ? '' : '<p class="note t-warn sm">Lecture seule : seul le dirigeant (super-administrateur) peut modifier ces paramètres.</p>'}
  <div class="row" style="flex-wrap:wrap">${SET_FIELDS.map(([k, l, lo, hi, stp]) => `<div class="field grow" style="min-width:210px"><label for="st-${k}">${l}</label><input id="st-${k}" type="number" name="${k}" min="${lo}" max="${hi}" step="${stp}" value="${esc(sv[k] ?? '')}" ${sup ? '' : 'disabled'}></div>`).join('')}</div>
  ${'insurance_required' in sv ? `<label class="row sm"><input type="checkbox" name="insurance_required" ${sv.insurance_required ? 'checked' : ''} ${sup ? '' : 'disabled'}> Assurance responsabilité civile obligatoire pour recevoir des réservations</label>` : ''}
  <p class="xs muted">Les nouvelles règles s'appliquent aux nouvelles réservations ; elles sont affichées au client avant tout paiement. Modification journalisée (avant / après), nouveau code de double authentification demandé.</p>${sup ? '<button class="btn pri">Enregistrer</button>' : ''}</form>`}</section>
  <section class="section"><h3>Équipe d'administration</h3>${!ad ? '<p class="muted">Chargement…</p>' : ad._err ? errBox(ad) : `<div class="tbl"><table class="t"><tr><th>Membre</th><th>E-mail</th><th>Niveau</th><th>Double authentification</th><th>Dernière connexion</th><th>État</th>${sup ? '<th>Actions</th>' : ''}</tr>
  ${ad.admins.map(x => `<tr><td><b>${esc((x.first_name || '') + ' ' + (x.last_name || ''))}</b></td><td class="xs">${esc(x.email)}</td><td>${x.level === 'super' ? '<span class="chip gold">Dirigeant</span>' : 'Administrateur'}</td><td>${x.totp ? '<span class="pill t-ok">Active</span>' : '<span class="pill t-warn">À activer</span>'}</td><td>${x.last_login ? dts(x.last_login) : '—'}</td>
    <td>${x.revoked_at ? '<span class="pill t-muted">Accès retiré</span>' : x.locked_until && Date.parse(x.locked_until) > Date.now() ? '<span class="pill t-bad">Bloqué</span>' : '<span class="pill t-ok">Actif</span>'}</td>
    ${sup ? `<td class="acts">${x.level !== 'super' && !x.revoked_at ? `<button class="btn" data-a="adm-unlock" data-v="${esc(x.email)}">Débloquer</button><button class="btn" data-a="adm-totp-reset" data-id="${esc(x.user_id)}">Réinitialiser la double authentification</button><button class="btn bad" data-a="adm-revoke" data-id="${esc(x.user_id)}">Retirer l'accès</button>` : ''}</td>` : ''}</tr>`).join('')}</table></div>
  ${sup ? `<form class="card stack" data-form="adm-create"><h3>Ajouter un administrateur</h3><div class="row" style="flex-wrap:wrap"><div class="field grow"><label for="ac-f">Prénom</label><input id="ac-f" name="first_name"></div><div class="field grow"><label for="ac-l">Nom</label><input id="ac-l" name="last_name"></div><div class="field grow" style="min-width:240px"><label for="ac-e">E-mail professionnel dédié</label><input id="ac-e" name="email" type="email"></div></div>
  <p class="xs muted">Un mot de passe provisoire s'affiche une seule fois : transmettez-le de vive voix. À la première connexion, la personne choisit son mot de passe et active sa double authentification.</p><button class="btn pri">Créer l'accès</button></form>` : '<p class="xs muted">Seul le dirigeant peut ajouter ou retirer un administrateur.</p>'}`}</section>
  <section class="section"><h3>Annonces aux membres</h3><form class="card stack" data-form="adm-announce"><div class="field"><label for="an-a">Destinataires</label><select id="an-a" name="audience"><option value="all">Tous les membres</option><option value="client">Clients</option><option value="companion">Accompagnateurs</option></select></div>
  <div class="field"><label for="an-b">Message (notification dans l'application)</label><textarea id="an-b" name="body" rows="3" maxlength="400"></textarea></div><button class="btn pri">Envoyer l'annonce</button></form>
  ${an && !an._err && an.announcements.length ? `<div class="tbl"><table class="t"><tr><th>Date</th><th>Public</th><th>Message</th><th>Destinataires</th></tr>${an.announcements.map(x => `<tr><td>${dts(x.created_at)}</td><td>${esc({ all: 'Tous', client: 'Clients', companion: 'Accompagnateurs' }[x.audience])}</td><td class="ugc">${esc(x.body)}</td><td class="num">${x.recipients}</td></tr>`).join('')}</table></div>` : ''}</section>
  <section class="section"><h3>Sécurité de mon compte</h3><div class="card stack sm"><div class="row"><b class="grow">Double authentification</b><span class="pill t-ok">Active</span></div><div class="row"><b class="grow">Déconnexion automatique</b><span>après 15 minutes d'inactivité</span></div><div class="row"><b class="grow">Opérations sensibles</b><span>nouveau code demandé</span></div><div class="row"><b class="grow">Niveau</b><span>${sup ? 'Dirigeant (super-administrateur)' : 'Administrateur'}</span></div></div>
  <form class="card stack" data-form="adm-mypw"><b>Changer mon mot de passe</b><div class="field"><label for="mp-1">Nouveau mot de passe</label><input id="mp-1" name="pw" type="password" autocomplete="new-password"></div><div class="field"><label for="mp-2">Confirmation</label><input id="mp-2" name="pw2" type="password" autocomplete="new-password"></div><button class="btn">Enregistrer</button></form>
  <button class="btn bad full" data-a="adm-logout">Se déconnecter</button></section>`;
}

/* ---------- Interactions ---------- */
async function admRun(p, ok, keys) { try { const r = await p; if (ok) toast(ok); refreshAll(keys); return r; } catch (e) { if (e.message !== 'annulé') toast(e.message, true); render(); return null; } }
function v30AdminClick(a, el, id, v) {
  switch (a) {
    case 'tab': if (S.role === 'admin' && ADMIN_TABS.includes(v)) { S.tab = v; S.sheet = null; render(); window.scrollTo(0, 0); return true; } return false;
    case 'adm-refresh': refreshAll(); return true;
    case 'notifs': if (S.role === 'admin') { S.tab = 'dashboard'; S.sheet = null; render(); return true; } return false;
    case 'security': if (S.role === 'admin') { S.tab = 'settings'; S.sheet = null; render(); return true; } return false;
    case 'adm-cancel': admLogout('deconnexion'); return true;
    case 'adm-logout': admLogout('deconnexion', 'Vous êtes déconnecté.'); return true;
    case 'adm-page': { const [k, p] = v.split('|'), map = { users: 'uf', bookings: 'bf', tx: 'tf', sup: 'sf', audit: 'af', authev: 'ef' }; AD[map[k]].page = Math.max(0, +p); delete AD[k]; render(); return true; }
    case 'adm-user': delete AD['user:' + id]; open('admuser', { id }); render(); return true;
    case 'adm-resa': delete AD['resa:' + id]; open('admresa', { id }); render(); return true;
    case 'adm-ticket': delete AD['tk:' + id]; open('admticket', { id }); render(); return true;
    case 'adm-notif-read': admRun(admApi('notifications_read'), null, ['dash']); return true;
    case 'adm-comp': admRun(admApi('companion_review', { companion_id: id, approve: true, tier: v }), 'Profil validé.', ['ov', 'users', 'user:' + id]); return true;
    case 'adm-dossier': admRun(admApi('admin_review', { companion_id: id, approve: true }), 'Dossier administratif validé.', ['ov', 'user:' + id]); return true;
    case 'adm-rev': admRun(admApi('review_moderate', { review_id: id, publish: v === '1' }), v === '1' ? 'Avis publié.' : 'Avis masqué.', ['reviews']); return true;
    case 'adm-cancel-resa': if (S._admConfirm !== id) { S._admConfirm = id; toast('Touchez à nouveau pour confirmer l\'annulation et le remboursement.'); render(); return true; }
      S._admConfirm = null; admRun(admCall('refund-booking', { booking_id: id }), 'Réservation annulée : le client est remboursé.', ['bookings', 'resa:' + id, 'fin', 'tx', 'dash']); return true;
    case 'adm-payout': admRun(admCall('release-payout', { booking_id: id }), 'Versement exécuté.', ['bookings', 'resa:' + id, 'fin', 'tx']); return true;
    case 'adm-supf': AD.sf = { status: v, q: '', page: 0 }; delete AD.sup; render(); return true;
    case 'adm-sup-st': admRun(admApi('support_status', { ticket_id: id, status: v }), 'Statut mis à jour.', ['sup', 'tk:' + id, 'dash']); return true;
    case 'adm-unlock': admRun(admApi('admin_unlock', { email: v }), 'Accès débloqué.', ['admins']); return true;
    case 'adm-totp-reset': if (S._admConfirm !== id) { S._admConfirm = id; toast('Touchez à nouveau pour confirmer la réinitialisation.'); render(); return true; }
      S._admConfirm = null; admRun(admApi('admin_reset_totp', { user_id: id }), 'Double authentification réinitialisée : nouvelle association à la prochaine connexion.', ['admins']); return true;
    case 'adm-revoke': if (S._admConfirm !== id) { S._admConfirm = id; toast('Touchez à nouveau pour confirmer le retrait de l\'accès.'); render(); return true; }
      S._admConfirm = null; admRun(admApi('admin_revoke', { user_id: id }), 'Accès administrateur retiré.', ['admins']); return true;
    case 'adm-csv-b': { const d = AD.bookings; if (!d || !d.bookings) return true; admDl(`reservations-${new Date().toISOString().slice(0, 10)}.csv`, [csvLine(['Référence', 'Date', 'Client', 'Accompagnateur', 'Statut', 'Total', 'Commission', 'Frais client HT', 'Versement']), ...d.bookings.map(b => csvLine([b.ref, b.starts_at, b.client, b.companion, b.status, b.amount_total, b.amount_commission, b.amount_client_fee, b.amount_payout]))].join('\n')); return true; }
    case 'adm-csv-tx': { const d = AD.tx; if (!d || !d.transactions) return true; admDl(`transactions-${new Date().toISOString().slice(0, 10)}.csv`, [csvLine(['Date', 'Mouvement', 'Réservation', 'Référence Stripe', 'Montant']), ...d.transactions.map(t => csvLine([t.created_at, t.kind, t.bookings?.ref || '', t.stripe_object_id || '', t.amount]))].join('\n')); return true; }
    case 'close': if (S.sheet && S.sheet.type === 'stepup' && admStepWait) { admStepWait.ko(new Error('annulé')); admStepWait = null; } return false;
    default: return false;
  }
}
function v30AdminSubmit(k, f, d) {
  const btnOk = () => { const b = document.activeElement; return b && b.name === 'ok' ? b.value === '1' : (f._okv ?? true); };
  const err = (m) => { G.err = m; G.busy = false; render(); };
  switch (k) {
    case 'adm-login': {
      G.busy = true; G.err = ''; G.info = ''; render();
      admAuth({ action: 'login', email: d.email, password: d.password }).then(async r => {
        if (!r.session) return err(r.error || 'Connexion impossible.');
        const { error } = await SB.auth.setSession({ access_token: r.session.access_token, refresh_token: r.session.refresh_token });
        if (error) return err('Connexion impossible.');
        try { await admStartMfa(); } catch (e) { return err('Impossible de préparer la double authentification.'); }
        G.busy = false; render();
      }).catch(() => err('Le serveur ne répond pas. Réessayez.'));
      return true;
    }
    case 'adm-mfa': {
      const code = String(d.code || '').replace(/\D/g, ''); if (code.length !== 6) return err('Saisissez les 6 chiffres du code.'), true;
      G.busy = true; render();
      admToken().then(async s => {
        const r = await admAuth({ action: 'mfa_verify', access_token: s && s.access_token, refresh_token: s && s.refresh_token, code, factor_id: G.factorId });
        if (!r.session) return err(r.error || 'Code incorrect.');
        await SB.auth.setSession({ access_token: r.session.access_token, refresh_token: r.session.refresh_token });
        G.busy = false; G.qr = null; G.secret = null;
        if (r.must_change_password) { G.step = 'pw'; render(); return; }
        try { await admEnter(); } catch (e) { err(e.message); }
      }).catch(() => err('Le serveur ne répond pas. Réessayez.'));
      return true;
    }
    case 'adm-pw': case 'adm-mypw': {
      if ((d.pw || '') !== (d.pw2 || '')) { if (k === 'adm-pw') err('Les deux mots de passe ne correspondent pas.'); else toast('Les deux mots de passe ne correspondent pas.', true); return true; }
      admToken().then(async s => {
        const r = await admAuth({ action: 'change_password', password: d.pw }, s && s.access_token);
        if (!r.ok) { if (k === 'adm-pw') return err(r.error || 'Mot de passe refusé.'); return toast(r.error || 'Mot de passe refusé.', true); }
        // Le serveur ferme toutes les sessions du compte : reconnexion avec le nouveau mot de passe et le code TOTP
        await admLogout('mot_de_passe', 'Mot de passe enregistré. Reconnectez-vous avec votre nouveau mot de passe et votre code de double authentification.');
      });
      return true;
    }
    case 'adm-stepup': {
      const code = String(d.code || '').replace(/\D/g, ''), e = document.getElementById('su-err');
      if (code.length !== 6) { if (e) { e.textContent = 'Saisissez les 6 chiffres.'; e.hidden = false; } return 'stop'; }
      admToken().then(async s => {
        const r = await admAuth({ action: 'stepup', code, refresh_token: s && s.refresh_token }, s && s.access_token);
        if (!r.session) { if (r.status === 401 && /Session/.test(r.error || '')) return admExpired(r.error); if (e) { e.textContent = r.error || 'Code incorrect.'; e.hidden = false; } return; }
        await SB.auth.setSession({ access_token: r.session.access_token, refresh_token: r.session.refresh_token });
        S.sheet = null; render(); const w = admStepWait; admStepWait = null; w && w.ok();
      });
      return true;
    }
    case 'adm-users': AD.uf = { q: d.q || '', role: d.role || '', status: d.status || '', page: 0 }; delete AD.users; render(); return true;
    case 'adm-bookings': AD.bf = { q: d.q || '', status: d.status || '', from: d.from || '', to: d.to || '', page: 0 }; delete AD.bookings; render(); return true;
    case 'adm-fin': AD.ff = { from: d.from, to: d.to }; delete AD.fin; render(); return true;
    case 'adm-audit': AD.af = { q: d.q || '', from: d.from || '', to: d.to || '', page: 0 }; delete AD.audit; render(); return true;
    case 'adm-id': { const ok = btnOk(), reason = (d.reason || '').trim(); if (!ok && reason.length < 5) return toast('Indiquez le motif du refus (5 caractères minimum).', true), true;
      admRun(admApi('identity_review', { check_id: f.dataset.id, approve: ok, reason }), ok ? 'Identité validée.' : 'Pièce refusée : le membre est prévenu.', ['ov', 'dash']); return true; }
    case 'adm-dossier': { const ok = btnOk(), reason = (d.reason || '').trim(); if (!ok && reason.length < 5) return toast('Indiquez le motif du refus (5 caractères minimum).', true), true;
      admRun(admApi('admin_review', { companion_id: f.dataset.id, approve: ok, reason }), ok ? 'Dossier validé.' : 'Dossier refusé : l\'accompagnateur est prévenu.', ['ov']); return true; }
    case 'adm-photo': { const ok = btnOk(), reason = (d.reason || '').trim(); if (!ok && reason.length < 5) return toast('Indiquez le motif du refus (5 caractères minimum).', true), true;
      admRun(admApi('photo_review', { photo_id: f.dataset.id, approve: ok, reason }), ok ? 'Photo validée : elle est visible sur le profil.' : 'Photo refusée : l\'accompagnateur est prévenu.', ['photos', 'dash']); return true; }
    case 'adm-suspend': { const reason = (d.reason || '').trim(); if (reason.length < 5) return toast('Indiquez le motif (5 caractères minimum).', true), true;
      const susp = f.dataset.v === '1'; admRun(admApi('suspend', { user_id: f.dataset.id, suspended: susp, reason }), susp ? 'Compte suspendu.' : 'Compte réactivé.', ['users', 'user:' + f.dataset.id, 'dash']); return true; }
    case 'adm-decide': { const note = (d.note || '').trim(); if (note.length < 5) return toast('Motivez la décision (5 caractères minimum).', true), true;
      admRun(admApi('dispute_decide', { dispute_id: f.dataset.id, decision: d.decision, refund_pct: d.decision === 'refund' ? Math.max(0, Math.min(100, +d.pct || 0)) : null, note }), 'Décision enregistrée.', ['disp', 'disph', 'dash', 'fin', 'tx']); return true; }
    case 'adm-sup-reply': { const body = (d.body || '').trim(); if (body.length < 2) return toast('Rédigez la réponse.', true), true;
      admRun(admApi('support_reply', { ticket_id: f.dataset.id, body, status: d.status }), 'Réponse envoyée au membre.', ['sup', 'tk:' + f.dataset.id, 'dash']); return true; }
    case 'adm-settings': { const s = {}; SET_FIELDS.forEach(([kk]) => { if (d[kk] !== undefined && d[kk] !== '') s[kk] = +d[kk]; }); if (f.querySelector('[name=insurance_required]')) s.insurance_required = !!f.querySelector('[name=insurance_required]').checked;
      admRun(admApi('settings_update', { settings: s }), 'Paramètres enregistrés.', ['settings', 'fin']); return true; }
    case 'adm-announce': { const body = (d.body || '').trim(); if (body.length < 5) return toast('Rédigez le message (5 caractères minimum).', true), true;
      admRun(admApi('announce', { audience: d.audience, body }).then(r => { toast(`Annonce envoyée à ${r.recipients} membre(s).`); return r; }), null, ['ann']); return true; }
    case 'adm-create': admRun(admApi('admin_create', { email: d.email, first_name: d.first_name, last_name: d.last_name }).then(r => { open('admtemp', { pw: r.temporary_password, email: d.email }); return r; }), null, ['admins']); return true;
    default: return false;
  }
}
EXTRA_SHEETS.admtemp = (s, h) => h('Accès créé', esc(s.email)) + `<div class="stack"><p class="sm">Mot de passe provisoire, affiché <b>une seule fois</b> :</p><p class="card num sel" style="font-size:1.2em;word-break:break-all">${esc(s.pw)}</p>
  <p class="xs muted">Transmettez-le de vive voix ou en personne, jamais par e-mail ni par message. À la première connexion sur /gestion, la personne choisit son mot de passe puis active Google Authenticator.</p><button class="btn pri full" data-a="close">J'ai noté le mot de passe</button></div>`;

/* ---------- Démarrage de l'espace de gestion ---------- */
function v30AdminInit() {
  if (window.__v30a) return; window.__v30a = 1;
  document.title = 'Gestion — Side by Side';
  Object.assign(T.fr, { verif: 'Vérifications', finances: 'Finances', support: 'Assistance', audit: 'Journal', users: 'Comptes', bookings: 'Réservations', dashboard: 'Tableau', settings: 'Réglages', disputes: 'Litiges' });
  Object.assign(ICON, { verif: '<path d="M12 2.5 4 5.5v6c0 5 3.4 8.6 8 10 4.6-1.4 8-5 8-10v-6z"/><path d="m8.5 12 2.5 2.5 4.5-5"/>', finances: '<path d="M17 6.5a6.5 6.5 0 1 0 0 11M4.5 10.5h9M4.5 13.5h9"/>', support: '<path d="M4 5h16v11H9l-5 4z"/><path d="M8 9.5h8M8 12.5h5"/>' });
  if (!ICON.bookings) ICON.bookings = '<rect x="3.5" y="5" width="17" height="15" rx="2.5"/><path d="M3.5 10h17M8 3v4M16 3v4"/>';
  ADMIN_VIEWS = { dashboard: vDash, users: vUsers, verif: vVerif, bookings: vBookings, finances: vFinances, disputes: vDisputes, support: vSupport, audit: vAudit, settings: vSettings };
  // Aucune inscription, aucun parcours client ou accompagnateur dans l'espace de gestion
  welcome = () => admLoginPage(); signupPage = () => admLoginPage(); mfa = () => admLoginPage(); liveMfaHtml = () => admLoginPage();
  if (typeof liveLogin === 'function') liveLogin = () => admLoginPage();
  liveLoad = admLoad; liveSubscribe = () => {}; liveCall = (fn, body) => admCall(fn, body);
  ['mousemove', 'keydown', 'click', 'scroll', 'touchstart'].forEach(ev => document.addEventListener(ev, admActivity, { passive: true }));
  setInterval(admIdleWatch, 15_000);
  document.addEventListener('change', e => {
    const t = e.target;
    if (t && t.matches && t.matches('[data-adm-days]')) { AD.days = +t.value; delete AD.dash; render(); }
    if (t && t.matches && t.matches('[data-adm-txkind]')) { AD.tf = { kind: t.value, page: 0 }; delete AD.tx; render(); }
  });
  // Bouton de validation / refus dans un formulaire : mémorise le bouton utilisé
  document.addEventListener('click', e => { const b = e.target.closest && e.target.closest('button[name=ok]'); if (b && b.form) b.form._okv = b.value === '1'; }, true);
}

/* ================= V2.5 — Mode connecté, lot 2 : mission, SOS, notifications, identité, RGPD, administration sécurisée =================
   Tout ce qui suit ne s'exécute qu'en mode connecté (application native). La démo en ligne ne change pas. */
const LIVE_ADM={data:null,busy:false};
const tr_=(m,bad)=>{toast(m,bad);render()};   // message affiché après une réponse du serveur
function liveNotifs(rows){S.notifs=(rows||[]).map(n=>({id:n.id,to:S.role,text:n.body,t:Date.parse(n.created_at),read:!!n.read_at,kind:n.kind,bid:n.booking_id}))}
async function liveExtra(p){
  const [nt,ids]=await Promise.all([SB.from('notifications').select('*').order('created_at',{ascending:false}).limit(60),SB.from('identity_checks').select('status,reason,created_at').order('created_at',{ascending:false}).limit(1)]);
  liveNotifs(nt.data);S.liveId=(ids.data||[])[0]||null;
  // Historique horodaté par le serveur (booking_events) et réglages de l'accompagnateur
  const bids=S.bookings.map(b=>b.id);
  if(bids.length){const {data:ev}=await SB.from('booking_events').select('booking_id,status,note,created_at').in('booking_id',bids).order('id');const g={};(ev||[]).forEach(e=>{(g[e.booking_id]=g[e.booking_id]||[]).push({s:e.status||'note',t:Date.parse(e.created_at),actor:'',note:e.note||''})});S.bookings.forEach(b=>{if(g[b.id]&&g[b.id].length)b.history=g[b.id]})}
  if(p.role==='companion'){const c=comp('c1');if(c){const [cr,bd]=await Promise.all([SB.from('companions').select('travel_buffer_min,payouts_enabled,legal_status,tax_id,admin_status,admin_doc_path').eq('id',p.id).single(),SB.from('companion_blocked_days').select('day').eq('companion_id',p.id)]);
    const x=cr.data||{};c.buffer=x.travel_buffer_min||0;c._payouts=!!x.payouts_enabled;c.adm={legal:x.legal_status||'',siret:x.tax_id||'',status:x.admin_status||'a_completer',doc:!!x.admin_doc_path};c.blocked=(bd.data||[]).map(r=>r.day)}}
  // Code de rencontre : demandé au serveur, jamais stocké dans la base lisible
  await Promise.all(S.bookings.filter(b=>b.clientId==='u1'&&['confirmee','controle'].includes(b.status)).map(async b=>{try{const c=await liveCall('mission-action',{booking_id:b.id,action:'get_code'});b.code={value:c.code,distress:c.distress,expires:Date.parse(c.expires_at),attempts:0,used:false,locked:false}}catch(e){b.code=null}}));
  S.bookings.forEach(b=>{if(b.companionId==='c1'&&!b.code)b.code={value:'',distress:'',expires:b.start+(b.hours+2)*H,attempts:0,used:false,locked:false}})}
function liveAdapt2(x,b){b.payoutDone=!!x.payout_done;b.payDeadline=x.payment_deadline?Date.parse(x.payment_deadline):null;b.prest=+x.amount_service;b.comm=+(x.amount_commission||0);b.presence={client:!!x.presence_client,companion:!!x.presence_companion};b.starts={client:x.start_client?Date.parse(x.start_client):null,companion:x.start_companion?Date.parse(x.start_companion):null};b.extMins=x.extra_minutes||0;return b}

/* ---------- Administration : vrai compte admin + double authentification TOTP (Supabase Auth) ---------- */
async function liveMfaInit(){S.liveMfa={step:'loading'};
  try{const {data:a}=await SB.auth.mfa.getAuthenticatorAssuranceLevel();
    if(a&&a.currentLevel==='aal2'){S.adminOk=true;S.liveMfa=null;liveAdminLoad();return}
    const {data:f}=await SB.auth.mfa.listFactors();const ok=(f.totp||[]).find(x=>x.status==='verified');
    if(ok){S.liveMfa={step:'verify',factorId:ok.id};render();return}
    for(const x of (f.all||[]).filter(x=>x.status!=='verified'))await SB.auth.mfa.unenroll({factorId:x.id});
    const {data:e,error}=await SB.auth.mfa.enroll({factorType:'totp',friendlyName:'Side by Side Admin'});if(error)throw error;
    S.liveMfa={step:'enroll',factorId:e.id,qr:e.totp.qr_code,secret:e.totp.secret};render()}
  catch(e){S.liveMfa={step:'error'};render()}}
function liveMfaHtml(){const M=S.liveMfa;if(!M){setTimeout(liveMfaInit,0);return `<section class="section"><p class="muted">Vérification de la sécurité…</p></section>`}
  if(M.step==='loading')return `<section class="section"><p class="muted">Vérification de la sécurité…</p></section>`;
  if(M.step==='error')return `<section class="section" style="max-width:420px;margin:0 auto"><h2>Double authentification</h2><p class="note t-bad sm">Impossible de joindre le serveur de sécurité.</p><button class="btn pri full" data-a="live-mfa-retry">Réessayer</button></section>`;
  return `<section class="section" style="max-width:420px;margin:0 auto"><h2>Double authentification</h2>${M.step==='enroll'?`<p class="muted">Première connexion : scannez ce QR code avec une application d'authentification (Google Authenticator, Microsoft Authenticator…).</p><div class="card" style="text-align:center"><img src="${M.qr}" alt="QR code de double authentification" style="width:200px;height:200px;background:#fff;padding:8px;border-radius:12px"><p class="xs muted">Ou saisissez la clé : <b class="sel num">${esc(M.secret)}</b></p></div>`:'<p class="muted">L\'espace administrateur exige un second facteur à chaque connexion.</p>'}
  <form class="card stack" data-form="live-mfa"><div class="field"><label for="mfa-code">Code à 6 chiffres de l'application d'authentification</label><input id="mfa-code" name="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="••••••"></div><p class="note t-bad sm" id="mfa-err" hidden></p><button class="btn pri full">Valider</button></form></section>`}
async function liveAdminLoad(){LIVE_ADM.busy=true;render();try{LIVE_ADM.data=await liveCall('admin-action',{action:'overview'})}catch(e){toast(e.message,true)}LIVE_ADM.busy=false;render()}
const admDo=(body,ok)=>liveCall('admin-action',body).then(()=>{toast(ok);liveAdminLoad()}).catch(e=>tr_(e.message,true));
const lfd=t=>t?fdt(Date.parse(t)):'—';
function lAdmDash(){const D=LIVE_ADM.data;if(!D)return `<section class="section"><p class="muted">${LIVE_ADM.busy?'Chargement…':'Aucune donnée.'}</p><button class="btn" data-a="live-adm-refresh">Actualiser</button></section>`;
  return `<section class="section"><div class="row"><h2 class="grow">Tableau de bord</h2><button class="btn ghost" data-a="live-adm-refresh">Actualiser</button></div>
  <div class="kpis"><div class="card kpi"><span class="lbl">Alertes de sécurité (7 j)</span><span class="num">${D.alerts.length}</span></div><div class="card kpi"><span class="lbl">Identités à vérifier</span><span class="num">${D.identity.length}</span></div><div class="card kpi"><span class="lbl">Litiges ouverts</span><span class="num">${D.disputes.length}</span></div><div class="card kpi"><span class="lbl">Missions à vérifier</span><span class="num">${D.review.length}</span></div></div></section>
  <section class="section"><h3>Alertes de sécurité</h3>${D.alerts.length?D.alerts.map(a=>`<div class="card stack"><div class="row"><b class="grow">${esc(a.kind)}</b><span class="pill t-bad">${a.bookings?esc(a.bookings.ref):'Hors réservation'}</span></div><span class="xs muted">${lfd(a.created_at)}${a.latitude!=null?` · position ${a.latitude.toFixed(5)}, ${a.longitude.toFixed(5)}`:''}</span>${a.latitude!=null?`<a class="btn ghost" href="https://www.openstreetmap.org/?mlat=${a.latitude}&mlon=${a.longitude}#map=17/${a.latitude}/${a.longitude}" target="_blank" rel="noopener">Voir sur la carte</a>`:''}<button class="btn bad" data-a="live-adm-suspend" data-id="${esc(a.user_id)}">Suspendre l'auteur de l'alerte</button></div>`).join(''):'<div class="empty">Aucune alerte.</div>'}</section>
  <section class="section"><h3>Missions à vérifier</h3>${D.review.length?D.review.map(b=>`<div class="card row"><b class="grow">${esc(b.ref)}</b>${pill(b.status)}<span class="xs muted">${lfd(b.starts_at)}${b.payout_error?` · ${esc(b.payout_error)}`:''}</span></div>`).join(''):'<div class="empty">Rien à vérifier.</div>'}</section>`}
function lAdmDisputes(){const D=LIVE_ADM.data;if(!D)return lAdmDash();
  return `<section class="section"><h2>Litiges ouverts</h2>${D.disputes.length?D.disputes.map(d=>`<form class="card stack" data-form="live-adm-decide" data-id="${esc(d.id)}"><div class="row"><b class="grow">${esc(d.bookings?.ref||'')} · ${esc(d.reason)}</b><span class="pill ${Date.parse(d.deadline)<now()?'t-bad':'t-warn'}">Échéance ${lfd(d.deadline)}</span></div><p class="sm ugc">${esc(d.description)}</p><span class="xs muted">Montant payé ${eur(+(d.bookings?.amount_total||0))} · versement prévu ${eur(+(d.bookings?.amount_payout||0))}</span>
    <div class="field"><label>Décision</label><select name="decision"><option value="payout">Prestation réalisée : verser l'accompagnateur</option><option value="refund">Rembourser le client</option></select></div><div class="field"><label>Remboursement du client (%)</label><input name="pct" type="number" min="0" max="100" value="100" inputmode="numeric"></div><div class="field"><label>Motif de la décision (obligatoire)</label><textarea name="note" rows="2"></textarea></div><button class="btn pri">Enregistrer la décision</button></form>`).join(''):'<div class="empty">Aucun litige ouvert.</div>'}</section>`}
function lAdmUsers(){const D=LIVE_ADM.data;if(!D)return lAdmDash();
  return `<section class="section"><h2>Pièces d'identité à vérifier</h2>${D.identity.length?D.identity.map(x=>`<div class="card stack"><div class="row"><b class="grow">${esc((x.profiles?.first_name||'')+' '+(x.profiles?.last_name||''))}</b><span class="pill t-warn">${x.profiles?.role==='companion'?'Accompagnateur':'Client'}</span></div><span class="xs muted">Né(e) le ${esc(x.profiles?.birth_date||'—')} · déposé le ${lfd(x.created_at)}</span>
    <div class="row">${x.doc_url?`<a class="btn ghost" href="${esc(x.doc_url)}" target="_blank" rel="noopener">Voir la pièce</a>`:''}${x.selfie_url?`<a class="btn ghost" href="${esc(x.selfie_url)}" target="_blank" rel="noopener">Voir le selfie</a>`:''}</div><p class="xs muted">Liens valables 10 minutes. Vérifiez la majorité, la correspondance du visage et la validité du document.</p>
    <div class="pbar"><button class="btn pri" data-a="live-adm-id" data-id="${esc(x.id)}" data-v="1">Valider l'identité</button><button class="btn bad" data-a="live-adm-id" data-id="${esc(x.id)}" data-v="0">Refuser</button></div></div>`).join(''):'<div class="empty">Aucune pièce en attente.</div>'}</section>
  <section class="section"><h2>Accompagnateurs à valider</h2>${D.companions.length?D.companions.map(c=>`<div class="card stack"><div class="row"><b class="grow">${esc((c.profiles?.first_name||'')+' '+(c.profiles?.last_name||''))}</b>${c.profiles?.identity_verified?'<span class="pill t-ok">Identité vérifiée</span>':'<span class="pill t-warn">Identité non vérifiée</span>'}</div><span class="xs muted">${esc(c.profiles?.city||'')} · ${eur(+c.hourly_rate)}/h · ${esc((c.categories||[]).join(', ')||'aucune activité')}</span>${c.bio?`<p class="sm ugc">${esc(c.bio)}</p>`:''}
    <div class="pbar"><button class="btn pri" data-a="live-adm-comp" data-id="${esc(c.id)}" data-v="Standard" ${c.profiles?.identity_verified?'':'disabled'}>Valider (Standard)</button><button class="btn" data-a="live-adm-comp" data-id="${esc(c.id)}" data-v="Prestige" ${c.profiles?.identity_verified?'':'disabled'}>Valider (Prestige)</button></div></div>`).join(''):'<div class="empty">Aucun profil en attente.</div>'}</section>`}
function lAdmAudit(){const D=LIVE_ADM.data;if(!D)return lAdmDash();return `<section class="section"><h2>Journal de sécurité</h2>${D.logs.map(l=>`<div class="card row"><span class="xs muted">${lfd(l.created_at)}</span><span class="grow sm">${esc(l.action)}</span><span class="xs muted">${esc(l.ref||'')}</span></div>`).join('')||'<div class="empty">Journal vide.</div>'}</section>`}
function lAdmSettings(){return `<section class="section"><h2>Sécurité de l'administration</h2><div class="card stack"><div class="row"><b class="grow">Double authentification</b><span class="pill t-ok">Active</span></div><p class="xs muted">Chaque connexion à l'espace administrateur exige le mot de passe du compte et un code de l'application d'authentification. Chaque décision est enregistrée dans le journal de sécurité. Les réglages financiers se modifient dans la base de données, avec l'accord du dirigeant.</p></div></section>`+logoutBlock()}

/* ---------- Vérification d'identité et données personnelles (RGPD) ---------- */
function liveIdCard(){const u=S.users.u1,L=S.liveId;if(u.verified==='ok')return '';
  return `<section class="section"><h3>Vérification d'identité</h3><div class="card stack">${L&&L.status==='pending'?'<div class="note t-warn sm">Pièce reçue : l\'équipe Side by Side la vérifie (24 h ouvrées en général).</div>':`${L&&L.status==='refused'?`<div class="note t-bad sm">Pièce refusée${L.reason?' : '+esc(L.reason):''}. Déposez-en une nouvelle.</div>`:''}<p class="xs muted">Obligatoire avant toute prestation. Pièce d'identité ou passeport en cours de validité, puis un selfie. Fichiers privés, visibles uniquement par l'équipe de vérification, supprimés avec votre compte.</p>
  <form class="stack" data-form="live-id"><div class="field"><label for="id-doc">Pièce d'identité (photo ou PDF, 5 Mo max.)</label><input id="id-doc" name="doc" type="file" accept="image/jpeg,image/png,application/pdf"></div><div class="field"><label for="id-selfie">Selfie (photo de votre visage)</label><input id="id-selfie" name="selfie" type="file" accept="image/jpeg,image/png" capture="user"></div><p class="note t-bad sm" id="id-err" hidden></p><button class="btn pri full">Envoyer pour vérification</button></form>`}</div></section>`}
function liveDataCard(){return `<section class="section"><h3>Mes données personnelles</h3><div class="card stack"><p class="xs muted">Vous pouvez obtenir une copie de vos données ou supprimer votre compte. Les factures et écritures comptables sont conservées 10 ans (obligation légale), rattachées à un compte anonymisé.</p><button class="btn" data-a="live-export">Obtenir une copie de mes données</button><button class="btn bad" data-a="live-delete">Supprimer mon compte</button></div></section>`}
async function liveIdSubmit(f){const e=m=>{const p=document.getElementById('id-err');p.textContent=tr(m);p.hidden=false},doc=f.querySelector('[name=doc]').files[0],sf=f.querySelector('[name=selfie]').files[0];
  const okType=(x,pdf)=>x&&x.size<=5*1024*1024&&(/^image\/(jpeg|png)$/.test(x.type)||(pdf&&x.type==='application/pdf'));
  if(!okType(doc,true))return e('Pièce d\'identité : JPG, PNG ou PDF, 5 Mo maximum.');if(!okType(sf,false))return e('Selfie : JPG ou PNG, 5 Mo maximum.');
  const stamp=Date.now(),ext=x=>x.type==='application/pdf'?'pdf':x.type==='image/png'?'png':'jpg',dp=`${ME.id}/identite-${stamp}.${ext(doc)}`,sp=`${ME.id}/selfie-${stamp}.${ext(sf)}`;
  toast('Envoi en cours…');
  const u1=await SB.storage.from('documents').upload(dp,doc,{contentType:doc.type}),u2=await SB.storage.from('documents').upload(sp,sf,{contentType:sf.type});
  if(u1.error||u2.error)return toast('Envoi impossible. Vérifiez votre connexion.',true);
  const {error}=await SB.from('identity_checks').insert({user_id:ME.id,doc_path:dp,selfie_path:sp});
  if(error)return toast(/identity_one_pending/.test(error.message)?'Une vérification est déjà en cours.':'Envoi impossible. Réessayez.',true);
  toast('Documents envoyés. Vous serez prévenu(e) dès la vérification.');liveLoad()}

/* ---------- Paiement : Stripe (quand la clé publique est configurée) ---------- */
function stripeJs(){return window.Stripe?Promise.resolve(window.Stripe):new Promise((ok,ko)=>{const s=document.createElement('script');s.src='https://js.stripe.com/v3/';s.onload=()=>ok(window.Stripe);s.onerror=ko;document.head.appendChild(s)})}
async function livePayWith(secret,amount,label){const pk=SBS_CONFIG.stripePk;if(!pk)throw new Error('Le paiement en ligne sera disponible très bientôt.');
  const st=(await stripeJs())(pk),el=st.elements({clientSecret:secret,locale:S.lang||'fr'});
  open('livepay',{label,amount});render();const pe=el.create('payment');pe.mount('#livepay-el');
  S.livePay={st,el}}
async function livePayConfirm(){const P=S.livePay;if(!P)return;const btn=document.getElementById('livepay-go');if(btn)btn.disabled=true;
  const {error}=await P.st.confirmPayment({elements:P.el,redirect:'if_required'});
  if(error){toast(error.message||'Paiement refusé.',true);if(btn)btn.disabled=false;return}
  S.sheet=null;S.livePay=null;toast('Paiement reçu. Confirmation en cours…');setTimeout(liveLoad,1500)}

/* ---------- Branchement sur le serveur ---------- */
function liveBoot2(){
  const _mfa=mfa;mfa=()=>ME&&ME.role==='admin'?liveMfaHtml():_mfa();
  aDash=lAdmDash;aDisputes=lAdmDisputes;aVerif=lAdmUsers;aAudit=lAdmAudit;aSettings=lAdmSettings;
  ['aSupport','aDecisions','aGalReview','aExpReview','aBiz','aUsers','aAdmins','aPhotoTool'].forEach(n=>{window[n]=()=>''});
  const ok=(p,m)=>{liveDo(p,m);return{ok:1,msg:'Envoi…'}};
  const M=(b,action,extra)=>liveCall('mission-action',{booking_id:b.id,action,...extra});
  api.presence=(b)=>ok(M(b,'presence'),'Présence confirmée.');
  api.verifyCode=(b,code)=>{if(!/^\d{6}$/.test(String(code||'').replace(/\s/g,'')))return{err:'Saisissez les 6 chiffres du code.'};return ok(M(b,'verify_code',{code:String(code).replace(/\s/g,'')}),'Bonne rencontre confirmée.')};
  api.start=(b)=>ok(M(b,'start'),'Début validé.');
  api.declareEnd=(b)=>ok(M(b,'end'),'Fin confirmée.');
  api.requestExt=(b,mins)=>ok(M(b,'ext_request',{minutes:+mins}),'Demande de prolongation envoyée.');
  api.respondExt=(b,yes)=>ok(M(b,'ext_respond',{accept:!!yes}),yes?'Prolongation acceptée.':'Prolongation refusée.');
  api.payExt=(b)=>{M(b,'ext_pay').then(r=>livePayWith(r.client_secret,r.amount,'Prolongation '+b.ref)).catch(e=>tr_(e.message,true));return{ok:1,msg:'Préparation du paiement…'}};
  api.openDispute=(b,who,motif,desc,status)=>status==='incident'?ok(M(b,'interrupt'),'Mission interrompue. L\'équipe Side by Side est prévenue.'):(String(desc||'').trim().length<10?{err:'Décrivez le problème (10 caractères minimum).'}:ok(M(b,'dispute',{reason:motif,description:desc}),'Dossier ouvert. L\'équipe Side by Side vous répond sous 48 h.'));
  api.pay=(b)=>{liveCall('create-payment',{booking_id:b.id,gift_code:b.giftCode||null}).then(r=>{if(r.paid){toast('Réservation payée.');return liveLoad()}return livePayWith(r.client_secret,r.amount,'Réservation '+b.ref)}).catch(e=>tr_(e.message,true));return{ok:1,msg:'Préparation du paiement…'}};
  api.review=(b,who,stars,text)=>{const st=+stars;if(!(st>=1&&st<=5))return{err:'Choisissez une note de 1 à 5.'};
    SB.from('reviews').insert({booking_id:b.id,author_id:ME.id,target_id:realOf(who==='client'?b.companionId:b.clientId),stars:st,body:String(text||'').trim().slice(0,1000)||null}).then(({error})=>{toast(error?(/duplicate|unique/.test(error.message)?'Vous avez déjà donné votre avis.':'Avis impossible pour cette réservation.'):'Merci. Les deux avis sont publiés quand chacun a donné le sien.',!!error);if(!error)liveLoad()});return{ok:1,msg:'Envoi…'}};
  const _ch=liveSubscribe;liveSubscribe=()=>{const first=!LIVE_SUB;_ch();if(first&&LIVE_SUB&&SB.channel)SB.channel('sbs-n-'+ME.id).on('postgres_changes',{event:'INSERT',schema:'public',table:'notifications',filter:'user_id=eq.'+ME.id},p=>{const n=p.new;S.notifs.unshift({id:n.id,to:S.role,text:n.body,t:Date.parse(n.created_at),read:false,kind:n.kind,bid:n.booking_id});if(n.kind==='sos'&&S.role==='admin')toast(n.body,true);else toast(n.body);if(S.role==='admin'&&S.adminOk)liveAdminLoad();else render()}).subscribe()};
}
function liveSosTarget(el){return el.dataset.id||(S.sheet&&S.sheet.id)||null}
function liveClick2(a,el){
  if(a==='live-mfa-retry'){S.liveMfa=null;return true}
  if(a==='live-adm-refresh'){liveAdminLoad();return true}
  if(a==='live-adm-id'){const yes=el.dataset.v==='1';if(yes)admDo({action:'identity_review',check_id:el.dataset.id,approve:true},'Identité validée.');else{open('live-reason',{kind:'id',id:el.dataset.id})}return true}
  if(a==='live-adm-comp'){admDo({action:'companion_review',companion_id:el.dataset.id,approve:true,tier:el.dataset.v},'Profil validé et visible des clients.');return true}
  if(a==='live-adm-suspend'){open('live-reason',{kind:'suspend',id:el.dataset.id});return true}
  if(a==='notifs'){const ids=S.notifs.filter(n=>!n.read&&n.id).map(n=>n.id);if(ids.length)SB.from('notifications').update({read_at:new Date().toISOString()}).in('id',ids).then(()=>{});return false}
  if(a==='live-export'){liveCall('account',{action:'export'}).then(d=>{open('live-export',{json:JSON.stringify(d,null,2)});render()}).catch(e=>tr_(e.message,true));return true}
  if(a==='live-copy'){const t=S.sheet&&S.sheet.json||'';(navigator.clipboard?navigator.clipboard.writeText(t):Promise.reject()).then(()=>tr_('Copié.')).catch(()=>{const x=document.getElementById('lx-json');if(x){x.focus();x.select()}toast('Sélectionnez le texte pour le copier.')});return true}
  if(a==='live-delete'){open('live-delete');return true}
  if(a==='livepay-go'){livePayConfirm();return true}
  if(a==='sos-report'||a==='sos-contact'||a==='sos-loc'){const id=liveSosTarget(el),b=id&&S.bookings.find(x=>x.id===id);
    const send=(kind,pos)=>liveCall('sos',{booking_id:b?b.id:null,kind,...(pos||{})});
    if(a==='sos-report'){send('report').then(()=>tr_('Signalement prioritaire transmis à Side by Side.')).catch(e=>tr_(e.message,true));return true}
    if(a==='sos-loc'){if(!navigator.geolocation){toast('Position indisponible sur cet appareil.',true);return true}
      navigator.geolocation.getCurrentPosition(p=>send('location',{latitude:p.coords.latitude,longitude:p.coords.longitude}).then(()=>tr_('Position transmise à l\'équipe Side by Side.')).catch(e=>tr_(e.message,true)),()=>tr_('Autorisez l\'accès à la position dans les réglages du téléphone.',true),{enableHighAccuracy:true,timeout:15000});return true}
    const tc=(ME&&ME.trusted_contact)||'';send('contact').catch(()=>{});
    if(!tc){toast('Ajoutez d\'abord un contact de confiance dans Compte.',true);return true}
    const num=(tc.match(/\+?\d[\d\s.]{8,}/)||[''])[0].replace(/[\s.]/g,'');
    if(!num){toast('Le numéro du contact de confiance est introuvable.',true);return true}
    const msg=encodeURIComponent(`Alerte Side by Side : j'ai besoin d'aide${b?` (rendez-vous ${b.ref}, ${b.place})`:''}. Appelle-moi ou préviens le 112.`);
    location.href=`sms:${num}?body=${msg}`;toast('Votre application SMS s\'ouvre : envoyez le message.');return true}
  return false}
function liveSubmit2(k,f,d){
  if(k==='live-mfa'){const e=m=>{const p=document.getElementById('mfa-err');p.textContent=tr(m);p.hidden=false;return 'stop'},code=String(d.code||'').replace(/\D/g,'');
    if(code.length!==6)return e('Saisissez les 6 chiffres.');
    SB.auth.mfa.challengeAndVerify({factorId:S.liveMfa.factorId,code}).then(({error})=>{if(error)return e('Code invalide.');S.adminOk=true;S.liveMfa=null;liveAdminLoad()});return 'stop'}
  if(k==='live-adm-decide'){const note=String(d.note||'').trim();if(note.length<5){toast('Motivez la décision.',true);return 'stop'}
    admDo({action:'dispute_decide',dispute_id:f.dataset.id,decision:d.decision,refund_pct:+d.pct,note},'Décision enregistrée.');return 'stop'}
  if(k==='live-reason'){const r=String(d.reason||'').trim();if(r.length<5){toast('Indiquez un motif (5 caractères minimum).',true);return 'stop'}const s=S.sheet;S.sheet=null;
    if(s.kind==='id')admDo({action:'identity_review',check_id:s.id,approve:false,reason:r},'Pièce refusée, le membre est prévenu.');else admDo({action:'suspend',user_id:s.id,suspended:true,reason:r},'Compte suspendu.');return true}
  if(k==='live-id'){liveIdSubmit(f);return 'stop'}
  if(k==='live-delete'){if(String(d.confirm||'').trim()!=='SUPPRIMER'){toast('Écrivez SUPPRIMER pour confirmer.',true);return 'stop'}
    liveCall('account',{action:'delete',confirm:'SUPPRIMER'}).then(()=>{S.sheet=null;toast('Compte supprimé.');SB.auth.signOut()}).catch(e=>tr_(e.message,true));return 'stop'}
  return false}
function liveSheets(s,head){
  if(s.type==='live-reason')return `${head(s.kind==='id'?'Refuser la pièce d\'identité':'Suspendre le compte','Le membre est prévenu et peut contester.')}<form class="stack" data-form="live-reason"><div class="field"><label for="lr-r">Motif</label><textarea id="lr-r" name="reason" rows="3"></textarea></div><button class="btn ${s.kind==='id'?'pri':'bad'} full">Confirmer</button></form>`;
  if(s.type==='live-export')return `${head('Mes données','Copie complète de vos données Side by Side')}<textarea id="lx-json" class="sel" rows="14" readonly style="width:100%;font-family:monospace;font-size:.75rem">${esc(s.json)}</textarea><button class="btn pri full" data-a="live-copy">Copier</button>`;
  if(s.type==='live-delete')return `${head('Supprimer mon compte','Action définitive')}<p class="sm">Vos informations personnelles, pièces d'identité et photos sont supprimées. Impossible si une réservation est en cours.</p><form class="stack" data-form="live-delete"><div class="field"><label for="ld-c">Écrivez SUPPRIMER pour confirmer</label><input id="ld-c" name="confirm" autocomplete="off"></div><button class="btn bad full">Supprimer définitivement</button></form>`;
  if(s.type==='livepay')return `${head(esc(s.label),'Paiement sécurisé par Stripe')}<p class="sm">Montant : <b class="num">${eur(+s.amount)}</b></p><div id="livepay-el" style="min-height:120px"></div><button class="btn pri full big" id="livepay-go" data-a="livepay-go">Payer ${eur(+s.amount)}</button>`;
  return null}

/* ================= V1.6 — Galerie : photo de référence + 5 photos, validation puis verrouillage ================= */
const GAL_MAX=5;
function seedV17(){S.companions.forEach(c=>{c.gallery={photos:[],locked:c.id!=='c1',status:null}})}
function galOk(c){return c.gallery&&c.gallery.locked?c.gallery.photos.filter(p=>p.status==='ok'):[]}
function galHtml(c){const ph=galOk(c);
  if(ph.length)return `<div class="gallery g5">${ph.map(p=>`<div class="gtile"><img src="${p.src}" alt="Photo de ${esc(c.name)}"><i>Photo vérifiée</i></div>`).join('')}</div>`;
  if(PHOTOS[c.id])return `<div class="gallery g5"><div class="gtile">${face(c,'g0')}<i>Photo vérifiée</i></div></div>`;
  return `<div class="gallery">${[40,150,260].map((dh,i)=>`<div class="gtile">${face({...c,hue:(c.hue+dh)%360},'g'+i)}<i>Photo vérifiée</i></div>`).join('')}</div>`}
function pPhotoCard(){const c=comp('c1'),g=c.gallery,ref=c.photo,ph=g.photos,drafts=ph.filter(p=>p.status==='draft');
  const refPill=ref.status==='pending'?'<span class="pill t-warn">En attente de validation</span>':ref.status==='ok'?`<span class="pill t-ok">Photo vérifiée le ${fshort(ref.t)}</span>`:'<span class="pill t-bad">Refusée</span>';
  const step2=g.locked?`<div class="galgrid">${ph.filter(p=>p.status==='ok').map(p=>`<div class="gtile"><img src="${p.src}" alt=""></div>`).join('')}</div><div class="note t-ok sm"><b>Photos validées et verrouillées.</b> Pour toute modification, contactez l'assistance Side by Side.</div>`
    :ref.status!=='ok'?`<p class="sm muted">Disponible après la validation de votre photo de référence.</p>`
    :`<div class="galgrid">${ph.map(p=>`<div class="gtile"><img src="${p.src}" alt="">${p.status==='draft'?`<button class="gdel" data-a="gal-del" data-v="${p.id}" aria-label="Retirer cette photo">✕</button>`:''}${p.status==='pending'?'<i>En vérification</i>':''}</div>`).join('')}${ph.length<GAL_MAX&&g.status!=='pending'?`<label class="gadd"><input type="file" id="gal-up" accept="image/jpeg,image/png" multiple hidden><span>+</span><small>Ajouter</small></label>`:''}</div>
      <p class="xs muted">${ph.length} / ${GAL_MAX} photos · JPG ou PNG, 5 Mo maximum. Même règle que la photo de référence : réelles, récentes, sans retouche, vous uniquement.</p>
      ${g.status==='pending'?'<div class="note t-warn sm">En cours de comparaison avec votre photo de référence par l\'équipe Side by Side.</div>':drafts.length?`<button class="btn pri full" data-a="gal-send">Envoyer pour validation</button>`:''}`;
  return `<section class="section"><h3>Mes photos</h3>
  <div class="card stack"><div class="row"><span class="stepn">1</span><span class="lbl grow">Photo de référence (privée)</span>${refPill}</div>
   <div class="row" style="flex-wrap:nowrap;align-items:flex-start"><div class="gtile refthumb">${face(c,'ref')}</div><p class="xs muted grow">Prise avec l'appareil photo de l'application. Elle reste privée : seule l'équipe Side by Side la voit, pour vérifier que vos autres photos sont bien vous. Elle n'apparaît jamais sur votre profil.</p></div>
   ${videoOk(c)?VBADGE:''}${!g.locked?'<button class="btn" data-a="photo">Changer ma photo</button>':''}</div>
  <div class="card stack"><div class="row"><span class="stepn">2</span><span class="lbl grow">Photos visibles par les clients (jusqu'à 5)</span></div><p class="xs muted">Ces photos sont celles que voient les clients. La première devient votre photo principale.</p>${step2}</div></section>`}
function galUpload(el){const c=comp('c1'),g=c.gallery,files=[...(el.files||[])];el.value='';
  const room=GAL_MAX-g.photos.length;if(!room){toast('Maximum 5 photos.',true);render();return}
  let bad=0;const ok=files.filter(f=>{const v=/^image\/(jpeg|png)$/.test(f.type)&&f.size<=5*1024*1024;if(!v)bad++;return v}).slice(0,room);
  if(files.length>room)toast('Maximum 5 photos.',true);else if(bad)toast('Format refusé : JPG ou PNG, 5 Mo maximum.',true);
  let left=ok.length;if(!left){render();return}
  ok.forEach(f=>{const r=new FileReader();r.onload=()=>{g.photos.push({id:'p'+Date.now()+Math.random().toString(36).slice(2,6),src:r.result,status:'draft',t:now()});if(--left===0)render()};r.onerror=()=>{if(--left===0)render()};r.readAsDataURL(f)})}
function aGalReview(){const l=S.companions.filter(c=>c.gallery&&c.gallery.status==='pending');
  return `<section class="section"><h3>Photos supplémentaires à comparer</h3>${l.length?l.map(c=>`<form class="card stack" data-form="gal-review" data-cid="${c.id}"><div class="row"><b class="grow">${esc(c.name)}</b><span class="pill t-warn">${c.gallery.photos.filter(p=>p.status==='pending').length} photo(s)</span></div>
    <div class="galcmp"><div class="gtile">${face(c,'gr')}<i>Référence</i></div><div class="galgrid">${c.gallery.photos.filter(p=>p.status==='pending').map(p=>`<label class="gtile gpick"><img src="${p.src}" alt=""><input type="checkbox" name="ok" value="${p.id}" checked aria-label="Photo conforme"></label>`).join('')}</div></div>
    <p class="xs muted">Décochez les photos qui ne correspondent pas à la photo de référence. Une fois validées, les photos sont verrouillées.</p>
    <div class="pbar"><button class="btn pri">Valider et verrouiller</button><button class="btn bad" type="button" data-a="gal-reject" data-id="${c.id}">Tout refuser</button></div></form>`).join(''):'<div class="empty">Aucune série de photos à comparer.</div>'}</section>`}
function v17Click(a,el,id,v){const c1=comp('c1');switch(a){
  case'gal-del':c1.gallery.photos=c1.gallery.photos.filter(p=>p.id!==v);return true;
  case'gal-send':c1.gallery.photos.forEach(p=>{if(p.status==='draft')p.status='pending'});c1.gallery.status='pending';notify('admin','Photos supplémentaires à comparer : Camille.');log('Camille','Photos supplémentaires envoyées pour validation','—');toast('Photos envoyées. L\'équipe Side by Side les compare à votre photo de référence.');return true;
  case'gal-reject':{const c=comp(id);c.gallery.photos=c.gallery.photos.filter(p=>p.status!=='pending');c.gallery.status=null;log('Administrateur Side by Side',`Photos supplémentaires refusées : ${c.name}`,'—');if(c.id==='c1')notify('companion','Vos photos supplémentaires ont été refusées : elles ne correspondent pas à votre photo de référence.');toast('Photos refusées.');return true}
  default:return false}}
function v17Submit(k,f,fd){if(k!=='gal-review')return false;const c=comp(f.dataset.cid),keep=fd.getAll('ok');
  c.gallery.photos=c.gallery.photos.filter(p=>p.status!=='pending'||keep.includes(p.id));c.gallery.photos.forEach(p=>{if(p.status==='pending')p.status='ok'});
  c.gallery.status=null;c.gallery.locked=true;log('Administrateur Side by Side',`Photos validées et verrouillées : ${c.name} (${keep.length})`,'—');if(c.id==='c1')notify('companion','Vos photos ont été validées et sont maintenant verrouillées.');toast('Photos validées et verrouillées.');return true}

/* ================= V1.7 — Inscription pleine page ================= */
function newSu(){return{v:{type:'client',city:'Paris'},err:{},smsSent:false,code:null,step:'form',done:{id:false,photo:false,pro:false,iv:null}}}
const suv=k=>esc((S.su.v[k]??''));
function ferr(k){return S.su.err[k]?`<p class="ferr" role="alert">${S.su.err[k]}</p>`:''}
function fld(k,label,attrs,help){return `<div class="field"><label for="su-${k}">${label}</label><input id="su-${k}" name="${k}" value="${suv(k)}" ${attrs} ${S.su.err[k]?'aria-invalid="true"':''}>${help?`<span class="xs muted">${help}</span>`:''}${ferr(k)}</div>`}
function pageHead(title,back){return `<header class="pagehead"><button class="iconbtn" data-a="${back}" aria-label="Retour"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M15 5 8 12l7 7"/></svg></button><div class="mono sm" aria-hidden="true"><svg class="mark" viewBox="0 0 40 40" aria-hidden="true"><circle cx="14.5" cy="11" r="4.2"/><circle cx="25.5" cy="11" r="4.2"/><rect x="10.3" y="18" width="8.4" height="17" rx="4.2"/><rect x="21.3" y="18" width="8.4" height="17" rx="4.2"/></svg></div><b class="grow">${title}</b></header>`}
function signupPage(){const su=S.su;if(su.step==='email')return emailPage();if(su.step==='onboard')return onboardPage();
  const v=su.v,isC=v.type==='companion',isB=v.type==='biz',sec=(n,t,body)=>`<section class="sect"><div class="secth"><span class="stepn">${n}</span><h3>${t}</h3></div>${body}</section>`;
  return `<main class="page">${pageHead('Créer un compte','su-back')}
  <p class="muted sm">Quelques minutes suffisent. Tous les champs sont obligatoires.</p>
  <form class="stack" data-form="su" novalidate>
  ${sec(1,'Type de compte',`<div class="typecards">
    <label class="typecard ${!isC&&!isB?'on':''}"><input type="radio" name="type" value="client" ${!isC&&!isB?'checked':''}><span class="tc"><b>Client</b><small>Je réserve un accompagnateur pour une sortie, une visite, un dîner professionnel ou un événement.</small></span></label>
    <label class="typecard ${isC?'on':''}"><input type="radio" name="type" value="companion" ${isC?'checked':''}><span class="tc"><b>Accompagnateur</b><small>Je propose mes services d'accompagnement et je suis rémunéré(e) pour chaque prestation.</small></span></label>
    <label class="typecard ${isB?'on':''}"><input type="radio" name="type" value="biz" ${isB?'checked':''}><span class="tc"><b>Entreprise</b><small>Je réserve pour mes clients, partenaires ou événements, avec une facture mensuelle unique. Empreinte bancaire obligatoire.</small></span></label></div>`)}
  ${sec(2,'Identité',`${isB?bizFields():''}<div class="two">${fld('first','Prénom','autocomplete="given-name"')}${fld('last','Nom','autocomplete="family-name"')}</div>
    ${fld('dob','Date de naissance','type="date"','Service réservé aux personnes majeures (18 ans et plus).')}
    <div class="field"><label for="su-city">Ville</label><select id="su-city" name="city">${S.cities.filter(c=>c.on).map(c=>`<option ${v.city===c.city?'selected':''}>${esc(c.city)}</option>`).join('')}</select></div>`)}
  ${sec(3,'Coordonnées',`${fld('email','E-mail','type="email" autocomplete="email" inputmode="email"')}
    <div class="field"><label for="su-tel">Téléphone mobile</label><div class="row" style="flex-wrap:nowrap"><input id="su-tel" name="tel" value="${suv('tel')}" type="tel" autocomplete="tel" placeholder="06 12 34 56 78" style="flex:1;min-width:0" ${su.err.tel?'aria-invalid="true"':''}><button type="button" class="btn ${su.smsSent?'':'pri'}" data-a="su-sms">${su.smsSent?'Renvoyer':'Envoyer le code'}</button></div>${ferr('tel')}</div>
    ${su.smsSent?fld('sms','Code reçu par SMS','inputmode="numeric" maxlength="6" autocomplete="one-time-code"',`Code envoyé au ${esc(v.tel||'')}.`):''}`)}
  ${sec(4,'Mot de passe',`${fld('pw','Mot de passe','type="password" autocomplete="new-password"','10 caractères minimum, avec au moins une lettre et un chiffre.')}
    <div class="pwmeter" aria-hidden="true"><i id="pw-bar"></i></div>
    ${fld('pw2','Confirmez le mot de passe','type="password" autocomplete="new-password"')}<p class="xs" id="pw-match"></p>`)}
  ${!isC&&!isB?`<div class="card stack">${fld('ref','Code de parrainage (facultatif)','autocomplete="off" style="text-transform:uppercase"',`${eur(S.settings.refAmount||10)} offerts sur votre première réservation.`)}</div>`:''}
  ${sec(5,'Engagements',`<label class="row sm"><input type="checkbox" name="cgu" ${v.cgu?'checked':''}> <span>J'accepte les <button type="button" class="linkin" data-a="legal">conditions générales</button> et la politique de confidentialité</span></label>${ferr('cgu')}
    <label class="row sm"><input type="checkbox" name="charte" ${v.charte?'checked':''}> J'accepte la charte : aucun service intime ou sexuel, aucune activité illégale</label>${ferr('charte')}
    <label class="row sm"><input type="checkbox" name="adult" ${v.adult?'checked':''}> Je certifie avoir 18 ans ou plus</label>${ferr('adult')}
    ${isC?`<label class="row sm"><input type="checkbox" name="pro" ${v.pro?'checked':''}> Je m'engage à déclarer mes revenus (statut auto-entrepreneur ou équivalent)</label>${ferr('pro')}
    <label class="row sm"><input type="checkbox" name="photos" ${v.photos?'checked':''}> Je m'engage à publier uniquement des photos réelles de moi, sans retouche ni IA</label>${ferr('photos')}
    <label class="row sm"><input type="checkbox" name="nc" ${v.nc?'checked':''}> Je m'engage à ne pas proposer mes services en direct aux clients rencontrés via Side by Side pendant 12 mois</label>${ferr('nc')}`:''}
    ${isB?`<label class="row sm"><input type="checkbox" name="hold" ${v.hold?'checked':''}> J'accepte l'enregistrement d'une empreinte bancaire : chaque réservation est pré-autorisée et la facture mensuelle est prélevée sur cette carte</label>${ferr('hold')}
    <label class="row sm"><input type="checkbox" name="nc" ${v.nc?'checked':''}> L'entreprise s'engage à ne pas faire travailler directement un accompagnateur rencontré via Side by Side pendant 12 mois, sous peine de frais de mise en relation</label>${ferr('nc')}`:''}`)}
  ${Object.keys(su.err).length?'<div class="note t-bad sm">Corrigez les champs signalés en rouge.</div>':''}
  <button class="btn pri full big2">Créer mon compte</button>
  <p class="xs muted" style="text-align:center">Déjà inscrit(e) ? <button type="button" class="linkin" data-a="su-back">Se connecter</button></p></form></main>`}
function emailPage(){const v=S.su.v;return `<main class="page">${pageHead('Activer mon compte','su-edit')}
  <div class="bigicon"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/></svg></div>
  <h2 style="text-align:center">Vérifiez votre e-mail</h2><p class="sm muted" style="text-align:center">Un lien d'activation a été envoyé à <b class="sel">${esc(v.email)}</b>. Ouvrez-le pour activer votre compte, puis revenez dans l'application.</p>
  <div class="mailcard"><div class="row"><div class="mono sm" aria-hidden="true"><svg class="mark" viewBox="0 0 40 40" aria-hidden="true"><circle cx="14.5" cy="11" r="4.2"/><circle cx="25.5" cy="11" r="4.2"/><rect x="10.3" y="18" width="8.4" height="17" rx="4.2"/><rect x="21.3" y="18" width="8.4" height="17" rx="4.2"/></svg></div><div class="grow"><b>Side by Side</b><div class="xs muted">Activez votre compte</div></div><span class="xs muted">${fhm(now())}</span></div>
   <p class="sm">Bonjour ${esc(v.first)}, merci pour votre inscription. Touchez le bouton ci-dessous pour activer votre compte.</p><button class="btn pri full" data-a="su-activate">Activer mon compte</button></div>
  <div class="row" style="justify-content:center"><button class="btn ghost" data-a="su-resend">Renvoyer l'e-mail</button><button class="btn ghost" data-a="su-edit">Modifier l'adresse</button></div></main>`}
function onboardPage(){const su=S.su,v=su.v,d=su.done,isC=v.type==='companion',isB=v.type==='biz';
  const steps=isC?[['id','Vérifier mon identité','Photo de votre pièce d\'identité puis selfie vidéo, analysés par notre prestataire spécialisé.'],['photo','Photo de référence','Prise avec l\'appareil photo de l\'application. Elle reste privée et sert à vérifier vos photos de profil.'],['pro','Mon profil professionnel','Présentation, tarif horaire, langues et activités proposées.'],['iv','Entretien vidéo','10 minutes avec l\'équipe Side by Side, dans l\'application, pour valider votre profil.']]
    :[['id','Vérifier mon identité','Photo de votre pièce d\'identité puis selfie vidéo. Obligatoire avant toute réservation.'],...(isB?[['card','Empreinte bancaire','Carte de l\'entreprise enregistrée chez notre prestataire de paiement. Aucun débit à cette étape.']]:[])];
  const firstTodo=steps.findIndex(([k])=>!d[k]),all=firstTodo<0;
  const body=(k,i)=>{if(d[k])return k==='iv'?`<div class="xs" style="color:var(--ok)">✓ ${fdt(d.iv)}</div>`:'<div class="xs" style="color:var(--ok)">✓ Terminé</div>';if(i!==firstTodo)return '<div class="xs muted">Après l\'étape précédente</div>';
    if(k==='card')return `<div class="field"><label for="su-lim">Plafond mensuel</label><select id="su-lim">${[1000,2500,5000,10000].map(x=>`<option value="${x}" ${x===2500?'selected':''}>${eur(x)}</option>`).join('')}</select></div><div class="card row"><div class="mini" style="--h:45">V</div><div class="grow"><b class="sm">Visa •••• 4242</b><div class="xs muted">${esc(v.company||'')}</div></div></div><button class="btn pri" data-a="su-card">Enregistrer la carte</button>`;
    if(k==='id')return `<button class="btn pri" data-a="su-id">Commencer la vérification</button>`;
    if(k==='photo')return `<button class="btn pri" data-a="su-photo">Prendre ma photo de référence</button>`;
    if(k==='pro')return `<form class="stack" data-form="su-pro"><div class="field"><label for="pp-bio">Présentation</label><textarea id="pp-bio" name="bio" maxlength="400" placeholder="Votre parcours, ce que vous aimez faire découvrir"></textarea></div><div class="field"><label for="pp-rate">Tarif horaire (€)</label><input id="pp-rate" name="rate" type="number" min="10" max="1000" value="35"></div><span class="fl">Langues parlées</span><div class="days">${LANGS.map((l,j)=>`<label><input type="checkbox" name="lang" value="${l}" ${j===0?'checked':''}>${l}</label>`).join('')}</div><span class="fl">Activités proposées</span><div class="days">${S.cats.filter(x=>x.on&&x.id!=='prestige').map(x=>`<label><input type="checkbox" name="cat" value="${x.id}">${esc(x.name)}</label>`).join('')}</div><p class="note t-bad sm" id="pp-err" hidden></p><button class="btn pri">Enregistrer mon profil</button></form>`;
    if(k==='iv')return `<div class="row" style="flex-wrap:nowrap"><select id="su-iv" aria-label="Choisissez un créneau" style="flex:1;min-width:0">${interviewSlots().map(t=>`<option value="${t}">${fdt(t)}</option>`).join('')}</select><button class="btn pri" data-a="su-iv">Réserver</button></div>`};
  return `<main class="page">${pageHead('Finaliser mon inscription','su-back')}
  <div><span class="lbl" style="color:var(--gold)">Compte activé</span><h2>Bienvenue ${esc(v.first)}</h2><p class="sm muted">${isC?'Encore 4 étapes avant que votre profil soit visible par les clients.':isB?'Encore 2 étapes avant de pouvoir réserver.':'Une dernière étape avant de pouvoir réserver.'}</p></div>
  <ol class="onb">${steps.map(([k,t,x],i)=>`<li class="onbstep ${d[k]?'done':i===firstTodo?'cur':'lock'}"><span class="stepn">${d[k]?'✓':i+1}</span><div class="stack grow" style="gap:8px;min-width:0"><b>${t}</b><p class="xs muted">${x}</p>${body(k,i)}</div></li>`).join('')}</ol>
  ${all?(isC?`<div class="note t-ok sm"><b>Inscription terminée.</b> Votre profil sera visible par les clients dès la validation de votre entretien vidéo. Vous pourrez alors ajouter jusqu'à 5 photos depuis votre profil.</div><button class="btn pri full big2" data-a="su-enter" data-v="companion">Accéder à mon espace accompagnateur</button>`
    :`<div class="note t-ok sm"><b>Identité vérifiée.</b> Vous pouvez maintenant réserver.</div><button class="btn pri full big2" data-a="su-enter" data-v="client">${isB?'Accéder à mon espace entreprise':'Accéder à mon espace client'}</button>`):''}</main>`}
function suValidate(){const e=_suValidate();if(LIVE){delete e.sms;if(e.tel&&/Envoyer le code/.test(e.tel))delete e.tel}return e}
function _suValidate(){const v=S.su.v,e={},isC=v.type==='companion',isB=v.type==='biz';
  if(!/^[A-Za-zÀ-ÿ' -]{2,}$/.test((v.first||'').trim()))e.first='Indiquez votre prénom.';
  if(!/^[A-Za-zÀ-ÿ' -]{2,}$/.test((v.last||'').trim()))e.last='Indiquez votre nom.';
  if(!v.dob)e.dob='Indiquez votre date de naissance.';else{const b=new Date(v.dob),n=new Date(),age=n.getFullYear()-b.getFullYear()-((n.getMonth()<b.getMonth()||(n.getMonth()===b.getMonth()&&n.getDate()<b.getDate()))?1:0);if(age<18)e.dob='Inscription impossible : Side by Side est réservé aux personnes majeures.';else if(age>110)e.dob='Date de naissance invalide.'}
  if(!/^\S+@\S+\.\S{2,}$/.test(v.email||''))e.email='Adresse e-mail invalide.';
  if(!/^(?:\+33|0)[67]\d{8}$/.test((v.tel||'').replace(/[\s.-]/g,'')))e.tel='Numéro de mobile invalide (06 ou 07).';
  else if(!S.su.smsSent)e.tel='Touchez « Envoyer le code » pour vérifier votre numéro.';
  else if((v.sms||'').trim()!==S.su.code)e.sms='Code SMS incorrect.';
  const pw=v.pw||'';if(pw.length<10||!/[A-Za-z]/.test(pw)||!/\d/.test(pw))e.pw='10 caractères minimum, avec au moins une lettre et un chiffre.';
  if(!v.pw2)e.pw2='Confirmez votre mot de passe.';else if(v.pw2!==pw)e.pw2='Les deux mots de passe ne correspondent pas.';
  if(!v.cgu)e.cgu='Acceptez les conditions générales.';if(!v.charte)e.charte='Acceptez la charte.';if(!v.adult)e.adult='Ce service est réservé aux personnes majeures.';
  if(isB){if((v.company||'').trim().length<2)e.company='Indiquez la raison sociale.';if(!/^\d{14}$/.test((v.siret||'').replace(/\s/g,'')))e.siret='Le SIRET doit contenir 14 chiffres.';if(!v.hold)e.hold='L\'empreinte bancaire est obligatoire pour les comptes Entreprise.'}
  if((isC||isB)&&!v.nc)e.nc='Cet engagement est obligatoire.';
  if(!isC&&!isB&&(v.ref||'').trim()&&(v.ref||'').trim().toUpperCase()!==S.users.u1.refCode)e.ref='Code de parrainage inconnu.';
  if(isC&&!v.pro)e.pro='Cet engagement est obligatoire pour les accompagnateurs.';if(isC&&!v.photos)e.photos='Cet engagement est obligatoire pour les accompagnateurs.';
  return e}
function pwLive(){const v=S.su.v,pw=v.pw||'',bar=document.getElementById('pw-bar'),m=document.getElementById('pw-match');
  if(bar){const sc=(pw.length>=10)+/[A-Za-z]/.test(pw)+/\d/.test(pw)+/[^A-Za-z0-9]/.test(pw)+(pw.length>=14);bar.style.width=(sc*20)+'%';bar.dataset.l=sc<3?'low':sc<5?'mid':'ok'}
  if(m){if(!v.pw2){m.textContent='';m.className='xs'}else if(v.pw2===pw){m.textContent=tr('✓ Les mots de passe correspondent');m.className='xs ok'}else{m.textContent=tr('Les mots de passe ne correspondent pas encore');m.className='xs bad'}}}
function smsBanner(code){const old=document.getElementById('smsb');old&&old.remove();const d=document.createElement('div');d.id='smsb';d.className='smsbanner';d.setAttribute('role','status');
  d.innerHTML=`<b>SMS · Side by Side</b><span>${tr('Votre code de vérification')} : <span class="num">${code.replace(/(\d{3})/,'$1 ')}</span></span>`;document.body.appendChild(d);setTimeout(()=>d.remove(),9000)}
function v18Click(a,el,id,v){const su=S.su;switch(a){
  case'su-back':S.page=null;scrollTo(0,0);return true;
  case'su-edit':su.step='form';scrollTo(0,0);return true;
  case'su-sms':{const t=(su.v.tel||'').replace(/[\s.-]/g,'');if(!/^(?:\+33|0)[67]\d{8}$/.test(t)){su.err.tel=tr('Numéro de mobile invalide (06 ou 07).');return true}
    delete su.err.tel;su.smsSent=true;su.code=String(crypto.getRandomValues(new Uint32Array(1))[0]%900000+100000);setTimeout(()=>{smsBanner(su.code);const s=document.getElementById('su-sms');s&&s.focus()},50);return true}
  case'su-resend':toast('E-mail renvoyé.');return true;
  case'su-activate':su.step='onboard';scrollTo(0,0);toast('Compte activé.');log(su.v.first||'Nouveau membre','Compte créé et e-mail validé','—');return true;
  case'su-id':su.done.id=true;toast('Identité vérifiée.');return true;
  case'su-photo':open('photo',{st:0,onb:true});return true;
  case'su-iv':{const t=+document.getElementById('su-iv').value;su.done.iv=t;S.interviews.push({name:(su.v.first||'')+' '+(su.v.last||''),slot:t,status:'scheduled'});notify('admin',`Nouvel entretien vidéo prévu le ${fdt(t)}.`);toast('Entretien vidéo réservé.');return true}
  case'su-enter':S.page=null;if(su.v.type!=='companion'&&su.v.type!=='biz'&&(su.v.ref||'').trim())setTimeout(()=>toast(`${eur(S.settings.refAmount||10)} offerts sur votre première réservation grâce au parrainage.`),50);if(su.v.type==='biz'&&su.done.card)S.biz={name:su.v.company.trim(),siret:su.v.siret.replace(/\s/g,'').replace(/(\d{3})(\d{3})(\d{3})(\d{5})/,'$1 $2 $3 $4'),limit:su.done.limit||2500,card:'Visa •••• 4242'};S.role=v;S.tab='home';scrollTo(0,0);return true;
  default:return false}}
function v18Submit(k,f,fd,d){
  if(k==='su'){S.su.err=suValidate();if(Object.keys(S.su.err).length){Object.keys(S.su.err).forEach(x=>S.su.err[x]=tr(S.su.err[x]));render();const fe=document.querySelector('.ferr');fe&&fe.scrollIntoView({block:'center',behavior:'smooth'});return 'stop'}
    if(LIVE){const v=S.su.v;liveSignup(v).then(({error})=>{if(error){toast(/registered|already/i.test(error.message)?'Un compte existe déjà avec cet e-mail.':'Inscription impossible. Vérifiez vos informations.',true);return}S.su.step='email';scrollTo(0,0);render()});return 'stop'}
    S.su.step='email';scrollTo(0,0);return true}
  if(k==='su-pro'){const langs=fd.getAll('lang'),cats=fd.getAll('cat');if(!(d.bio||'').trim()||!langs.length||!cats.length||!(+d.rate>=10)){const p=document.getElementById('pp-err');p.textContent=tr('Remplissez la présentation, le tarif, au moins une langue et une activité.');p.hidden=false;return 'stop'}
    S.su.done.pro=true;toast('Profil enregistré.');return true}
  return false}

/* ---------- Événements ---------- */
function res(r){if(!r)return;if(r.err)toast(r.err,true);else if(r.msg)toast(r.msg)}
function open(type,data={}){S.sheet={type,...data}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-a]');if(!el)return;
  if(el.dataset.a==='scrim'&&e.target!==el)return;
  if(el.tagName==='INPUT'&&el.type==='checkbox'){e.stopPropagation()}
  const a=el.dataset.a,id=el.dataset.id,v=el.dataset.v,b=id&&S.bookings.find(x=>x.id===id),me=S.role==='client'?'client':'companion';
  if(LIVE&&liveClick(a,el)){render();return}
  switch(a){
  case'role':if(v==='client'&&S.users.u1.bio&&!S.role){S.lock={role:v};S.sheet=null;scrollTo(0,0);break}S.role=v;S.tab={client:'home',companion:'home',admin:'dashboard'}[v];S.sheet=null;break;
  case'leave':S.role=null;S.adminOk=false;S.sheet=null;break;
  case'logout':S.role=null;S.adminOk=false;S.sheet=null;scrollTo(0,0);toast('Vous êtes déconnecté(e).');break;
  case'tab':S.tab=v;scrollTo(0,0);break;
  case'theme':{const r=document.documentElement,cur=r.dataset.theme||'dark';r.dataset.theme=cur==='dark'?'light':'dark';return}
  case'notifs':open('notifs');S.notifs.forEach(n=>{if(n.to===S.role)n.read=true});break;
  case'close':case'scrim':S.sheet=null;break;
  case'signup':S.page='signup';S.su=newSu();S.sheet=null;scrollTo(0,0);break;
  case'clock-reset':S.offset=0;log('Outil de test','Horloge remise à l\'heure réelle','—');break;
  case'open-profile':open('profile',{cid:id});break;
  case'fav':S.favs=S.favs.includes(id)?S.favs.filter(x=>x!==id):[...S.favs,id];toast(S.favs.includes(id)?'Ajouté aux favoris.':'Retiré des favoris.');break;
  case'book':open('book',{cid:id});break;
  case'report-profile':S.flags.push({t:now(),type:'Profil signalé par un client',ref:'—',who:comp(id).name});notify('admin',`Profil de ${comp(id).name} signalé.`);S.sheet=null;toast('Merci, le profil est signalé à l\'équipe Side by Side.');break;
  case'accept':open('mission',{id});break;
  case'refuse':res(api.refuse(b));S.sheet=null;break;
  case'pay':open('pay',{id});break;
  case'pay-yes':res(api.pay(b));S.sheet=null;break;
  case'presence':res(api.presence(b,me));break;
  case'code':open('code',{id});break;
  case'start':open('startconf',{id:b.id});break;
  case'sos':open('sos',{id});break;
  case'sos-contact':{const u=S.users.u1;log(partyName(b,me),'SOS : contact de confiance alerté',b.ref);toast(me==='client'&&u.trusted?`Alerte envoyée à ${u.trusted}.`:'Alerte envoyée à votre contact de confiance.');return render()}
  case'sos-loc':if(me==='client'&&!S.users.u1.consentLoc){toast('Activez d\'abord le partage de position dans Compte.',true);return render()}log(partyName(b,me),'SOS : position partagée 60 min',b.ref);toast('Position partagée pendant 60 min avec votre contact et Side by Side.');return render();
  case'sos-report':S.flags.push({t:now(),type:'SOS : signalement',ref:b.ref,who:partyName(b,me)});notify('admin',`SOS signalé sur ${b.ref} par ${partyName(b,me)}.`);log(partyName(b,me),'SOS : signalement à la plateforme',b.ref);toast('Signalement prioritaire transmis à Side by Side.');return render();
  case'sos-stop':res(api.openDispute(b,me,'Incident de sécurité','Prestation interrompue via le bouton SOS pour raison de sécurité.','incident'));S.sheet=null;break;
  case'ext':open('ext',{id});break;
  case'ext-req':res(api.requestExt(b,+v));S.sheet=null;break;
  case'ext-yes':res(api.respondExt(b,true));break;
  case'ext-no':res(api.respondExt(b,false));break;
  case'pay-ext':res(api.payExt(b));break;
  case'end':open('endconf',{id:b.id});break;
  case'dispute':open('dispute',{id,motif:b.status==='double_attente'?'Désaccord sur la durée':''});break;
  case'absence':open('dispute',{id,motif:'Absence',st:'absence'});break;
  case'review':open('review',{id});break;
  case'cancel':open('confirm',{title:`Annuler ${b.ref} ?`,text:b.paid?`Le remboursement suit les conditions affichées lors de la réservation.`:'Aucun paiement n\'a été effectué.',yes:'cancel-yes',yesLabel:'Annuler la réservation',id});break;
  case'cancel-yes':res(api.cancel(b,me));S.sheet=null;break;
  case'chat':open('chat',{id});setTimeout(()=>{const m=document.getElementById('msgs');m&&(m.scrollTop=m.scrollHeight)});break;
  case'block':S.blocked=S.blocked.includes(id)?S.blocked.filter(x=>x!==id):[...S.blocked,id];log(partyName(b,me),S.blocked.includes(id)?'Conversation bloquée':'Conversation débloquée',b.ref);break;
  case'report-chat':S.flags.push({t:now(),type:'Conversation signalée',ref:b.ref,who:partyName(b,me==='client'?'companion':'client')});notify('admin',`Conversation ${b.ref} signalée.`);toast('Conversation signalée à Side by Side.');break;
  case'detail':open('detail',{id});break;
  case'j-h1':jump(b.start-H+M,'H-1 de '+b.ref);break;
  case'j-late':jump(b.start+16*M,'H+16 min de '+b.ref);break;
  case'j-end':jump(endOf(b)-14*M,'14 min avant la fin de '+b.ref);break;
  case'j-48':b.ends.client=b.ends.client||null;setStatus(b,'a_verifier','Système','48 h sans seconde confirmation');S.disputes.unshift({id:'D-'+(S.dseq++),bookingId:b.id,motif:'Fin non confirmée par les deux parties',openedBy:'Système',desc:'Une seule des deux parties a confirmé la fin dans le délai de 48 h.',evidence:['Historique horodaté'],status:'ouvert',opened:now(),deadline:now()+S.settings.disputeDays*DAY,decision:null,appealed:false});notify('admin',`${b.ref} passe en « À vérifier ».`);notify('client',`${b.ref} est à vérifier par l'équipe Side by Side.`);notify('companion',`${b.ref} est à vérifier par l'équipe Side by Side.`);toast('Statut « À vérifier » : un dossier est ouvert.');break;
  case'export':open('text',{title:'Export de mes données',sub:'Format JSON, conforme au droit à la portabilité.',text:JSON.stringify({compte:S.users.u1,reservations:S.bookings.filter(x=>x.clientId==='u1').map(({code,...r})=>r),favoris:S.favs,messages:Object.fromEntries(Object.entries(S.msgs).filter(([k])=>S.bookings.find(x=>x.id===k&&x.clientId==='u1')))},null,2)});log('Sophie','Export RGPD des données','—');break;
  case'delete-account':open('confirm',{title:'Supprimer le compte ?',text:'Vos données seront effacées, sauf celles que la loi impose de conserver (factures, litiges en cours). Action irréversible.',yes:'delete-yes',yesLabel:'Supprimer définitivement'});break;
  case'delete-yes':log('Sophie','Demande de suppression de compte','—');S.sheet=null;toast('Demande enregistrée. Votre compte sera supprimé sous 30 jours.');break;
  case'legal':open('legaldoc',{doc:'cgu'});break;
  case'copy':{const tx=document.getElementById('txt');navigator.clipboard.writeText(tx.value).then(()=>toast('Copié.')).catch(()=>{tx.select();toast('Texte sélectionné : copiez-le manuellement.')});return}
  case'payouts':S.bookings.filter(x=>x.status==='versement').forEach(x=>{S.ledger.push({t:now(),type:'Versement',ref:x.ref,amount:x.payout});setStatus(x,'cloturee','Administrateur Side by Side','versement exécuté');if(x.companionId==='c1')notify('companion',`Versement de ${eur(x.payout)} effectué pour ${x.ref}.`)});toast('Versements exécutés.');break;
  case'rev-ok':S.reviews[+v].status='publie';log('Administrateur Side by Side','Avis publié',S.reviews[+v].ref);break;
  case'rev-no':S.reviews[+v].status='masque';log('Administrateur Side by Side','Avis masqué',S.reviews[+v].ref);break;
  case'resolve':open('resolve',{did:v});break;
  case'verify':{const[k,i]=v.split(':'),o=k==='c'?comp(i):S.users[i];o.verified='ok';log('Administrateur Side by Side',`Identité validée : ${o.name}`,'—');toast(`${o.name} est vérifié(e).`);break}
  case'suspend':{const[k,i]=v.split(':'),o=k==='c'?comp(i):S.users[i];o.suspended=!o.suspended;log('Administrateur Side by Side',`${o.suspended?'Suspension':'Réactivation'} : ${o.name}`,'—');toast(`${o.name} ${o.suspended?'suspendu(e)':'réactivé(e)'}.`);break}
  case'prestige':{const c=comp(v);c.tier=c.tier==='Prestige'?'Standard':'Prestige';if(c.tier==='Prestige'&&!c.cats.includes('prestige'))c.cats.push('prestige');log('Administrateur Side by Side',`${c.name} : catégorie ${c.tier}`,'—');break}
  case'cat-toggle':{const c=S.cats.find(x=>x.id===v);c.on=el.checked;log('Administrateur Side by Side',`Catégorie ${c.name} ${c.on?'activée':'désactivée'}`,'—');return}
  case'city-toggle':{const c=S.cities[+v];c.on=el.checked;log('Administrateur Side by Side',`${c.city} ${c.on?'ouverte':'fermée'}`,'—');return}
  case'csv':{const rows=[['date','type','reference','montant_eur']].concat(S.ledger.slice().sort((a,b)=>a.t-b.t).map(l=>[new Date(l.t).toISOString(),l.type,l.ref,l.amount.toFixed(2)]));open('text',{title:'Export comptable',sub:'À rapprocher des relevés du prestataire de paiement.',text:rows.map(r=>r.join(';')).join('\n')});break}
  case'all-bookings':open('list');break;
  default:if(!extClick(a,el,id,v,b,me))return;
  }
  render()});
document.addEventListener('change',e=>{const el=e.target;
  if(extChange(el))return;
  if(el.id==='lang'){S.lang=el.value;render();return}
  if(el.dataset.f){S.filters[el.dataset.f]=el.dataset.f==='max'?+el.value:el.value;render()}});
document.addEventListener('input',e=>{const f=e.target.form;
  if(f&&f.dataset.form==='su'){const t=e.target;if(t.name){S.su.v[t.name]=t.type==='checkbox'?t.checked:t.value;if(t.name==='pw'||t.name==='pw2')pwLive();
    if(S.su.err[t.name]){delete S.su.err[t.name];t.removeAttribute('aria-invalid');const fe=t.type==='checkbox'?t.closest('label').nextElementSibling:t.closest('.field')&&t.closest('.field').querySelector('.ferr');if(fe&&fe.classList.contains('ferr'))fe.remove()}}return}
  if(e.target.id==='s-com'){document.getElementById('comv').textContent=e.target.value+' %'}
  if(f&&f.dataset.form==='book')bookPrice(f)});
document.addEventListener('change',e=>{const f=e.target.form;if(f&&f.dataset.form==='book'){bookRefresh(f,e.target.id);bookPrice(f)}if(f&&f.dataset.form==='modify')bookRefresh(f,e.target.id);});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,k=f.dataset.form,fd=new FormData(f),d=Object.fromEntries(fd),b=f.dataset.id&&S.bookings.find(x=>x.id===f.dataset.id),me=S.role==='client'?'client':'companion';
  const err=(id,m)=>{const p=document.getElementById(id);p.textContent=m;p.hidden=false};
  if(k==='mfa'){adminCheck(d.code).then(ok=>{if(ok){S.adminOk=true;S.mfaTries=0;log('Administrateur Side by Side','Connexion avec double authentification','—')}else{S.mfaTries++;log('Système',`Échec MFA administrateur (${S.mfaTries})`,'—');if(S.mfaTries>=5){S.role=null;S.mfaTries=0;toast('Trop d\'échecs : accès administrateur bloqué temporairement.',true)}else toast('Code invalide.',true)}render()});return}
  else if(k==='book'){const r=api.create(f.dataset.cid,{...d,exp:f.dataset.exp||null,extras:fd.getAll('extra'),needs:fd.getAll('pr_needs')});if(r.err)return err('book-err',r.err);S.sheet=null;S.tab='bookings';toast(r.msg)}
  else if(k==='code'){const r=api.verifyCode(b,d.code);if(r.ok)S.sheet=null;res(r)}
  else if(k==='dispute'){const r=api.openDispute(b,me,d.motif,d.desc,f.dataset.st||undefined);if(r.err)return err('d-err',r.err);S.sheet=null;toast(r.msg)}
  else if(k==='review'){const r=api.review(b,me,d.stars,d.text);if(r.err){toast(r.err,true);return}S.sheet=null;toast(r.msg)}
  else if(k==='msg'){const r=api.send(b,me,d.text||'');if(r.err){toast(r.err,true);return}render();const m=document.getElementById('msgs');m&&(m.scrollTop=m.scrollHeight);document.querySelector('[data-form=msg] input')?.focus();return}
  else if(k==='account'){S.users.u1.trusted=d.trusted||'';S.users.u1.consentLoc=!!d.loc;S.users.u1.bio=!!d.bio;S.users.u1.interests=fd.getAll('int');S.users.u1.notif=fd.getAll('nt');S.cur=d.cur||'EUR';log('Sophie','Paramètres de sécurité mis à jour','—');toast('Enregistré.')}
  else if(k==='cprofile'){const c=comp('c1'),rate=+d.rate,from=+d.from,to=+d.to;if(!(rate>=10&&rate<=1000)){toast('Tarif entre 10 et 1 000 €/h.',true);return}if(!(to>from)){toast('L\'heure de fin doit suivre l\'heure de début.',true);return}
    Object.assign(c,{incl:(d.incl||'').split('\n').map(x=>x.trim()).filter(Boolean),excl:(d.excl||'').split('\n').map(x=>x.trim()).filter(Boolean),rate,bio:d.bio,langs:fd.getAll('lang'),cats:[...fd.getAll('cat'),...(c.tier==='Prestige'?['prestige']:[])],days:fd.getAll('day').map(Number),from,to});log('Camille','Profil mis à jour','—');toast('Profil enregistré.')}
  else if(k==='settings'){const s=S.settings,n=x=>Math.max(0,Math.min(100,+x||0));{const n2=(x,v)=>Number.isFinite(+x)&&x!==''?Math.max(0,Math.min(30,+x)):v;s.clientFee=n2(d.clientFee,s.clientFee);s.compFee=n2(d.compFee,s.compFee);s.privFee=n2(d.privFee,s.privFee);s.privPrice=Math.max(0,+d.privPrice||s.privPrice)}s.minH=Math.max(1,+d.minH);s.maxH=Math.max(s.minH,+d.maxH);s.disputeDays=Math.max(1,+d.disputeDays);s.noShowPct=Math.max(0,Math.min(100,+d.noShowPct||0));Object.assign(s.cancel,{early:n(d.early),mid:n(d.mid),late:n(d.late),companion:n(d.companion),safety:n(d.safety)});log('Administrateur Side by Side',`Paramètres financiers : frais client ${s.clientFee} %, commission accompagnateur ${s.compFee} %`,'—');toast('Paramètres enregistrés. Ils s\'appliquent aux nouvelles réservations.')}
  else if(k==='addcity'){const ct=(d.city||'').trim().replace(/\s+/g,' '),co=(d.country||'').trim().replace(/\s+/g,' ');if(ct.length<2||co.length<2||/[<>"&{}]/.test(ct+co)||ct.length>40||co.length>40){toast('Indiquez la ville et le pays.',true);return}const cap=x=>x.charAt(0).toUpperCase()+x.slice(1);if(S.cities.some(x=>x.city.toLowerCase()===ct.toLowerCase())){toast('Cette ville existe déjà.',true);return}S.cities.push({city:cap(ct),country:cap(co),on:true});log('Administrateur Side by Side',`Ville ajoutée : ${cap(ct)} (${cap(co)})`,'—');toast('Ville ajoutée.')}
  else if(k==='addcat'){const nm=(d.name||'').trim();if(nm.length<3||nm.length>40||/[<>"&{}]/.test(nm)){toast('Nom trop court.',true);return}S.cats.push({id:'x'+Date.now(),name:nm,on:true});log('Administrateur Side by Side',`Catégorie ajoutée : ${nm}`,'—')}
  else if(k==='resolve'){const dsp=S.disputes.find(x=>x.id===f.dataset.v),bb=S.bookings.find(x=>x.id===dsp.bookingId);if(!d.note||d.note.trim().length<10)return err('r-err','Motivez la décision (10 caractères minimum).');
    const lab={refund:'Remboursement intégral du client',half:'Partage 50 / 50',pay:'Paiement intégral de l\'accompagnateur'}[d.dec];
    if(d.dec==='refund'){bb.refund=bb.total;bb.payout=0}else if(d.dec==='half'){bb.refund=r2(bb.total/2);bb.payout=r2(bb.payout/2)}else{bb.refund=0}
    if(bb.refund)S.ledger.push({t:now(),type:'Remboursement',ref:bb.ref,amount:-bb.refund});if(bb.payout)S.ledger.push({t:now(),type:'Versement',ref:bb.ref,amount:bb.payout});
    dsp.status='décidé';dsp.decision=`${lab}. ${d.note.trim()} (${fdt(now())})`;setStatus(bb,'cloturee','Administrateur Side by Side',`décision ${dsp.id} : ${lab}`);
    notify('client',`Décision rendue sur ${bb.ref} : ${lab}. Recours possible.`);notify('companion',`Décision rendue sur ${bb.ref} : ${lab}. Recours possible.`);S.sheet=null;toast('Décision enregistrée et notifiée.')}
  else if(k==='signup'){const st=S.sheet.step;
    if(st===1){if(!/^\S+@\S+\.\S+$/.test(d.email||''))return err('su-err','Adresse e-mail invalide.');if((d.pw||'').length<10)return err('su-err','Mot de passe : 10 caractères minimum.');S.sheet.kind=d.kind}
    if(st===2){if((d.tel||'').replace(/\D/g,'').length<9)return err('su-err','Numéro de téléphone invalide.');if(d.sms!=='123456')return err('su-err','Code SMS incorrect.')}
    if(st===3){if(!d.dob)return err('su-err','Indiquez votre date de naissance.');const dob=new Date(d.dob),n=new Date(),age=n.getFullYear()-dob.getFullYear()-((n.getMonth()<dob.getMonth()||(n.getMonth()===dob.getMonth()&&n.getDate()<dob.getDate()))?1:0);if(age<18)return err('su-err','Inscription impossible : Side by Side est réservé aux personnes majeures.')}
    if(st===4&&!d.consent)return err('su-err','Acceptez la politique de confidentialité et les CGU.');
    S.sheet.step=st+1}
  else if(extSubmit(k,f,fd,d,b,me)==='stop')return;
  render()});

seed();liveBoot();if(!LIVE)render();setInterval(()=>{if(!S.sheet&&S.role)render()},30000);
setTimeout(()=>{const sp=document.getElementById('splash');if(!sp)return;sp.classList.add('out');setTimeout(()=>sp.remove(),550)},1100);
